function initAudio() {
  if (soundState.ctx) {
    return;
  }

  const AudioContext = window.AudioContext || window.webkitAudioContext;
  if (!AudioContext) {
    soundState.muted = true;
    return;
  }

  soundState.ctx = new AudioContext();
}

function setMuted(isMuted) {
  soundState.muted = isMuted;
  localStorage.setItem("cardsAgainstAiMuted", String(isMuted));
  updateSoundButton();
  if (!isMuted) {
    initAudio();
    preloadSfxAudioAssets();
    startMusic();
    playSound("click");
  } else {
    soundState.musicUnlocked = false;
    if (soundState.sfxPreloadIdleId && "cancelIdleCallback" in window) {
      window.cancelIdleCallback(soundState.sfxPreloadIdleId);
    }
    soundState.sfxPreloadIdleId = null;
    disarmMusicUnlockListeners();
    stopMusic();
    stopTimerTick();
  }
}

function updateSoundButton() {
  [
    elements.soundToggleButton,
    elements.menuSoundToggleButton,
    elements.roomSoundToggleButton,
    elements.joinSoundToggleButton,
    elements.lobbySoundToggleButton
  ].forEach((button) => {
    if (!button) {
      return;
    }
    button.textContent = soundState.muted ? "Sound Off" : "Sound On";
    button.setAttribute("aria-pressed", String(!soundState.muted));
  });
}

function ensureMusicAudio(preload = "auto") {
  if (soundState.musicAudio) {
    if (preload === "auto" && soundState.musicAudio.preload !== "auto") {
      soundState.musicAudio.preload = "auto";
    }
    return soundState.musicAudio;
  }
  soundState.musicAudio = new Audio(audioAssets.music);
  soundState.musicAudio.loop = true;
  soundState.musicAudio.preload = preload;
  soundState.musicAudio.addEventListener("error", () => {
    soundState.musicUnlocked = false;
    soundState.musicAudio = null;
    armMusicUnlockListeners();
  });
  return soundState.musicAudio;
}

function preloadMusicAudio() {
  if (soundState.muted || soundState.musicVolume <= 0 || soundState.musicPreloadStarted) {
    return;
  }
  const audio = ensureMusicAudio("auto");
  soundState.musicPreloadStarted = true;
  try {
    audio.load();
  } catch {}
}

function primeAudioPlayback() {
  if (soundState.muted) {
    return;
  }

  initAudio();
  if (soundState.ctx?.state === "suspended") {
    soundState.ctx.resume().catch(() => {});
  }
  preloadSfxAudioAssets();
  startMusic();
}

function armMusicUnlockListeners() {
  window.addEventListener("pointerdown", primeAudioPlayback, { passive: true });
  window.addEventListener("click", primeAudioPlayback, { passive: true });
  window.addEventListener("touchstart", primeAudioPlayback, { passive: true });
  window.addEventListener("keydown", primeAudioPlayback);
}

function disarmMusicUnlockListeners() {
  window.removeEventListener("pointerdown", primeAudioPlayback);
  window.removeEventListener("click", primeAudioPlayback);
  window.removeEventListener("touchstart", primeAudioPlayback);
  window.removeEventListener("keydown", primeAudioPlayback);
}

function playTone(frequency, duration = 0.12, type = "sine", gainValue = 0.05, delay = 0) {
  if (soundState.muted) {
    return;
  }

  initAudio();
  const ctx = soundState.ctx;
  if (!ctx) {
    return;
  }

  const start = ctx.currentTime + delay;
  const oscillator = ctx.createOscillator();
  const gain = ctx.createGain();
  const effectiveGain = Math.max(0.0001, gainValue * getScaledSfxVolume());
  oscillator.type = type;
  oscillator.frequency.setValueAtTime(frequency, start);
  gain.gain.setValueAtTime(0.0001, start);
  gain.gain.exponentialRampToValueAtTime(effectiveGain, start + 0.015);
  gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);
  oscillator.connect(gain);
  gain.connect(ctx.destination);
  oscillator.start(start);
  oscillator.stop(start + duration + 0.02);
}

function getScaledSfxVolume() {
  const raw = Math.max(0, Math.min(1, soundState.sfxVolume || 0));
  if (raw <= 0) {
    return 0;
  }
  return Math.min(2.2, Math.pow(raw, 0.72) * 1.65);
}

function getPreloadableSfxSources() {
  const prioritySources = [
    audioAssets.zapLosePoints,
    audioAssets.explodeLosePoints,
    audioAssets.burningLosePoints,
    audioAssets.genericLosePoint,
    audioAssets.glitchOverlay,
    audioAssets.bountyRound,
    audioAssets.suddenDeath,
    audioAssets.lightOff,
    audioAssets.noMercy,
    audioAssets.blackMarket,
    audioAssets.dice,
    audioAssets.roulette,
    audioAssets.warning,
    audioAssets.ticking
  ].filter(Boolean);
  const remainingSources = Object.entries(audioAssets)
    .filter(([key]) => key !== "music")
    .map(([, src]) => src);
  return [...new Set([...prioritySources, ...remainingSources])];
}

function decodeAudioData(ctx, arrayBuffer) {
  try {
    const decodeResult = ctx.decodeAudioData(arrayBuffer.slice(0));
    if (decodeResult?.then) {
      return decodeResult;
    }
  } catch (error) {
    // Older Web Audio implementations use the callback form below.
  }
  return new Promise((resolve, reject) => {
    ctx.decodeAudioData(arrayBuffer.slice(0), resolve, reject);
  });
}

function preloadSfxBuffer(src) {
  if (!src || soundState.sfxBuffers.has(src)) {
    return Promise.resolve(soundState.sfxBuffers.get(src) || null);
  }
  if (soundState.sfxBufferPromises.has(src)) {
    return soundState.sfxBufferPromises.get(src);
  }

  initAudio();
  if (!soundState.ctx || typeof fetch !== "function") {
    return Promise.resolve(null);
  }

  const promise = fetch(src)
    .then((response) => {
      if (!response.ok) {
        throw new Error(`Audio preload failed: ${response.status}`);
      }
      return response.arrayBuffer();
    })
    .then((arrayBuffer) => decodeAudioData(soundState.ctx, arrayBuffer))
    .then((buffer) => {
      soundState.sfxBuffers.set(src, buffer);
      soundState.sfxBufferPromises.delete(src);
      return buffer;
    })
    .catch(() => {
      soundState.sfxBufferPromises.delete(src);
      return null;
    });

  soundState.sfxBufferPromises.set(src, promise);
  return promise;
}

function preloadSfxAudioAssets() {
  if (soundState.muted) {
    return Promise.resolve([]);
  }
  if (soundState.sfxPreloadPromise) {
    return soundState.sfxPreloadPromise;
  }
  if (soundState.sfxPreloadStarted) {
    return Promise.resolve([]);
  }
  initAudio();
  if (!soundState.ctx) {
    return Promise.resolve([]);
  }
  soundState.sfxPreloadStarted = true;
  const sources = getPreloadableSfxSources();
  soundState.sfxPreloadPromise = Promise.allSettled(
    sources.map((source) => preloadSfxBuffer(source))
  ).then((results) => results.map((result) => result.status === "fulfilled" ? result.value : null));
  return soundState.sfxPreloadPromise;
}

function playBufferedAudioFile(src, volume = 1, options = {}) {
  if (soundState.muted || options.loop || options.ignoreSettings) {
    return null;
  }
  const ctx = soundState.ctx;
  const buffer = ctx && soundState.sfxBuffers.get(src);
  if (!ctx || !buffer) {
    preloadSfxBuffer(src);
    return null;
  }

  const effectiveVolume = volume * getScaledSfxVolume();
  if (effectiveVolume <= 0) {
    return null;
  }
  const source = ctx.createBufferSource();
  const gain = ctx.createGain();
  source.buffer = buffer;
  gain.gain.value = Math.min(2.2, effectiveVolume);
  source.connect(gain);
  gain.connect(ctx.destination);
  const node = { source, gain };
  soundState.activeAudioNodes.add(node);
  source.addEventListener("ended", () => {
    soundState.activeAudioNodes.delete(node);
  }, { once: true });
  source.start();
  return source;
}

function playAudioFile(src, volume = 1, options = {}) {
  if (soundState.muted) {
    return null;
  }

  initAudio();
  const buffered = playBufferedAudioFile(src, volume, options);
  if (buffered) {
    return buffered;
  }

  const audio = new Audio(src);
  audio.preload = "auto";
  audio.loop = Boolean(options.loop);
  const effectiveVolume = options.ignoreSettings ? volume : volume * getScaledSfxVolume();
  if (!options.ignoreSettings && effectiveVolume > 1) {
    initAudio();
    if (soundState.ctx) {
      const source = soundState.ctx.createMediaElementSource(audio);
      const gain = soundState.ctx.createGain();
      gain.gain.value = Math.min(2.2, effectiveVolume);
      source.connect(gain);
      gain.connect(soundState.ctx.destination);
      soundState.activeAudioNodes.add({ audio, source, gain });
      audio.addEventListener("ended", () => {
        soundState.activeAudioNodes.forEach((entry) => {
          if (entry.audio === audio) {
            soundState.activeAudioNodes.delete(entry);
          }
        });
      }, { once: true });
      audio.volume = 1;
    } else {
      audio.volume = 1;
    }
  } else {
    audio.volume = Math.max(0, Math.min(1, effectiveVolume));
  }
  audio.play().catch(() => {
    // Browser audio permissions can block playback before a user gesture.
  });
  return audio;
}

function getScaledMusicVolume(volume = soundState.musicVolume) {
  const raw = Math.max(0, Math.min(1, volume || 0));
  return Math.min(0.26, Math.pow(raw, 1.2) * 0.26);
}

function setMusicElementVolume(volume) {
  if (soundState.musicAudio) {
    soundState.musicAudio.volume = getScaledMusicVolume(volume);
  }
}

function cancelMusicDuck() {
  if (soundState.musicDuckFrame) {
    cancelAnimationFrame(soundState.musicDuckFrame);
    soundState.musicDuckFrame = null;
  }
}

function duckMusicForTimer() {
  if (soundState.muted || !soundState.musicAudio || soundState.musicVolume <= 0) {
    return;
  }

  cancelMusicDuck();
  const normalVolume = soundState.musicVolume;
  const startVolume = normalVolume * 0.45;
  const duration = 6000;
  const startedAt = performance.now();
  setMusicElementVolume(startVolume);

  const step = (now) => {
    const progress = Math.min(1, (now - startedAt) / duration);
    const eased = 1 - ((1 - progress) ** 3);
    setMusicElementVolume(startVolume + ((normalVolume - startVolume) * eased));
    if (progress < 1 && !soundState.muted) {
      soundState.musicDuckFrame = requestAnimationFrame(step);
    } else {
      soundState.musicDuckFrame = null;
      setMusicElementVolume(soundState.musicVolume);
    }
  };

  soundState.musicDuckFrame = requestAnimationFrame(step);
}

function stopTimerTick() {
  if (soundState.timerWarningRampId) {
    cancelAnimationFrame(soundState.timerWarningRampId);
    soundState.timerWarningRampId = null;
  }

  if (soundState.timerTickAudio) {
    soundState.timerTickAudio.pause();
    soundState.timerTickAudio.currentTime = 0;
    soundState.timerTickAudio = null;
  }

  if (soundState.timerWarningAudio) {
    soundState.timerWarningAudio.pause();
    soundState.timerWarningAudio.currentTime = 0;
    soundState.timerWarningAudio = null;
  }
}

function setTimerWarningVolume(volume) {
  const safeVolume = Math.max(0, Math.min(1, volume));
  if (soundState.timerWarningAudio) {
    soundState.timerWarningAudio.volume = safeVolume;
  }
  if (soundState.timerTickAudio) {
    soundState.timerTickAudio.volume = safeVolume;
  }
}

function getTimerWarningVolume(remainingSeconds = state.timerRemaining) {
  const remaining = Math.max(0, Math.min(10, Number(remainingSeconds) || 0));
  const progress = (10 - remaining) / 10;
  const eased = progress ** 1.35;
  return 0.18 + (0.82 * eased);
}

function updateTimerWarningVolume(remainingSeconds = state.timerRemaining) {
  if (!soundState.timerWarningAudio && !soundState.timerTickAudio) {
    return;
  }
  setTimerWarningVolume(getTimerWarningVolume(remainingSeconds));
}

function playTimerWarningAudio() {
  stopTimerTick();
  const startVolume = getTimerWarningVolume(10);
  soundState.timerWarningAudio = playAudioFile(audioAssets.warning, startVolume, { ignoreSettings: true });
  soundState.timerTickAudio = playAudioFile(audioAssets.ticking, startVolume, { ignoreSettings: true, loop: true });
  const startedAt = performance.now();
  const rampDuration = 9500;
  const ramp = (now) => {
    const progress = Math.min(1, (now - startedAt) / rampDuration);
    const eased = progress ** 1.35;
    setTimerWarningVolume(0.18 + (0.82 * eased));
    if (progress < 1 && (soundState.timerWarningAudio || soundState.timerTickAudio)) {
      soundState.timerWarningRampId = requestAnimationFrame(ramp);
    } else {
      soundState.timerWarningRampId = null;
    }
  };
  soundState.timerWarningRampId = requestAnimationFrame(ramp);
  duckMusicForTimer();
}

function playSound(name) {
  const sounds = {
    click: () => playAudioFile(audioAssets.genericClick, 0.9),
    targetSelect: () => playAudioFile(audioAssets.selectTarget, 0.95),
    pointGain: () => playAudioFile(audioAssets.gainPoints, 0.9),
    coin: () => playAudioFile(audioAssets.gainPoints, 0.95),
    correctAnswer: () => playAudioFile(audioAssets.correctAnswer, 0.95),
    wrongAnswer: () => playAudioFile(audioAssets.wrongAnswer, 0.95),
    genericLosePoint: () => playAudioFile(audioAssets.genericLosePoint, 0.9),
    burnLoss: () => playAudioFile(audioAssets.burningLosePoints, 0.9),
    glitch: () => playAudioFile(audioAssets.glitchOverlay, 0.9),
    bombLoss: () => playAudioFile(audioAssets.explodeLosePoints, 0.9),
    zapLoss: () => playAudioFile(audioAssets.zapLosePoints, 0.9),
    bountyRound: () => playAudioFile(audioAssets.bountyRound, 0.95),
    suddenDeath: () => playAudioFile(audioAssets.suddenDeath, 0.95),
    lightOff: () => playAudioFile(audioAssets.lightOff, 0.95),
    noMercy: () => playAudioFile(audioAssets.noMercy, 0.95),
    blackMarket: () => playAudioFile(audioAssets.blackMarket, 0.95),
    dice: () => playAudioFile(audioAssets.dice, 0.95),
    roulette: () => playAudioFile(audioAssets.roulette, 0.95),
    gearSpin: () => playAudioFile(audioAssets.gearSpin, 0.9),
    switchCards: () => playAudioFile(audioAssets.switchCards, 0.9),
    reveal: () => {
      playTone(240, 0.08, "sine", 0.035);
      playTone(480, 0.12, "triangle", 0.04, 0.06);
    },
    submit: () => {
      playTone(180, 0.08, "square", 0.025);
      playTone(340, 0.1, "triangle", 0.035, 0.05);
    },
    lock: () => {
      playTone(440, 0.08, "triangle", 0.035);
      playTone(220, 0.08, "sine", 0.025, 0.06);
    },
    type: () => playTone(720, 0.025, "square", 0.011),
    timerWarning: () => playTimerWarningAudio(),
    judge: () => {
      playTone(160, 0.18, "sawtooth", 0.025);
      playTone(120, 0.22, "sine", 0.02, 0.08);
    },
    fly: () => {
      playTone(420, 0.1, "triangle", 0.04);
      playTone(760, 0.16, "triangle", 0.035, 0.08);
    },
    score: () => {
      playAudioFile(audioAssets.gainPoints, 0.9);
    },
    streak: () => {
      playTone(300, 0.08, "sawtooth", 0.035);
      playTone(600, 0.1, "triangle", 0.04, 0.05);
      playTone(900, 0.16, "triangle", 0.04, 0.12);
    },
    matchEnd: () => {
      playTone(392, 0.12, "triangle", 0.04);
      playTone(523, 0.14, "triangle", 0.04, 0.1);
      playTone(784, 0.2, "sine", 0.04, 0.22);
    },
    error: () => playTone(120, 0.18, "sawtooth", 0.025)
  };

  if (sounds[name]) {
    soundState.lastSfxAt = performance.now();
    sounds[name]();
  }
}

function playFallbackClickIfSilent(event) {
  const clickable = event.target.closest("button, .power-card, .target-option, .chat-message.clickable-profile");
  if (!clickable || clickable.disabled || clickable.getAttribute("aria-disabled") === "true") {
    return;
  }
  const clickStartedAt = performance.now();
  window.setTimeout(() => {
    if ((soundState.lastSfxAt || 0) < clickStartedAt) {
      playSound("click");
    }
  }, 0);
}

function startMusic() {
  if (soundState.muted || soundState.musicVolume <= 0) {
    return;
  }

  ensureMusicAudio("auto");

  setMusicElementVolume(soundState.musicVolume);
  soundState.musicAudio.play()
    .then(() => {
      soundState.musicUnlocked = true;
      disarmMusicUnlockListeners();
    })
    .catch(() => {
      soundState.musicUnlocked = false;
      armMusicUnlockListeners();
    });
}

function startOpeningMusic() {
  if (soundState.musicAutoStartAttempted || soundState.muted || soundState.musicVolume <= 0) {
    return;
  }
  soundState.musicAutoStartAttempted = true;
  preloadMusicAudio();
  startMusic();
}

function stopMusic() {
  cancelMusicDuck();
  if (soundState.musicAudio) {
    soundState.musicAudio.pause();
  }
}

function updateMusicVolume() {
  cancelMusicDuck();
  setMusicElementVolume(soundState.musicVolume);

  if (!soundState.muted && soundState.musicVolume > 0) {
    startMusic();
  }

  if (soundState.musicVolume === 0) {
    stopMusic();
  }
}

function cleanInput(input) {
  return input
    .trim()
    .replace(/\s+/g, " ")
    .replace(/[.?!]+$/g, "")
    .slice(0, 80);
}

function cleanAnswerDraft(input) {
  return String(input || "")
    .replace(/\s+/g, " ")
    .slice(0, 80);
}

function clearSpectatorAnswerDraftState() {
  state.spectatorAnswerDrafts = {};
  state.lastBroadcastAnswerDraft = "";
  if (state.answerDraftBroadcastTimerId) {
    window.clearTimeout(state.answerDraftBroadcastTimerId);
    state.answerDraftBroadcastTimerId = null;
  }
}

function isMultipleChoiceRound() {
  return state.questionStyle === MULTIPLE_CHOICE_STYLE;
}

function normalizeMultipleChoiceOption(answer) {
  return normalizeTriviaAnswer(cleanInput(answer));
}

function getCurrentMultipleChoiceOptions() {
  const options = Array.isArray(state.multipleChoiceOptions) ? state.multipleChoiceOptions : [];
  const unique = [];
  const seen = new Set();
  options.forEach((answer) => {
    const cleanAnswer = cleanInput(String(answer || ""));
    const key = normalizeMultipleChoiceOption(cleanAnswer);
    if (cleanAnswer && key && !seen.has(key)) {
      seen.add(key);
      unique.push(cleanAnswer);
    }
  });
  return unique.slice(0, 4);
}

function isMultipleChoiceAnswerCorrect(answer) {
  const correct = normalizeMultipleChoiceOption(state.canonicalAnswer);
  return Boolean(correct && normalizeMultipleChoiceOption(answer) === correct);
}

function isHintSupportedForCurrentQuestion() {
  return Boolean(
    isMultipleChoiceRound()
      || String(state.canonicalAnswer || "").trim()
  );
}

function getHintMatchId() {
  return getCurrentRoomMatchId() || `local-${state.matchWorkToken}`;
}

function resetHintStateForMatch(matchId = getHintMatchId()) {
  const normalizedMatchId = String(matchId || "").trim();
  const freeRemaining = state.mode === "bots" ? 3 : state.mode === "room" ? 1 : 0;
  state.hintState = {
    matchId: normalizedMatchId,
    freeRemaining,
    purchasesUsed: 0,
    usedThisRound: false,
    usedRounds: {},
    pending: false
  };
  state.roundHintUsage = {};
}

function normalizeHintState(source = {}, fallbackMatchId = getHintMatchId()) {
  const value = source && typeof source === "object" ? source : {};
  const usedRounds = value.usedRounds && typeof value.usedRounds === "object" ? value.usedRounds : {};
  return {
    matchId: String(value.matchId || fallbackMatchId || "").trim(),
    freeRemaining: Math.max(0, Math.floor(Number(value.freeRemaining) || 0)),
    purchasesUsed: Math.max(0, Math.floor(Number(value.purchasesUsed) || 0)),
    usedThisRound: Boolean(value.usedThisRound),
    usedRounds: Object.fromEntries(Object.entries(usedRounds).filter(([, used]) => Boolean(used)).slice(-100)),
    pending: false
  };
}

function getHintRoundKey(round = state.round) {
  return `${getHintMatchId()}:${Number(round) || 0}`;
}

function buildTextHint(answer = "") {
  const words = String(answer || "").trim().split(/\s+/).filter(Boolean);
  return words.map((word) => {
    let revealed = false;
    return Array.from(word).map((character) => {
      if (/\p{L}|\p{N}/u.test(character)) {
        if (!revealed) {
          revealed = true;
          return character.toLocaleUpperCase();
        }
        return "_";
      }
      return character;
    }).join(" ");
  }).join("   ");
}

function getHintAvailability() {
  const hintState = normalizeHintState(state.hintState);
  const roundKey = getHintRoundKey();
  const supported = isHintSupportedForCurrentQuestion();
  const usedThisRound = Boolean(state.roundHintUsage[state.currentOwner])
    || Boolean(hintState.usedRounds[roundKey])
    || Boolean(hintState.usedThisRound);
  const isMultiplayer = isRoomMode();
  const hasFree = hintState.freeRemaining > 0;
  const hasPurchase = isMultiplayer && hintState.purchasesUsed < 2 && loadCurrencyBalance() >= 5;
  return {
    hintState,
    supported,
    usedThisRound,
    hasFree,
    hasPurchase,
    available: Boolean(supported && (hasFree || hasPurchase) && !usedThisRound)
  };
}

function renderMolotovControls() {
  const button = elements.molotovButton;
  if (!button) {
    return;
  }
  const owner = getCurrentPowerOwner();
  const stacks = getEffectStackCount(state.molotovOwners?.[owner]);
  const visible = Boolean(
    stacks > 0
      && !state.isSpectator
      && !state.matchEnded
      && isAnswerInputLive()
      && elements.verdictPanel.classList.contains("hidden")
      && elements.endPanel.classList.contains("hidden")
  );
  setHidden(button, !visible);
  if (!visible) {
    return;
  }
  const used = Number(state.molotovUsedRounds?.[owner]) === Number(state.round);
  const hasTargets = getTargetCandidates(owner, getPowerById(`cocktail_mix${chaosInfusedPowerSuffix}`)).length > 0;
  const disabled = used || !hasTargets || isClassicModeEnabled() || isTableEventActive("power_outage");
  button.disabled = disabled;
  button.classList.toggle("molotov-used", used);
  const tooltip = used
    ? "Molotov Cocktail already used this round."
    : "Choose up to 2 players, including yourself. Others burn; you gain a streak and a buff.";
  button.dataset.tooltip = tooltip;
  button.setAttribute("aria-label", `Molotov Cocktail. ${tooltip}`);
}

function renderFireExtinguisherControls() {
  const button = elements.fireExtinguisherButton;
  if (!button) {
    return;
  }
  const owner = getCurrentPowerOwner();
  const stacks = getEffectStackCount(state.fireExtinguisherOwners?.[owner]);
  const visible = Boolean(
    stacks > 0
      && !state.isSpectator
      && !state.matchEnded
      && isAnswerInputLive()
      && elements.verdictPanel.classList.contains("hidden")
      && elements.endPanel.classList.contains("hidden")
  );
  setHidden(button, !visible);
  if (!visible) {
    return;
  }
  const candidates = getTargetCandidates(owner, getPowerById(`arsonist${chaosInfusedPowerSuffix}`));
  const used = Number(state.fireExtinguishedRounds?.[owner]?.usedRound) === Number(state.round);
  const disabled = used || !candidates.length || isClassicModeEnabled() || isTableEventActive("power_outage");
  button.disabled = disabled;
  button.classList.toggle("fire-extinguisher-used", used);
  const tooltip = used
    ? "Fire Extinguisher already used this round."
    : "Choose up to 2 players. They lose 1 streak now and cannot gain streak for 2 rounds.";
  button.dataset.tooltip = tooltip;
  button.setAttribute("aria-label", `Fire Extinguisher. ${tooltip}`);
}

function renderHintControls() {
  renderMolotovControls();
  renderFireExtinguisherControls();
  const button = elements.hintButton;
  if (!button) {
    return;
  }
  const visible = Boolean(
    (state.mode === "bots" || isRoomMode())
      && !state.isSpectator
      && !elements.inputPanel?.classList.contains("hidden")
  );
  setHidden(button, !visible);
  if (!visible) {
    return;
  }
  const availability = getHintAvailability();
  const disabled = Boolean(
    availability.usedThisRound
      || !availability.available
      || availability.hintState.pending
      || state.roomSubmissions[state.currentOwner]
      || state.matchEnded
  );
  button.disabled = disabled;
  button.classList.toggle("hint-used", availability.usedThisRound);
  button.classList.toggle("hint-unavailable", !availability.available && !availability.usedThisRound);
  const remainingPurchases = Math.max(0, 2 - availability.hintState.purchasesUsed);
  const tooltip = availability.usedThisRound
    ? isRoomMode() && remainingPurchases > 0
      ? `Hint used this round. Available next round for 5 coins. ${remainingPurchases} purchase${remainingPurchases === 1 ? "" : "s"} remaining.`
      : "One hint per round. Hint already used."
    : availability.hasFree
      ? `${availability.hintState.freeRemaining} free hint${availability.hintState.freeRemaining === 1 ? "" : "s"} remaining.`
      : availability.hasPurchase
        ? `Spend 5 coins. ${remainingPurchases} purchase${remainingPurchases === 1 ? "" : "s"} remaining this match.`
        : "No hints remaining this match.";
  button.dataset.tooltip = tooltip;
  button.setAttribute("aria-label", `Hint. ${tooltip}`);
}

function showQuestionHint(text = "") {
  const questionHint = elements.questionHint;
  const blackCard = getBlackCardElement();
  if (!questionHint || !blackCard) {
    return;
  }
  const hintText = String(text || "").trim();
  if (!hintText) {
    questionHint.textContent = "";
    questionHint.classList.remove("hint-arrived");
    setHidden(questionHint, true);
    scheduleBlackCardFit();
    return;
  }
  const beforeHeight = blackCard.getBoundingClientRect().height;
  const hintChanged = questionHint.textContent !== `Hint: ${hintText}`;
  questionHint.textContent = `Hint: ${hintText}`;
  setHidden(questionHint, false);
  if (hintChanged) {
    restartAnimation(questionHint, "hint-arrived");
  }
  animateBlackCardToNaturalHeightAfterLayout(blackCard, beforeHeight, {
    allowShrink: false,
    durationMs: 520
  });
}

function chooseLocalHintOptionToRemove() {
  const wrongOptions = getCurrentMultipleChoiceOptions().filter((answer) => !isMultipleChoiceAnswerCorrect(answer));
  if (!wrongOptions.length) {
    return "";
  }
  return wrongOptions[getRoundRandomIndex(wrongOptions.length, "hint-option")];
}

function applyHintResult(result = {}, options = {}) {
  const hintState = normalizeHintState(result.hintState || state.hintState);
  state.hintState = hintState;
  state.hintState.usedThisRound = true;
  state.hintState.usedRounds[getHintRoundKey()] = true;
  state.roundHintUsage[state.currentOwner] = true;
  if (isMultipleChoiceRound() && result.removedOption) {
    const removedKey = normalizeMultipleChoiceOption(result.removedOption);
    state.multipleChoiceOptions = getCurrentMultipleChoiceOptions()
      .filter((option) => normalizeMultipleChoiceOption(option) !== removedKey);
    renderMultipleChoiceOptions();
    showQuestionHint("One incorrect option was removed.");
  } else if (result.hint) {
    showQuestionHint(result.hint);
  }
  renderHintControls();
  renderAnswerCardsForOwners(getRoundCardOwners());
  if (!options.silent) {
    playSound("click");
  }
}

async function useHint() {
  const availability = getHintAvailability();
  if (!availability.available || availability.hintState.pending || state.isSpectator) {
    renderHintControls();
    return;
  }
  const isPaid = !availability.hasFree;
  if (isPaid && !spendCurrency(5, "hint")) {
    renderHintControls();
    return;
  }
  if (isPaid) {
    renderProfile();
  }
  state.hintState.pending = true;
  renderHintControls();
  if (isRoomMode()) {
    const participantId = getRoomParticipantIdForOwner(state.currentOwner) || state.clientId;
    const result = await roomSync.sendCommand("use_hint", {
      participantId,
      round: state.round,
      matchId: getCurrentRoomMatchId(),
      paid: isPaid
    }, { roomCode: state.roomSettings.code, participantId });
    if (!result?.ok) {
      if (isPaid) {
        addCurrency(5, "hint-refund");
        renderProfile();
      }
      state.hintState.pending = false;
      renderHintControls();
      addSystemChat(result?.error || "Hint could not be used.", { private: true, sync: false });
      return;
    }
    applyHintResult(result);
    return;
  }

  const nextState = {
    ...availability.hintState,
    freeRemaining: Math.max(0, availability.hintState.freeRemaining - (isPaid ? 0 : 1)),
    purchasesUsed: availability.hintState.purchasesUsed + (isPaid ? 1 : 0),
    pending: false
  };
  applyHintResult({
    hintState: nextState,
    hint: isMultipleChoiceRound() ? "One incorrect option was removed." : buildTextHint(state.canonicalAnswer),
    removedOption: isMultipleChoiceRound() ? chooseLocalHintOptionToRemove() : ""
  });
}

function resetRoundAnswers() {
  const owners = new Set([...DEFAULT_OWNER_IDS, ...getActiveOwners()]);
  state.roundAnswers = Object.fromEntries([...owners].map((owner) => [owner, ""]));
  state.roundCardOwners = [];
  state.visibleAnswerCardIndexes = [];
  state.answerCardCycleCursor = 0;
  state.currentRoundCards = [];
  state.currentRoundCardRatings = [];
  state.currentRoundCorrectIndexes = [];
  state.currentRoundGradingReasons = [];
  state.roundAnswerDamageByOwner = {};
  state.roundHintUsage = {};
  if (state.hintState && typeof state.hintState === "object") {
    state.hintState.usedThisRound = false;
  }
}

function clearRoomParticipantSubmissionState() {
  const clearParticipants = (participants = []) => normalizeRoomParticipantsList(participants).map((participant) => ({
    ...participant,
    answer: "",
    submittedRound: 0,
    submissionMatchId: "",
    remainingTime: 0,
    status: getRoomParticipantDefaultStatus(normalizeRoomParticipantRole(participant))
  }));
  state.roomParticipants = clearParticipants(state.roomParticipants);
  if (state.joiningRoom?.participants) {
    state.joiningRoom = {
      ...state.joiningRoom,
      participants: clearParticipants(state.joiningRoom.participants)
    };
  }
  const hostedRoom = state.hostedRooms.find((room) => room.code === state.roomSettings.code);
  if (hostedRoom?.participants) {
    hostedRoom.participants = clearParticipants(hostedRoom.participants);
  }
}

function clearRoundSubmissionState(options = {}) {
  clearLocalRoomSubmission();
  resetRoundAnswers();
  clearSpectatorAnswerDraftState();
  state.spectatorRoundResultPlaybackKey = "";
  state.roomRoundResultPlaybackKey = "";
  state.roomRoundResultPublishKey = "";
  state.roomBotAnswerSubmissions = {};
  state.roomBotAnswerWaitKey = "";
  state.roomSubmissions = {};
  state.answerRemainingTimes = Object.fromEntries(getActiveOwners().map((owner) => [owner, state.timerSeconds]));
  state.localAnswers = { playerOne: "", playerTwo: "" };
  if (options.clearParticipants !== false) {
    clearRoomParticipantSubmissionState();
  }
}

function clearRoomMatchPowerState() {
  // Match effects may intentionally survive round changes, but never survive
  // returning to the lobby or starting a different match.
  clearProlongedPowerEffects();
  state.impendingDoomOwners = {};
  state.collapsingStarOwners = {};
  state.targetWipeMarks = {};
  state.nullProtocolOwners = {};
  state.ultimatumRounds = {};
  state.explosiveDoomOwners = {};
  state.doomStreakGuardRounds = {};
  state.secretAgentRounds = {};
  state.secretAgentSwapRounds = {};
  state.chaosInputLockId = "";
  state.timerPenalties = createOwnerValueMap(0);
  state.lastPlayedPowerUps = createOwnerValueMap(null);
  state.forcedWinnerOwner = null;
  state.roundAmplifiedMultiplier = 1;
  state.currentTableEvent = null;
  state.tableEventSabotageUsed = {};
  state.blackMarketPurchases = {};
}

function clearRoomMatchScopedStateForLobby(options = {}) {
  cancelActiveMatchWork();
  stopTimer();
  clearRoomAutoResolve();
  stopNextRoundCountdown();
  resetTimerDisplay();
  stopLoadingMessages();
  setGradingActive(false);
  state.roomRoundTransitionPromise = null;
  state.roomRoundTransitionKey = "";
  state.roomGame = null;
  setCurrentRoomMatchId("");
  state.roomRoundResult = null;
  state.roomRoundResolving = false;
  resetRoomPowerSyncClocks();
  clearRoomMatchPowerState();
  resetPlayedPowersForRound();
  state.powerHands = {};
  state.freshPowerUps = {};
  state.freshPowerUpAnimations = {};
  state.powerHandExitHolds = {};
  clearRoundSubmissionState({ clearParticipants: options.clearParticipants !== false });
  state.round = 1;
  state.localEntryStep = 1;
  state.roundSetupRenderKey = "";
  state.questionId = "";
  state.blackCard = "";
  state.questionType = "image";
  state.questionStyle = "standard";
  state.questionLanguage = "en";
  state.gradingStrictness = "normal";
  state.questionDifficulty = "medium";
  state.triviaTheme = "";
  state.questionImage = null;
  state.canonicalAnswer = "";
  state.acceptedAnswers = [];
  state.judge = null;
  state.botCards = [];
  state.rejectedAnswers = [];
  state.multipleChoiceOptions = [];
  state.currentRoundCards = [];
  state.currentRoundCardRatings = [];
  state.currentRoundCorrectIndexes = [];
  state.currentRoundGradingReasons = [];
  state.roundProgress = Array.from({ length: Math.max(1, Number(state.maxRounds) || 1) }, () => "unanswered");
  if (elements.answerInput) {
    elements.answerInput.value = "";
  }
  if (elements.playerTwoInput) {
    elements.playerTwoInput.value = "";
  }
  renderMultipleChoiceOptions();
  setHidden(elements.endPanel, true);
  setHidden(elements.verdictPanel, true);
  setHidden(elements.loadingPanel, true);
  setHidden(elements.errorPanel, true);
}

function lockRoundAnswer(owner, input, fallback = "") {
  const answer = cleanInput(input || fallback || "");
  if (owner && answer) {
    state.roundAnswers[owner] = answer;
  }
  return answer;
}

function getLockedRoundAnswer(owner, fallback = "") {
  return cleanInput(state.roundAnswers?.[owner] || fallback || "");
}

function cleanChatInput(input) {
  return input
    .trim()
    .replace(/\s+/g, " ")
    .slice(0, 160);
}

function getEnabledTriviaThemes() {
  const source = state.mode === "room" || !elements.roomScreen.classList.contains("hidden")
    ? state.roomSettings.enabledThemes
    : state.enabledThemes;
  const enabled = Array.isArray(source) ? source.filter((theme) => triviaThemes.includes(theme)) : [];
  return enabled.length ? enabled : [...triviaThemes];
}

function normalizeQuestionLanguage(language) {
  const value = String(language || "").trim();
  if (value === "zh-Hans" || value === "zh" || value === "zh-CN" || value === "chinese") {
    return "zh-Hans";
  }
  return "en";
}

function getCurrentQuestionLanguage() {
  return normalizeQuestionLanguage(window.CardsAgainstAiI18n?.getLanguage?.() || "en");
}

function getRoomQuestionLanguage(settings = state.roomSettings) {
  const source = settings && typeof settings === "object" ? settings : {};
  return normalizeQuestionLanguage(source.questionLanguage || getCurrentQuestionLanguage());
}

function getQuestionLanguageLabel(language) {
  return questionLanguages[normalizeQuestionLanguage(language)]?.label || questionLanguages.en.label;
}

function setupMatchesQuestionLanguage(setup, questionLanguage = getCurrentQuestionLanguage()) {
  const setupLanguage = normalizeQuestionLanguage(setup?.language);
  return setupLanguage === normalizeQuestionLanguage(questionLanguage);
}

function getThemeSignature(themes = getEnabledTriviaThemes(), questionLanguage = getCurrentQuestionLanguage()) {
  return [...new Set(themes.filter((theme) => triviaThemes.includes(theme)))]
    .sort()
    .join("|") + `::${normalizeQuestionLanguage(questionLanguage)}`;
}

function normalizeDifficulty(difficulty) {
  const value = String(difficulty || "").toLowerCase();
  return Object.hasOwn(DIFFICULTY_BONUSES, value) ? value : "medium";
}

function getDifficultyBonus(difficulty = state.questionDifficulty) {
  return DIFFICULTY_BONUSES[normalizeDifficulty(difficulty)] || DIFFICULTY_BONUSES.medium;
}

function getDifficultyLabel(difficulty = state.questionDifficulty) {
  const normalized = normalizeDifficulty(difficulty);
  return `${normalized[0].toUpperCase()}${normalized.slice(1)} +${getDifficultyBonus(normalized).toLocaleString()}`;
}

function setupMatchesThemes(setup, enabledThemes = getEnabledTriviaThemes()) {
  const theme = setup?.triviaTheme || setup?.theme || "";
  return !theme || theme === "Mixed Trivia" || enabledThemes.includes(theme);
}

function getMultipleChoiceChancePercent(round = state.round, totalRounds = state.maxRounds) {
  const cleanTotalRounds = Math.max(1, Math.floor(Number(totalRounds) || 1));
  const cleanRound = Math.min(cleanTotalRounds, Math.max(1, Math.floor(Number(round) || 1)));
  if (cleanTotalRounds <= 1 || cleanRound >= cleanTotalRounds) {
    return 0;
  }
  return 30 * ((cleanTotalRounds - cleanRound) / (cleanTotalRounds - 1));
}

function getRoundQuestionStylePreference(options = {}, seed = "") {
  const { round, totalRounds } = getRoundSetupTimingOptions(options);
  const chance = getMultipleChoiceChancePercent(round, totalRounds);
  const rollSeed = String(seed || `${Date.now()}-${Math.random()}`);
  const rollPercent = (Math.abs(hashString(`${rollSeed}-question-style`)) % 10000) / 100;
  return chance > 0 && rollPercent < chance ? MULTIPLE_CHOICE_STYLE : "standard";
}

function getRoundSetupTimingOptions(options = {}) {
  const round = clampNumber(options.round ?? state.round, 1, 100, 1);
  const totalRounds = clampNumber(options.totalRounds ?? state.maxRounds, 1, 100, state.maxRounds || 10);
  return { round, totalRounds };
}

function setupMatchesRoundMultipleChoiceChance(setup, options = {}) {
  if (options.questionStylePreference === MULTIPLE_CHOICE_STYLE || options.questionStylePreference === "standard") {
    return setup?.questionStyle === options.questionStylePreference;
  }
  const { round, totalRounds } = getRoundSetupTimingOptions(options);
  return getMultipleChoiceChancePercent(round, totalRounds) > 0 || setup?.questionStyle !== MULTIPLE_CHOICE_STYLE;
}

function getThemeSetupOptions(theme = "") {
  const enabledThemes = getEnabledTriviaThemes();
  const preferredTheme = enabledThemes.includes(theme) ? theme : "";
  return {
    enabledThemes: preferredTheme ? [preferredTheme] : enabledThemes,
    preferredTheme,
    questionLanguage: getCurrentQuestionLanguage()
  };
}

function reserveQuestionSetups(setups) {
  const existing = new Set(state.questionReserve.map((setup) => normalizePromptText(setup?.blackCard)).filter(Boolean));
  for (const setup of setups) {
    const key = normalizePromptText(setup?.blackCard);
    if (!setup?.blackCard || !key || existing.has(key) || normalizePromptText(state.blackCard) === key) {
      continue;
    }
    existing.add(key);
    preloadQuestionImageInBackground(setup);
    state.questionReserve.push(setup);
  }
  if (state.questionReserve.length > QUESTION_RESERVE_LIMIT) {
    state.questionReserve = state.questionReserve.slice(-QUESTION_RESERVE_LIMIT);
  }
}

function removeReservedQuestionSetup(setupOrPrompt) {
  const prompt = normalizePromptText(typeof setupOrPrompt === "string" ? setupOrPrompt : setupOrPrompt?.blackCard);
  if (!prompt) {
    return;
  }
  state.questionReserve = state.questionReserve.filter((setup) => normalizePromptText(setup?.blackCard) !== prompt);
}

function discardUnusedQuestionSetups() {
  clearBackgroundSetupPrefetch();
  state.questionReserve = [];
  state.setupStack = [];
  state.nextSetup = null;
  state.nextSetupPromise = null;
  state.nextSetupStatus = "idle";
  state.warmSetup = null;
  state.warmSetupPromise = null;
  state.warmSetupSignature = "";
  state.setupVersion += 1;
  state.warmSetupVersion += 1;
}

function getQuestionImageUrls(setup) {
  const image = setup?.image;
  if (!image?.url) {
    return [];
  }
  return [image.url];
}

function forgetBackgroundImagePreload(url) {
  delete state.backgroundImagePreloads[url];
  state.backgroundImagePreloadOrder = state.backgroundImagePreloadOrder.filter((storedUrl) => storedUrl !== url);
}

function trackBackgroundImagePreload(url, value) {
  if (!state.backgroundImagePreloads[url]) {
    state.backgroundImagePreloadOrder.push(url);
  }
  state.backgroundImagePreloads[url] = value;
  while (state.backgroundImagePreloadOrder.length > BACKGROUND_IMAGE_PRELOAD_LIMIT) {
    const oldestUrl = state.backgroundImagePreloadOrder.shift();
    if (oldestUrl && oldestUrl !== url) {
      delete state.backgroundImagePreloads[oldestUrl];
    }
  }
}

function preloadQuestionImage(setup) {
  getQuestionImageUrls(setup).slice(0, 3).forEach((url) => {
    if (state.backgroundImagePreloads[url]) {
      return;
    }
    const image = new Image();
    trackBackgroundImagePreload(url, image);
    image.onload = () => {
      state.backgroundImagePreloads[url] = true;
    };
    image.onerror = () => {
      forgetBackgroundImagePreload(url);
    };
    image.decoding = "async";
    image.src = url;
  });
}

function preloadRoundExperience(setup) {
  if (!setup) {
    return;
  }
  preloadQuestionImage(setup);
  preloadSfxAudioAssets();
}

function runBackgroundTaskWhenIdle(callback, delay = 0) {
  window.setTimeout(() => {
    const run = () => {
      if (!state.gradingActive) {
        callback();
      } else {
        waitForGradingPriority().then(() => runBackgroundTaskWhenIdle(callback, 250));
      }
    };
    if ("requestIdleCallback" in window) {
      window.requestIdleCallback(run, { timeout: 1800 });
    } else {
      window.setTimeout(run, 0);
    }
  }, delay);
}

function preloadQuestionImageInBackground(setup) {
  if (!getQuestionImageUrls(setup).length) {
    return;
  }
  // Start the image request immediately so the next card can use the cache.
  preloadQuestionImage(setup);
  runBackgroundTaskWhenIdle(() => preloadQuestionImage(setup), 250);
}

function takeReservedSetup(enabledThemes = getEnabledTriviaThemes(), previousBlackCard = "", options = {}) {
  const previousKey = normalizePromptText(previousBlackCard);
  const questionLanguage = normalizeQuestionLanguage(options.questionLanguage || getCurrentQuestionLanguage());
  const index = state.questionReserve.findIndex((setup) => {
    const key = normalizePromptText(setup?.blackCard);
    return key
      && key !== previousKey
      && setupMatchesThemes(setup, enabledThemes)
      && setupMatchesQuestionLanguage(setup, questionLanguage)
      && setupMatchesRoundMultipleChoiceChance(setup, options);
  });
  if (index < 0) {
    return null;
  }
  const [setup] = state.questionReserve.splice(index, 1);
  preloadRoundExperience(setup);
  return setup;
}

function stashUnusedQuestionSetups() {
  reserveQuestionSetups([
    ...state.setupStack,
    state.nextSetup,
    state.warmSetup
  ].filter(Boolean));
  state.setupStack = [];
  state.nextSetup = null;
  state.warmSetup = null;
}

function hasReservedSetupForThemes(enabledThemes = getEnabledTriviaThemes(), options = {}) {
  const questionLanguage = normalizeQuestionLanguage(options.questionLanguage || getCurrentQuestionLanguage());
  return state.questionReserve.some((setup) => setupMatchesThemes(setup, enabledThemes)
    && setupMatchesQuestionLanguage(setup, questionLanguage)
    && setupMatchesRoundMultipleChoiceChance(setup, options));
}

function clearWarmSetup() {
  state.warmSetup = null;
  state.warmSetupPromise = null;
  state.warmSetupSignature = "";
  state.warmSetupVersion += 1;
}

function clearBackgroundSetupPrefetch() {
  if (state.backgroundSetupTimerId) {
    window.clearTimeout(state.backgroundSetupTimerId);
    state.backgroundSetupTimerId = null;
  }
}

function scheduleWhenIdle(callback, delay = BACKGROUND_PREFETCH_DELAY_MS) {
  clearBackgroundSetupPrefetch();
  state.backgroundSetupTimerId = window.setTimeout(() => {
    state.backgroundSetupTimerId = null;
    const run = () => {
      if (!state.gradingActive) {
        callback();
      }
    };
    if ("requestIdleCallback" in window) {
      window.requestIdleCallback(run, { timeout: 1800 });
    } else {
      window.setTimeout(run, 0);
    }
  }, delay);
}

function startWarmSetupPreload(options = {}) {
  const activeGameVisible = !elements.gameStage.classList.contains("hidden") && !state.matchEnded;
  if (window.location.protocol === "file:" || activeGameVisible) {
    return null;
  }

  const enabledThemes = Array.isArray(options.enabledThemes) ? options.enabledThemes : getEnabledTriviaThemes();
  const timingOptions = getRoundSetupTimingOptions(options);
  const questionLanguage = normalizeQuestionLanguage(options.questionLanguage || getCurrentQuestionLanguage());
  const signature = getThemeSignature(enabledThemes, questionLanguage);
  if (hasReservedSetupForThemes(enabledThemes, { ...timingOptions, questionLanguage })) {
    return Promise.resolve(state.questionReserve.find((setup) => setupMatchesThemes(setup, enabledThemes)
      && setupMatchesQuestionLanguage(setup, questionLanguage)
      && setupMatchesRoundMultipleChoiceChance(setup, timingOptions)));
  }
  if (state.warmSetup && state.warmSetupSignature === signature) {
    if (setupMatchesRoundMultipleChoiceChance(state.warmSetup, timingOptions)) {
      return Promise.resolve(state.warmSetup);
    }
    clearWarmSetup();
  }
  if (state.warmSetupPromise && state.warmSetupSignature === signature) {
    return state.warmSetupPromise;
  }

  const warmVersion = state.warmSetupVersion + 1;
  state.warmSetup = null;
  state.warmSetupVersion = warmVersion;
  state.warmSetupSignature = signature;
  const promise = requestRoundSetup({
    recentBlackCards: state.recentBlackCards,
    enabledThemes,
    preferredTheme: options.preferredTheme || "",
    questionLanguage,
    backgroundMode: true,
    ...timingOptions
  });
  state.warmSetupPromise = promise;
  promise
    .then((setup) => {
      if (state.warmSetupVersion === warmVersion && state.warmSetupSignature === signature) {
        state.warmSetup = setup;
        preloadRoundExperience(setup);
      }
      return setup;
    })
    .catch((error) => {
      if (isAbortError(error)) {
        return null;
      }
      if (state.warmSetupVersion === warmVersion) {
        console.warn("Warm question preload failed:", error);
      }
      return null;
    })
    .finally(() => {
      if (state.warmSetupVersion === warmVersion && state.warmSetupPromise === promise) {
        state.warmSetupPromise = null;
      }
    });
  return promise;
}

function ensureQuestionReserve(options = {}) {
  const enabledThemes = Array.isArray(options.enabledThemes) ? options.enabledThemes : getEnabledTriviaThemes();
  const timingOptions = getRoundSetupTimingOptions(options);
  const questionLanguage = normalizeQuestionLanguage(options.questionLanguage || getCurrentQuestionLanguage());
  if (hasReservedSetupForThemes(enabledThemes, { ...timingOptions, questionLanguage })) {
    return null;
  }
  return startWarmSetupPreload({ ...options, enabledThemes, ...timingOptions, questionLanguage });
}

function takeWarmSetup(enabledThemes = getEnabledTriviaThemes(), options = {}) {
  const questionLanguage = normalizeQuestionLanguage(options.questionLanguage || getCurrentQuestionLanguage());
  const signature = getThemeSignature(enabledThemes, questionLanguage);
  if (!state.warmSetup || state.warmSetupSignature !== signature) {
    return null;
  }
  if (!setupMatchesRoundMultipleChoiceChance(state.warmSetup, options)) {
    clearWarmSetup();
    return null;
  }

  const setup = state.warmSetup;
  state.warmSetup = null;
  state.warmSetupPromise = null;
  state.warmSetupSignature = "";
  return setup;
}

function getWarmSetupPromise(enabledThemes = getEnabledTriviaThemes(), options = {}) {
  const questionLanguage = normalizeQuestionLanguage(options.questionLanguage || getCurrentQuestionLanguage());
  const signature = getThemeSignature(enabledThemes, questionLanguage);
  return state.warmSetupPromise && state.warmSetupSignature === signature && getMultipleChoiceChancePercent(options.round, options.totalRounds) > 0
    ? state.warmSetupPromise
    : null;
}

function setGradingActive(isActive) {
  state.gradingActive = isActive;
  if (!isActive) {
    const waiters = state.gradingWaiters.splice(0);
    waiters.forEach((resolve) => resolve());
  }
}

function waitForGradingPriority() {
  if (!state.gradingActive) {
    return Promise.resolve();
  }
  return new Promise((resolve) => {
    state.gradingWaiters.push(resolve);
  });
}

function isAbortError(error) {
  return error?.name === "AbortError";
}

function combineAbortSignals(signals = []) {
  const activeSignals = signals.filter(Boolean);
  if (!activeSignals.length || typeof AbortController !== "function") {
    return activeSignals[0] || null;
  }
  const controller = new AbortController();
  const abort = () => {
    if (!controller.signal.aborted) {
      controller.abort();
    }
  };
  activeSignals.forEach((signal) => {
    if (signal.aborted) {
      abort();
    } else {
      signal.addEventListener("abort", abort, { once: true });
    }
  });
  return controller.signal;
}

async function withAbortableRequestTimeout(promiseFactory, timeoutMs = 10000, options = {}) {
  const baseSignal = options.signal || null;
  const timeoutController = typeof AbortController === "function" ? new AbortController() : null;
  const signal = timeoutController
    ? combineAbortSignals([baseSignal, timeoutController.signal])
    : baseSignal;
  const timeoutId = window.setTimeout(() => {
    timeoutController?.abort();
  }, Math.max(1, Number(timeoutMs) || 10000));
  try {
    return await promiseFactory(signal);
  } catch (error) {
    if (timeoutController?.signal.aborted && !baseSignal?.aborted) {
      const timeoutError = new Error(options.timeoutMessage || "The request took too long.");
      timeoutError.name = "TimeoutError";
      throw timeoutError;
    }
    throw error;
  } finally {
    window.clearTimeout(timeoutId);
  }
}

function createAbortError(message = "The active match work was cancelled.") {
  if (typeof DOMException === "function") {
    return new DOMException(message, "AbortError");
  }
  const error = new Error(message);
  error.name = "AbortError";
  return error;
}

function createHttpRequestError(message, response = null, payload = null) {
  const error = new Error(message || `Request failed${response?.status ? ` with status ${response.status}` : ""}.`);
  if (response?.status) {
    error.status = response.status;
  }
  if (payload && typeof payload === "object") {
    error.payload = payload;
    if (payload.code) {
      error.code = String(payload.code);
    }
  }
  return error;
}

function isRetryableRoomCommandStatus(status) {
  return [408, 429, 500, 502, 503, 504].includes(Number(status));
}

function waitForRoomCommandRetry(delayMs = 125) {
  return new Promise((resolve) => {
    window.setTimeout(resolve, Math.max(0, Number(delayMs) || 0));
  });
}

function isStaleRoomSetupError(error) {
  if (!error) {
    return false;
  }
  if (error.roomSyncStale) {
    return true;
  }
  const message = String(error.message || error.payload?.error || "").toLowerCase();
  return Number(error.status) === 409
    || message.includes("previous match")
    || message.includes("previous round")
    || message.includes("completed match")
    || message.includes("completed round")
    || message.includes("cannot overwrite")
    || message.includes("cannot skip")
    || message.includes("locked round");
}

function getRoomCommandLabel(commandType = "") {
  const labels = {
    add_bot: "Adding bot",
    create_room: "Creating room",
    end_game: "Ending game",
    join_room: "Joining room",
    leave_room: "Leaving room",
    moderate_participant: "Updating player",
    prepare_round: "Preparing question",
    publish_round_result: "Publishing results",
    rematch: "Starting rematch",
    resolve_auto_advance: "Starting next round",
    resolve_timer_expired: "Resolving timer",
    return_to_lobby: "Returning to lobby",
    send_chat: "Sending chat",
    skip_to_grading: "Starting grading",
    start_match: "Starting match",
    start_next_round: "Starting next round",
    submit_answer: "Submitting answer",
    transfer_host: "Transferring host",
    update_answer_draft: "Syncing answer",
    update_settings: "Saving settings",
    use_hint: "Using hint",
    use_power: "Using power"
  };
  const normalized = String(commandType || "").trim();
  if (labels[normalized]) {
    return labels[normalized];
  }
  const words = normalized.replaceAll("_", " ");
  return words ? `${words[0]?.toUpperCase() || ""}${words.slice(1)}` : "Room sync";
}

function isRoomBusyMessage(message = "") {
  const normalized = String(message || "").toLowerCase();
  return normalized.includes("room is busy processing another command")
    || normalized.includes("room is syncing another action")
    || normalized.includes("busy processing another command");
}

function isRoomTimeoutMessage(message = "") {
  const normalized = String(message || "").toLowerCase();
  return normalized.includes("signal is aborted")
    || normalized.includes("aborterror")
    || normalized.includes("timed out")
    || normalized.includes("timeout")
    || normalized.includes("aborted");
}

function getFriendlyRoomCommandError(errorOrMessage = "", status = 0, commandType = "") {
  const payload = errorOrMessage?.payload || errorOrMessage?.data || null;
  const rawMessage = String(
    errorOrMessage?.message
      || errorOrMessage?.error
      || payload?.error
      || errorOrMessage
      || ""
  );
  if (isRoomBusyMessage(rawMessage)) {
    return "Room is syncing another action. Give it a moment, then try again.";
  }
  if (isRoomTimeoutMessage(rawMessage) || isAbortError(errorOrMessage)) {
    return "Connection timed out while syncing. Please try again.";
  }
  if (Number(status) === 503 || Number(errorOrMessage?.status) === 503) {
    return "Room sync is slow right now. Please try again in a moment.";
  }
  if (rawMessage.toLowerCase().includes("failed to fetch") || rawMessage.toLowerCase().includes("network")) {
    return "Connection dropped while syncing. Please try again.";
  }
  return rawMessage || `${getRoomCommandLabel(commandType)} failed. Please try again.`;
}

function getRoomConnectionLabel(status = "connected") {
  const normalized = String(status || "connected").toLowerCase();
  if (normalized === "offline") {
    return "Offline";
  }
  if (normalized === "slow") {
    return "Slow";
  }
  if (normalized === "syncing") {
    return "Syncing";
  }
  return "Connected";
}

function getRoomConnectionMessage(status = "connected", message = "") {
  if (message) {
    return message;
  }
  const normalized = String(status || "connected").toLowerCase();
  if (normalized === "offline") {
    return "Room sync is disconnected. Actions may fail until it reconnects.";
  }
  if (normalized === "slow") {
    return "Room sync is slow. Your action may take a moment.";
  }
  if (normalized === "syncing") {
    return "Room sync is processing your latest action.";
  }
  return "Room sync is ready.";
}

function renderRoomConnectionStatus() {
  const health = state.roomConnectionHealth || {};
  const status = String(health.status || "connected").toLowerCase();
  const label = getRoomConnectionLabel(status);
  const message = getRoomConnectionMessage(status, health.message);
  [
    elements.roomConnectionStatus,
    elements.lobbyRoomConnectionStatus,
    elements.gameRoomConnectionStatus
  ].filter(Boolean).forEach((pill) => {
    pill.textContent = label;
    pill.dataset.status = status;
    pill.dataset.tooltip = message;
    pill.setAttribute("aria-label", `Room connection: ${label}. ${message}`);
  });
}

function setRoomConnectionHealth(status = "connected", options = {}) {
  const health = state.roomConnectionHealth || {};
  const nextStatus = String(status || "connected").toLowerCase();
  if (health.resetTimerId) {
    window.clearTimeout(health.resetTimerId);
    health.resetTimerId = null;
  }
  state.roomConnectionHealth = {
    ...health,
    status: nextStatus,
    message: getRoomConnectionMessage(nextStatus, options.message || ""),
    pendingCommands: Math.max(0, Number(options.pendingCommands ?? health.pendingCommands) || 0),
    lastLatencyMs: Math.max(0, Number(options.latencyMs ?? health.lastLatencyMs) || 0),
    lastError: String(options.error || (nextStatus === "connected" ? "" : health.lastError || "")).slice(0, 180),
    updatedAt: Date.now(),
    resetTimerId: null
  };
  renderRoomConnectionStatus();
  if (options.resetAfterMs && nextStatus !== "connected") {
    state.roomConnectionHealth.resetTimerId = window.setTimeout(() => {
      state.roomConnectionHealth.resetTimerId = null;
      if (state.roomConnectionHealth.pendingCommands > 0) {
        return;
      }
      setRoomConnectionHealth(isRoomRealtimeHealthy() || !state.supabaseEnabled ? "connected" : "slow", {
        message: isRoomRealtimeHealthy() || !state.supabaseEnabled
          ? "Room sync is ready."
          : "Realtime is reconnecting. Commands still sync through the server."
      });
    }, Math.max(500, Number(options.resetAfterMs) || 2500));
  }
}

function updateRoomConnectionForCommandStart(commandType = "") {
  const health = state.roomConnectionHealth || {};
  const pendingCommands = Math.max(0, Number(health.pendingCommands) || 0) + 1;
  setRoomConnectionHealth("syncing", {
    pendingCommands,
    message: `${getRoomCommandLabel(commandType)}...`
  });
  return Date.now();
}

function updateRoomConnectionForCommandEnd(commandType = "", startedAt = 0, result = {}) {
  const health = state.roomConnectionHealth || {};
  const pendingCommands = Math.max(0, (Number(health.pendingCommands) || 0) - 1);
  const latencyMs = startedAt ? Math.max(0, Date.now() - startedAt) : 0;
  if (result?.ok) {
    const slow = latencyMs > 1800 || (!state.realtimeRoomReady && state.supabaseEnabled);
    setRoomConnectionHealth(pendingCommands > 0 ? "syncing" : slow ? "slow" : "connected", {
      pendingCommands,
      latencyMs,
      message: pendingCommands > 0
        ? `${pendingCommands} room action${pendingCommands === 1 ? "" : "s"} still syncing...`
        : slow
          ? `${getRoomCommandLabel(commandType)} synced, but room updates are slow.`
          : "Room sync is ready.",
      resetAfterMs: slow ? 3500 : 0
    });
    return;
  }
  const status = Number(result?.status) || 0;
  const friendly = getFriendlyRoomCommandError(result, status, commandType);
  const busy = isRoomBusyMessage(friendly) || isRoomBusyMessage(result?.error);
  const timeout = isRoomTimeoutMessage(friendly) || isRoomTimeoutMessage(result?.error);
  setRoomConnectionHealth(busy ? "syncing" : timeout || status >= 500 || !status ? "slow" : "offline", {
    pendingCommands,
    latencyMs,
    message: friendly,
    error: friendly,
    resetAfterMs: busy || timeout || status >= 500 ? 4500 : 0
  });
}

function isCurrentMatchWork(token) {
  return token === state.matchWorkToken && !state.matchEnded;
}

function createRoundSetupWorkContext(extra = {}) {
  return {
    matchToken: state.matchWorkToken,
    roomCode: state.roomSettings.code || "",
    matchId: getCurrentRoomMatchId(),
    round: Number(state.round) || 0,
    ...extra
  };
}

function isCurrentRoundSetupWork(context = {}) {
  if (!isCurrentMatchWork(context.matchToken)) {
    return false;
  }
  const roomCode = String(context.roomCode || "").trim().toUpperCase();
  if (roomCode && roomCode !== String(state.roomSettings.code || "").trim().toUpperCase()) {
    return false;
  }
  if (Number(context.round || 0) && Number(context.round) !== Number(state.round)) {
    return false;
  }
  const matchId = String(context.matchId || "").trim();
  const currentMatchId = getCurrentRoomMatchId();
  if (matchId && currentMatchId && matchId !== currentMatchId) {
    return false;
  }
  return true;
}

function createRoomMatchId(code = state.roomSettings.code) {
  const normalizedCode = String(code || "CAI").trim().toUpperCase() || "CAI";
  return `${normalizedCode}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function createRoomBotParticipantId(code = state.roomSettings.code) {
  const roomCode = String(code || state.roomSettings.code || "room").trim().toUpperCase().replace(/[^A-Z0-9-]/g, "");
  const randomPart = window.crypto?.randomUUID
    ? window.crypto.randomUUID().replace(/-/g, "").slice(0, 12)
    : `${Date.now()}${Math.random().toString(36).slice(2, 8)}`;
  return `bot-${roomCode}-${randomPart}`.slice(0, 80);
}

function getRoomMatchIdFromPayload(payload = {}) {
  return String(
    payload.matchId
      || payload.game?.matchId
      || payload.room?.game?.matchId
      || payload.roundResult?.matchId
      || payload.powerState?.matchId
      || ""
  ).trim();
}

function getCurrentRoomMatchId() {
  return String(
    state.roomMatchId
      || state.roomGame?.matchId
      || state.joiningRoom?.game?.matchId
      || ""
  ).trim();
}

function setCurrentRoomMatchId(matchId = "") {
  state.roomMatchId = String(matchId || "").trim();
  return state.roomMatchId;
}

function getCurrentRoomRoundSyncKey(round = state.round) {
  return [
    state.roomSettings.code || "",
    getCurrentRoomMatchId() || "",
    Number(round) || 0
  ].join("|");
}

function isCurrentRoomRoundSyncKey(syncKey = "") {
  return Boolean(syncKey && syncKey === getCurrentRoomRoundSyncKey());
}

function roomPayloadMatchesCurrentMatch(payload = {}) {
  const incomingMatchId = getRoomMatchIdFromPayload(payload);
  const currentMatchId = getCurrentRoomMatchId();
  return !incomingMatchId || !currentMatchId || incomingMatchId === currentMatchId;
}

function isIncomingRoomRematchPayload(payload = {}, round = 0) {
  const incomingMatchId = getRoomMatchIdFromPayload(payload);
  const currentMatchId = getCurrentRoomMatchId();
  const nextRound = Number(
    round
      || payload.round
      || payload.nextRound
      || payload.game?.round
      || payload.room?.game?.round
      || 0
  ) || 0;
  if (!incomingMatchId || (currentMatchId && incomingMatchId === currentMatchId) || nextRound > 1) {
    return false;
  }
  return state.matchEnded
    || state.currentRoomStatus === "complete"
    || !elements.endPanel.classList.contains("hidden")
    || !elements.verdictPanel.classList.contains("hidden")
    || state.gradingActive;
}

function isJoinedRoomWaitingForSyncedSetup(round = state.round) {
  if (!isRoomMode() || !state.joiningRoom || isCurrentHost()) {
    return false;
  }
  const loadingVisible = elements.loadingPanel && !elements.loadingPanel.classList.contains("hidden");
  return state.currentRoomStatus === "lobby"
    || state.currentRoomStatus === "complete"
    || elements.gameStage.classList.contains("hidden")
    || (loadingVisible && (!state.questionId || Number(round) <= Number(state.round || 1)));
}

function isRoomGamePreparingRound(game = null, round = state.round) {
  if (!game || typeof game !== "object" || game.setup) {
    return false;
  }
  const status = String(game.status || "").trim().toLowerCase();
  const gameRound = Number(game.round) || 0;
  return ["starting", "preparing", "preparing_round"].includes(status)
    && (!round || !gameRound || gameRound === Number(round));
}

function getPreparingRoomGameForRound(round = state.round) {
  const game = state.roomGame || state.joiningRoom?.game || null;
  return isRoomGamePreparingRound(game, round) ? game : null;
}

function canAdoptIncomingRoomGame(game = null, room = null, round = state.round) {
  if (!game?.matchId || roomPayloadMatchesCurrentMatch({ game })) {
    return true;
  }
  if (isIncomingRoomRematchPayload({ game }, game.round || round)) {
    return String(room?.status || game.status || "").toLowerCase() !== "complete";
  }
  return Boolean(
    game.setup
    && Number(game.round || 0) >= Number(round || 1)
    && String(room?.status || game.status || "").toLowerCase() !== "complete"
    && isJoinedRoomWaitingForSyncedSetup(round)
  );
}

function cancelActiveMatchWork(options = {}) {
  state.matchWorkToken += 1;
  if (state.roundRequestAbortController) {
    state.roundRequestAbortController.abort();
    state.roundRequestAbortController = null;
  }
  state.setupRequestAbortControllers.forEach((controller) => controller.abort());
  state.setupRequestAbortControllers.clear();
  clearRoomAutoResolve();
  stopNextRoundCountdown();
  resetTimerDisplay();
  stopLoadingMessages();
  clearBackgroundSetupPrefetch();
  clearWarmSetup();
  setGradingActive(false);
  state.roomRoundResolving = false;
  state.nextSetup = null;
  state.nextSetupPromise = null;
  state.nextSetupStatus = "idle";
  state.setupStack = [];
  state.setupVersion += 1;
  if (options.stopRoomSync) {
    stopRoomPresenceMaintenance();
  }
}

function ensureServerMode() {
  if (window.location.protocol === "file:") {
    throw new Error("Open http://127.0.0.1:3000 instead of opening index.html directly.");
  }
}

function normalizeSetupPayload(setup) {
  if (!setup.blackCard) {
    throw new Error("Question setup response was incomplete.");
  }
  const judge = setup.judge || {
    name: "Trivia Grader",
    avatar: "AI",
    title: "Answer checker",
    bio: "Checks answers against accepted trivia facts.",
    likes: ["accuracy"],
    dislikes: [],
    voice: "concise quiz grading",
    tone: "fair"
  };
  const image = setup.image && typeof setup.image === "object" ? setup.image : {};
  const triviaTheme = String(setup.triviaTheme || setup.theme || "Mixed Trivia").trim();

  return {
    id: String(setup.id || "").trim(),
    blackCard: String(setup.blackCard || "").trim(),
    type: setup.type === "text" ? "text" : "image",
    questionStyle: setup.questionStyle === MULTIPLE_CHOICE_STYLE ? MULTIPLE_CHOICE_STYLE : "standard",
    language: normalizeQuestionLanguage(setup.language),
    gradingStrictness: normalizeGradingStrictness(setup.gradingStrictness),
    difficulty: ["easy", "medium", "hard"].includes(String(setup.difficulty || "").toLowerCase())
      ? String(setup.difficulty).toLowerCase()
      : "medium",
    triviaTheme,
    theme: triviaTheme,
    canonicalAnswer: String(setup.canonicalAnswer || "").trim(),
    acceptedAnswers: Array.isArray(setup.acceptedAnswers)
      ? setup.acceptedAnswers.map((answer) => String(answer).trim()).filter(Boolean).slice(0, 10)
      : [],
    image: {
      url: String(image.url || "").trim(),
      alt: String(image.alt || "").trim(),
      credit: String(image.credit || "").trim(),
      source: String(image.source || "").trim(),
      missingReason: String(image.missingReason || "").trim()
    },
    botCards: Array.isArray(setup.botCards) ? setup.botCards.map((card) => String(card).trim()).filter(Boolean).slice(0, 9) : [],
    rejectedAnswers: Array.isArray(setup.rejectedAnswers)
      ? setup.rejectedAnswers.map((answer) => String(answer).trim()).filter(Boolean).slice(0, 12)
      : [],
    multipleChoiceOptions: Array.isArray(setup.multipleChoiceOptions)
      ? setup.multipleChoiceOptions.map((answer) => cleanInput(String(answer || ""))).filter(Boolean).slice(0, 4)
      : [],
    judge: {
      name: String(judge.name || "Trivia Grader").trim(),
      avatar: String(judge.avatar || "AI").trim(),
      title: String(judge.title || "Answer checker").trim(),
      bio: String(judge.bio || "Checks answers against accepted trivia facts.").trim(),
      likes: Array.isArray(judge.likes) ? judge.likes.map((tag) => String(tag).trim()).filter(Boolean) : ["accuracy"],
      dislikes: Array.isArray(judge.dislikes) ? judge.dislikes.map((tag) => String(tag).trim()).filter(Boolean) : [],
      voice: String(judge.voice || "").trim(),
      tone: String(judge.tone || "fair").trim()
    },
    debug: setup.debug && typeof setup.debug === "object" ? setup.debug : null
  };
}

async function requestRoundSetup(options = {}) {
  ensureServerMode();
  await waitForGradingPriority();
  if (options.signal?.aborted) {
    throw createAbortError();
  }
  const setupSeed = `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  const timingOptions = getRoundSetupTimingOptions(options);
  const questionStylePreference = [MULTIPLE_CHOICE_STYLE, "standard"].includes(options.questionStylePreference)
    ? options.questionStylePreference
    : getRoundQuestionStylePreference(timingOptions, setupSeed);
  const questionDifficultyPreference = ["easy", "medium", "hard"].includes(options.questionDifficultyPreference)
    ? options.questionDifficultyPreference
    : "";
  const recentBlackCards = Array.isArray(options.recentBlackCards) ? options.recentBlackCards : state.recentBlackCards;
  const enabledThemes = Array.isArray(options.enabledThemes) ? options.enabledThemes : getEnabledTriviaThemes();
  const preferredTheme = options.preferredTheme || "";
  const questionLanguage = normalizeQuestionLanguage(options.questionLanguage || getCurrentQuestionLanguage());
  const cachedSetup = takeCachedRoundSetup({ recentBlackCards, enabledThemes, preferredTheme, questionLanguage, ...timingOptions, questionStylePreference });
  if (cachedSetup) {
    return cachedSetup;
  }
  const controller = options.signal ? null : new AbortController();
  const signal = options.signal || controller.signal;
  if (controller) {
    state.setupRequestAbortControllers.add(controller);
  }
  try {
    const response = await fetch("/api/setup", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      signal,
      body: JSON.stringify({
        recentBlackCards,
        enabledThemes,
        preferredTheme,
        preferredDifficulty: questionDifficultyPreference,
        preferredQuestionStyle: questionStylePreference,
        questionLanguage,
        backgroundMode: Boolean(options.backgroundMode),
        setupSeed,
        ...timingOptions
      })
    });

    if (!response.ok) {
      const error = await response.json().catch(() => ({}));
      throw new Error(error.error || `Question setup request failed with status ${response.status}.`);
    }

    const setup = normalizeSetupPayload(await response.json());
    cacheRoundSetup(setup, enabledThemes, questionLanguage);
    return setup;
  } finally {
    if (controller) {
      state.setupRequestAbortControllers.delete(controller);
    }
  }
}

async function requestAuthoritativeRoomRoundSetup(options = {}) {
  ensureServerMode();
  await waitForGradingPriority();
  if (!isRoomMode() || !isCurrentHost() || state.joiningRoom || !state.roomSettings.code || state.roomSettings.code === "CAI-0000") {
    throw new Error("Only the room host can prepare a shared round.");
  }
  if (options.signal?.aborted) {
    throw createAbortError();
  }

  const controller = options.signal ? null : new AbortController();
  const signal = options.signal || controller.signal;
  if (controller) {
    state.setupRequestAbortControllers.add(controller);
  }
  const timingOptions = getRoundSetupTimingOptions(options);
  const enabledThemes = Array.isArray(options.enabledThemes) ? options.enabledThemes : getEnabledTriviaThemes();
  const preferredTheme = options.preferredTheme || "";
  const preferredDifficulty = ["easy", "medium", "hard"].includes(options.questionDifficultyPreference)
    ? options.questionDifficultyPreference
    : "";
  const preferredQuestionStyle = [MULTIPLE_CHOICE_STYLE, "standard"].includes(options.questionStylePreference)
    ? options.questionStylePreference
    : "";
  const questionLanguage = normalizeQuestionLanguage(options.questionLanguage || getRoomQuestionLanguage());
  const setupSeed = String(options.setupSeed || `${Date.now()}-${Math.random().toString(36).slice(2)}`).slice(0, 80);
  const clientEventId = String(options.clientEventId || createRoomSyncCommandId("prepare-round", state.roomSettings.code)).slice(0, 160);

  try {
    if (signal?.aborted) {
      throw createAbortError();
    }
    const data = await roomSync.sendCommand("prepare_round", {
      clientEventId,
      hostParticipantId: state.clientId,
      matchId: getCurrentRoomMatchId(),
      round: timingOptions.round,
      totalRounds: timingOptions.totalRounds,
      recentBlackCards: Array.isArray(options.recentBlackCards) ? options.recentBlackCards : state.recentBlackCards,
      enabledThemes,
      preferredTheme,
      preferredDifficulty,
      preferredQuestionStyle,
      questionLanguage,
      setupSeed,
      matchSettings: getRoomMatchSettingsPayload(state.roomSettings),
      powerState: getRoomPowerStatePayload()
    }, {
      roomCode: state.roomSettings.code,
      participantId: state.clientId,
      clientEventId,
      timeoutMs: roomRoundCommandTimeoutMs
    });
    if (!data?.ok) {
      const requestError = createHttpRequestError(
        data?.error || "Room round setup failed.",
        { status: data?.status || 400 },
        data || {}
      );
      requestError.roomSyncStale = isStaleRoomSetupError(requestError);
      throw requestError;
    }

    state.roomDirectoryOnline = true;
    const events = Array.isArray(data.events) ? data.events : [];
    const roundStartedEvent = [...events].reverse()
      .find((event) => normalizeRoomEventType(event.type || event.payload?.eventType || "") === "round-started");
    const eventGame = roundStartedEvent?.payload?.game && typeof roundStartedEvent.payload.game === "object"
      ? roundStartedEvent.payload.game
      : null;
    const game = data.game && typeof data.game === "object" ? data.game : eventGame;
    if (game) {
      state.roomGame = game;
      if (game.matchId) {
        setCurrentRoomMatchId(game.matchId);
      }
    }

    const setup = getSyncedRoomSetupForRound(timingOptions.round)
      || normalizeSetupPayload(game?.setup || {});
    return setup;
  } catch (error) {
    if (!isStaleRoomSetupError(error)) {
      state.roomDirectoryOnline = false;
    }
    throw error;
  } finally {
    if (controller) {
      state.setupRequestAbortControllers.delete(controller);
    }
  }
}

function normalizePromptText(text) {
  return String(text || "")
    .normalize("NFD")
    .toLowerCase()
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .trim();
}

function loadRecentSetupCache() {
  const now = Date.now();
  const parsed = readJsonStorage(setupCacheStorageKey, []);
  return (Array.isArray(parsed) ? parsed : [])
    .map((entry) => ({
      signature: String(entry?.signature || ""),
      cachedAt: Number(entry?.cachedAt) || 0,
      setup: entry?.setup && typeof entry.setup === "object" ? entry.setup : null
    }))
    .filter((entry) => entry.setup && now - entry.cachedAt <= setupCacheMaxAgeMs)
    .slice(-setupCacheLimit);
}

function saveRecentSetupCache(entries) {
  writeJsonStorage(setupCacheStorageKey, (Array.isArray(entries) ? entries : []).slice(-setupCacheLimit));
  scheduleUserStorageSnapshot();
}

function removeCachedRoundSetup(setupOrPrompt) {
  const prompt = normalizePromptText(typeof setupOrPrompt === "string" ? setupOrPrompt : setupOrPrompt?.blackCard);
  if (!prompt) {
    return;
  }
  const cache = loadRecentSetupCache()
    .filter((entry) => normalizePromptText(entry.setup?.blackCard) !== prompt);
  saveRecentSetupCache(cache);
}

function getRecentPromptSet(recentBlackCards = state.recentBlackCards, previousBlackCard = state.blackCard) {
  return new Set([previousBlackCard, ...(Array.isArray(recentBlackCards) ? recentBlackCards : [])]
    .map(normalizePromptText)
    .filter(Boolean));
}

function isSetupUsableFromCache(setup, options = {}) {
  const enabledThemes = Array.isArray(options.enabledThemes) ? options.enabledThemes : getEnabledTriviaThemes();
  const preferredTheme = String(options.preferredTheme || "").trim();
  const questionLanguage = normalizeQuestionLanguage(options.questionLanguage || getCurrentQuestionLanguage());
  const prompt = normalizePromptText(setup?.blackCard);
  if (
    !prompt
    || getRecentPromptSet(options.recentBlackCards).has(prompt)
    || !setupMatchesThemes(setup, enabledThemes)
    || !setupMatchesQuestionLanguage(setup, questionLanguage)
    || !setupMatchesRoundMultipleChoiceChance(setup, options)
  ) {
    return false;
  }
  const usage = loadQuestionUsageStats();
  const usageKey = getQuestionUsageKey(setup);
  if (usageKey && Number(usage[usageKey]?.count) > 0) {
    return false;
  }
  return !preferredTheme || setup.triviaTheme === preferredTheme || setup.theme === preferredTheme;
}

function takeCachedRoundSetup(options = {}) {
  const cache = loadRecentSetupCache();
  const index = cache.findIndex((entry) => isSetupUsableFromCache(entry.setup, options));
  if (index < 0) {
    return null;
  }
  const [entry] = cache.splice(index, 1);
  saveRecentSetupCache(cache);
  try {
    return normalizeSetupPayload(entry.setup);
  } catch {
    return null;
  }
}

function cacheRoundSetup(setup, enabledThemes = getEnabledTriviaThemes(), questionLanguage = getCurrentQuestionLanguage()) {
  if (!setup?.blackCard) {
    return;
  }
  const normalized = normalizeSetupPayload(setup);
  const prompt = normalizePromptText(normalized.blackCard);
  const cache = loadRecentSetupCache()
    .filter((entry) => normalizePromptText(entry.setup?.blackCard) !== prompt);
  cache.push({
    signature: getThemeSignature(enabledThemes, questionLanguage),
    cachedAt: Date.now(),
    setup: normalized
  });
  saveRecentSetupCache(cache);
}

function getQuestionUsageKey(question) {
  return String(question?.id || "").trim() || normalizePromptText(question?.blackCard || question?.question || "");
}

function loadQuestionUsageStats() {
  try {
    const parsed = JSON.parse(localStorage.getItem(questionUsageStorageKey) || "{}");
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

function saveQuestionUsageStats(stats) {
  try {
    localStorage.setItem(questionUsageStorageKey, JSON.stringify(stats || {}));
    scheduleUserStorageSnapshot();
  } catch {
    // Local stats are nice-to-have; gameplay should keep moving if storage is full.
  }
}

function recordQuestionUsage(setup) {
  const key = getQuestionUsageKey(setup);
  if (!key) {
    return;
  }
  const stats = loadQuestionUsageStats();
  const current = stats[key] && typeof stats[key] === "object" ? stats[key] : {};
  stats[key] = {
    count: Math.max(0, Number(current.count) || 0) + 1,
    lastSeenAt: new Date().toISOString(),
    id: String(setup.id || current.id || "").trim(),
    question: String(setup.blackCard || current.question || "").trim(),
    theme: String(setup.triviaTheme || setup.theme || current.theme || "").trim()
  };
  saveQuestionUsageStats(stats);
}

function isRepeatedBlackCard(setup, previousBlackCard = state.blackCard) {
  const nextPrompt = normalizePromptText(setup && setup.blackCard);
  if (!nextPrompt) {
    return true;
  }

  const recentPrompts = [previousBlackCard, ...state.recentBlackCards]
    .map(normalizePromptText)
    .filter(Boolean);
  return recentPrompts.includes(nextPrompt);
}

async function requestAiRound(rawInput, options = {}) {
  ensureServerMode();
  if (options.signal?.aborted) {
    throw createAbortError();
  }
  const roundSeed = `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  const cardOwners = prepareRoundCardOwners(rawInput);
  const roomMode = isRoomMode();
  const duelMode = isDuelMode() && !roomMode;
  const apiMode = roomMode ? "room" : duelMode ? "local" : "bots";
  const botOwners = state.mode === "bots" ? getActiveBotOwners() : [];
  const botLabels = botOwners.map(getOwnerLabel);
  const playerAnswer = getLockedRoundAnswer("player", rawInput);
  const opponentAnswer = duelMode ? getLockedRoundAnswer("opponent", state.localAnswers.playerTwo) : "";
  const answerCards = cardOwners.map((owner) => {
    const player = getPlayer(owner);
    return {
      owner,
      label: getOwnerLabel(owner),
      answer: getRoundAnswerForOwner(owner),
      bot: Boolean(player?.bot || player?.type === "bot")
    };
  });
  const response = await fetch("/api/round", {
    method: "POST",
    headers: {
      "Content-Type": "application/json"
    },
    signal: options.signal,
    body: JSON.stringify({
      answer: playerAnswer,
      opponentAnswer,
      blackCard: state.blackCard,
      triviaTheme: state.triviaTheme,
      canonicalAnswer: state.canonicalAnswer,
      acceptedAnswers: state.acceptedAnswers,
      rejectedAnswers: state.rejectedAnswers || [],
      gradingStrictness: state.gradingStrictness,
      image: state.questionImage,
      mode: apiMode,
      roomCode: roomMode ? state.roomSettings.code : "",
      participantId: roomMode ? state.clientId : "",
      answerCards: roomMode ? answerCards : [],
      botCards: state.mode === "bots" ? botOwners.map((owner) => getRoundAnswerForOwner(owner)) : [],
      botLabels: state.mode === "bots" ? botLabels : [],
      matchContext: {
        playerScore: getScore("player"),
        opponentScore: state.mode === "bots" ? Math.max(0, ...botOwners.map((owner) => getScore(owner))) : getScore("opponent"),
        playerWins: state.matchHistory.filter((round) => round.winner === getOwnerLabel("player")).length,
        opponentWins: state.mode === "bots"
          ? state.matchHistory.filter((round) => botLabels.includes(round.winner)).length
          : state.matchHistory.filter((round) => round.winner === getOwnerLabel("opponent")).length,
        round: state.round,
        maxRounds: state.maxRounds
      },
      roundSeed
    })
  });

  if (!response.ok) {
    const error = await response.json().catch(() => ({}));
    throw new Error(error.error || `Round grading request failed with status ${response.status}.`);
  }

  const result = await response.json();
  const expectedCards = roomMode ? cardOwners.length : duelMode ? 2 : 1 + botOwners.length;
  if (!Array.isArray(result.cards) || result.cards.length !== expectedCards) {
    throw new Error(`Round grading response did not include ${expectedCards} cards.`);
  }

  return {
    cards: result.cards.map((card) => String(card).trim()),
    winner: {
      index: Number(result.winnerIndex)
    },
    correctIndexes: Array.isArray(result.correctIndexes)
      ? result.correctIndexes.map(Number).filter((index) => Number.isInteger(index) && index >= 0 && index < expectedCards)
      : [],
    aiReviewedIndexes: Array.isArray(result.aiReviewedIndexes)
      ? result.aiReviewedIndexes.map(Number).filter((index) => Number.isInteger(index) && index >= 0 && index < expectedCards)
      : [],
    aiSecondOpinionIndexes: Array.isArray(result.aiSecondOpinionIndexes)
      ? result.aiSecondOpinionIndexes.map(Number).filter((index) => Number.isInteger(index) && index >= 0 && index < expectedCards)
      : [],
    source: result.source || "api"
  };
}

function getMultipleChoiceRatingForOwner(owner, isCorrect) {
  if (!isCorrect) {
    return { label: "Incorrect", bonus: 0, correct: false, score: 0 };
  }
  const remaining = Number(state.answerRemainingTimes?.[owner]);
  const elapsed = Math.max(0, (Number(state.timerSeconds) || 0) - (Number.isFinite(remaining) ? remaining : 0));
  const badge = multipleChoiceTimingBadges.find((tier) => elapsed <= tier.maxElapsed) || multipleChoiceTimingBadges[multipleChoiceTimingBadges.length - 1];
  return {
    label: badge.label,
    bonus: badge.bonus,
    correct: true,
    score: Math.max(55, 140 - Math.round(elapsed * 6))
  };
}

function createMultipleChoiceRoundResult(rawInput = "") {
  const cardOwners = prepareRoundCardOwners(rawInput);
  const cards = cardOwners.map((owner) => getRoundAnswerForOwner(owner));
  const correctIndexes = cards
    .map((answer, index) => ({ answer, index }))
    .filter((entry) => isMultipleChoiceAnswerCorrect(entry.answer))
    .map((entry) => entry.index);
  const winnerIndex = correctIndexes
    .map((index) => ({
      index,
      remaining: Number(state.answerRemainingTimes?.[cardOwners[index]]) || 0
    }))
    .sort((a, b) => b.remaining - a.remaining || a.index - b.index)[0]?.index ?? 0;

  return {
    cards,
    winner: { index: winnerIndex },
    correctIndexes,
    source: "multiple-choice"
  };
}

function getClientLocalGradingThreshold(strictness = state.gradingStrictness) {
  switch (normalizeGradingStrictness(strictness)) {
    case "forgiving":
      return 0.78;
    case "strict":
      return 0.9;
    case "exact":
      return 1;
    case "normal":
    default:
      return 0.82;
  }
}

function isExactTriviaAnswerMatch(answer, acceptedAnswers = []) {
  const normalized = normalizeTriviaAnswer(answer);
  return Boolean(normalized) && acceptedAnswers
    .map(normalizeTriviaAnswer)
    .filter(Boolean)
    .includes(normalized);
}

function isExplicitlyRejectedRoundAnswer(answer, rejectedAnswers = []) {
  const normalized = normalizeTriviaAnswer(answer);
  if (!normalized) {
    return false;
  }
  return rejectedAnswers
    .map(normalizeTriviaAnswer)
    .filter(Boolean)
    .some((rejected) => (
      normalized === rejected
      || scoreAnswerAgainstAcceptedAnswers(answer, [rejected]) >= 0.92
    ));
}

function isRoundAnswerCorrectByStrictness(answer, acceptedAnswers = [], strictness = state.gradingStrictness) {
  const normalizedStrictness = normalizeGradingStrictness(strictness);
  if (normalizedStrictness === "exact") {
    return isExactTriviaAnswerMatch(answer, acceptedAnswers);
  }
  return scoreAnswerAgainstAcceptedAnswers(answer, acceptedAnswers) >= getClientLocalGradingThreshold(normalizedStrictness);
}

function createLocalTextRoundResult(rawInput = "") {
  const cardOwners = prepareRoundCardOwners(rawInput);
  const cards = cardOwners.map((owner) => getRoundAnswerForOwner(owner));
  const answerBank = [state.canonicalAnswer, ...state.acceptedAnswers].filter(Boolean);
  const rejectedAnswers = Array.isArray(state.rejectedAnswers) ? state.rejectedAnswers : [];
  const correctIndexes = cards
    .map((card, index) => ({ index, score: scoreAnswerAgainstAcceptedAnswers(card, answerBank) }))
    .filter((entry) => (
      !isExplicitlyRejectedRoundAnswer(cards[entry.index], rejectedAnswers)
      && isRoundAnswerCorrectByStrictness(cards[entry.index], answerBank, state.gradingStrictness)
    ))
    .sort((a, b) => b.score - a.score || a.index - b.index)
    .map((entry) => entry.index)
    .filter((index) => Number.isInteger(index) && index >= 0 && index < cards.length);

  return {
    cards,
    winner: { index: correctIndexes[0] ?? 0 },
    correctIndexes: [...new Set(correctIndexes)],
    aiReviewedIndexes: [],
    aiSecondOpinionIndexes: [],
    source: "client-local-fallback"
  };
}

const modalCloseTimers = new WeakMap();

function clearModalCloseTimer(element) {
  const timerId = modalCloseTimers.get(element);
  if (!timerId) {
    return;
  }
  window.clearTimeout(timerId);
  modalCloseTimers.delete(element);
}

function setHidden(element, isHidden) {
  if (!isHidden) {
    clearModalCloseTimer(element);
  }
  if (!isHidden) {
    element.classList.remove("closing");
  }
  element.classList.toggle("hidden", isHidden);
  if (element === elements?.gameStage) {
    document.body?.toggleAttribute("data-game-active", !isHidden);
  }
}

function markModalOpening(element, duration = 760) {
  if (!element) {
    return;
  }
  element.classList.add("motion-opening");
  window.setTimeout(() => {
    element.classList.remove("motion-opening");
  }, duration);
}

function shouldReduceMotion() {
  return !allowsOneShotAnimations();
}

function getVisibleElementRectMap(container, selector, keyGetter) {
  if (!container || typeof keyGetter !== "function") {
    return new Map();
  }
  return new Map(
    [...container.querySelectorAll(selector)]
      .filter((element) => element.isConnected && element.offsetParent !== null)
      .map((element) => [keyGetter(element), element.getBoundingClientRect()])
      .filter(([key]) => key)
  );
}

function animateReorderedChildren(container, previousRects, selector, keyGetter, options = {}) {
  if (!container || !previousRects?.size || !Element.prototype.animate || shouldReduceMotion()) {
    return;
  }
  const duration = Number(options.duration) || 360;
  const easing = options.easing || "cubic-bezier(0.16, 1, 0.3, 1)";
  [...container.querySelectorAll(selector)].forEach((element) => {
    const previousRect = previousRects.get(keyGetter(element));
    if (!previousRect) {
      return;
    }
    const nextRect = element.getBoundingClientRect();
    const deltaX = previousRect.left - nextRect.left;
    const deltaY = previousRect.top - nextRect.top;
    if (Math.abs(deltaX) < 1 && Math.abs(deltaY) < 1) {
      return;
    }
    element.classList.add("motion-polish-leaderboard-moving");
    element.animate(
      [
        { transform: `translate3d(${deltaX}px, ${deltaY}px, 0)`, zIndex: 30 },
        { transform: "translate3d(0, 0, 0)", zIndex: 30 }
      ],
      { duration, easing }
    ).finished.finally(() => {
      element.classList.remove("motion-polish-leaderboard-moving");
    });
  });
}

function ensureStatFlashElement() {
  let flash = document.querySelector("#statFlash");
  if (flash) {
    return flash;
  }

  flash = document.createElement("div");
  flash.id = "statFlash";
  flash.className = "stat-flash hidden";
  flash.setAttribute("aria-live", "polite");
  flash.setAttribute("aria-atomic", "true");
  flash.innerHTML = `
    <div class="stat-flash-panel">
      <strong class="stat-flash-title"></strong>
      <span class="stat-flash-detail"></span>
    </div>
  `;
  document.body.appendChild(flash);
  return flash;
}

function normalizeStatFlashKind(kind) {
  return [
    "positive",
    "negative",
    "mixed",
    "shield",
    "chaos",
    "burning",
    "lightning",
    "bomb",
    "bounty",
    "sudden-death",
    "outage",
    "no-mercy",
    "black-market",
    "casino",
    "doom",
    "sabotage",
    "coin"
  ].includes(kind) ? kind : "positive";
}

function getStatFlashPresentationMatchKey() {
  return getCurrentRoomMatchId() || `local-${state.matchWorkToken}`;
}

function getStatFlashPresentationRoundKey() {
  return `${getStatFlashPresentationMatchKey()}|${Number(state.round) || 1}`;
}

function getRoundOverlayIconConfig(kind, title, options = {}) {
  const normalizedKind = normalizeStatFlashKind(kind);
  const cleanTitle = String(title || "Effect").trim() || "Effect";
  const titleKey = cleanTitle.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "effect";
  const normalizedTitle = cleanTitle.toLowerCase();
  const defaults = {
    chaos: { src: "assets/modifiers/dice.svg", className: "chaos" },
    mixed: { src: "assets/modifiers/equalizer.svg", className: "mixed" },
    burning: { src: "assets/modifiers/flame.svg", className: "burning" },
    lightning: { src: "assets/overlays/flash.svg", className: "lightning" },
    bomb: { src: "assets/overlays/bomb.svg", className: "bomb" },
    doom: { src: "assets/overlays/nuke.svg", className: "doom" },
    shield: { src: "assets/overlays/shield.svg", className: "shield" },
    "sudden-death": { src: "assets/modifiers/skull.svg", className: "doom" },
    "no-mercy": { src: "assets/modifiers/skull.svg", className: "doom" },
    coin: { src: "assets/overlays/coin.svg", className: "coin" },
    bounty: { src: "assets/overlays/coin.svg", className: "coin" },
    outage: { src: "assets/modifiers/no-stopping.svg", className: "outage" },
    sabotage: { src: "assets/modifiers/skull.svg", className: "sabotage" },
    casino: { src: "assets/modifiers/dice.svg", className: "casino" },
    "black-market": { src: "assets/overlays/store.svg", className: "market" },
    negative: { src: "assets/overlays/arrow.svg", className: "negative" },
    positive: { src: "assets/overlays/arrow.svg", className: "positive" }
  };
  const fallback = defaults[normalizedKind] || defaults.positive;
  const titleAsset = !options.iconSrc && /\b(blue pill|mega pill|pharmacy)\b/.test(normalizedTitle)
    ? { src: "assets/overlays/pill.svg", className: "pill" }
    : !options.iconSrc && /\b(virus|antivirus|encryption|error 404)\b/.test(normalizedTitle)
      ? { src: "assets/overlays/coronavirus.svg", className: "virus" }
      : null;
  const modeAsset = options.iconKey === "mode:time-money"
    ? { src: "assets/modifiers/stop-watch.svg", className: "time-money" }
    : null;
  const resolvedAsset = modeAsset || titleAsset || fallback;
  return {
    key: String(options.iconKey || `${normalizedKind}:${titleKey}`),
    src: String(options.iconSrc || resolvedAsset.src),
    className: String(options.iconClassName || resolvedAsset.className),
    label: String(options.iconLabel || cleanTitle)
  };
}

function formatRoundOverlayTooltip(icon) {
  const details = Array.isArray(icon.details) ? icon.details.filter(Boolean).slice(-3) : [];
  const lines = [icon.label, ...details];
  if (icon.count > 1) {
    lines.push(`Triggered x${icon.count}`);
  }
  return lines.join("\n");
}

function renderRoundOverlayIcons() {
  const container = elements.roundOverlayIcons || document.querySelector("#roundOverlayIcons");
  if (!container) {
    return;
  }
  const existing = new Map(
    [...container.children]
      .filter((element) => element.dataset.overlayIconKey)
      .map((element) => [element.dataset.overlayIconKey, element])
  );
  container.replaceChildren();
  (Array.isArray(state.roundOverlayIcons) ? state.roundOverlayIcons : []).forEach((icon) => {
    const button = existing.get(icon.key) || document.createElement("button");
    const isNew = !existing.has(icon.key);
    button.type = "button";
    button.className = `round-overlay-icon ${icon.className || ""}`.trim();
    button.dataset.overlayIconKey = icon.key;
    button.dataset.tooltip = formatRoundOverlayTooltip(icon);
    button.setAttribute("aria-label", formatRoundOverlayTooltip(icon).replace(/\n/g, ". "));
    button.innerHTML = `
      <img src="${icon.src}" alt="" loading="lazy" decoding="async">
      ${icon.count > 1 ? `<span class="round-overlay-icon-count">x${icon.count}</span>` : ""}
    `;
    container.appendChild(button);
    button.classList.remove("round-overlay-icon-entering", "round-overlay-icon-pulse");
    void button.offsetWidth;
    button.classList.add(isNew ? "round-overlay-icon-entering" : "round-overlay-icon-pulse");
    window.setTimeout(() => {
      button.classList.remove("round-overlay-icon-entering", "round-overlay-icon-pulse");
    }, 760);
  });
}

function syncStatFlashRoundPresentation(options = {}) {
  const matchKey = getStatFlashPresentationMatchKey();
  const roundKey = getStatFlashPresentationRoundKey();
  if (state.statFlashRoundKey === roundKey) {
    return false;
  }
  if (options.clearQueue !== false && state.statFlashRoundKey) {
    clearStatFlashes({ clearIcons: false });
  }
  state.statFlashMatchKey = matchKey;
  state.statFlashRoundKey = roundKey;
  state.statFlashRoundOverlayCount = 0;
  state.roundOverlayIcons = [];
  renderRoundOverlayIcons();
  return true;
}

function recordRoundOverlayIcon(kind, title, detail, options = {}) {
  syncStatFlashRoundPresentation();
  const config = getRoundOverlayIconConfig(kind, title, options);
  const details = Array.isArray(detail)
    ? detail.map((line) => String(line || "").trim()).filter(Boolean)
    : String(detail || "").split("\n").map((line) => line.trim()).filter(Boolean);
  const existing = state.roundOverlayIcons.find((icon) => icon.key === config.key);
  if (existing) {
    existing.count += 1;
    existing.details = [...new Set([...(existing.details || []), ...details])].slice(-3);
    existing.className = config.className;
    existing.src = config.src;
    existing.label = config.label;
  } else {
    state.roundOverlayIcons.push({
      key: config.key,
      src: config.src,
      className: config.className,
      label: config.label,
      count: 1,
      details
    });
  }
  renderRoundOverlayIcons();
}

function getFocusedOwner() {
  return getCurrentPowerOwner();
}

function isStatFlashRelevant(owners = null) {
  if (!Array.isArray(owners) || owners.length === 0) {
    return true;
  }
  return owners.includes(getFocusedOwner());
}

function queueStatFlash(kind, title, detail, options = {}) {
  if (!isStatFlashRelevant(options.owners)) {
    return;
  }
  const cleanTitle = String(title || "").trim();
  const cleanDetail = Array.isArray(detail)
    ? detail.map((line) => String(line || "").trim()).filter(Boolean).join("\n")
    : String(detail || "").trim();
  if (!cleanTitle || !cleanDetail) {
    return;
  }
  syncStatFlashRoundPresentation();
  const iconConfig = getRoundOverlayIconConfig(kind, cleanTitle, options);
  const round = Number(state.round) || 1;
  const isFirstRound = round <= 1 && options.forceLimited !== true;
  const isModeIntroduction = options.modeIntroduction === true;
  const introductionKey = String(options.introductionKey || options.iconKey || iconConfig.key);
  if (isModeIntroduction && isFirstRound && state.statFlashModeIntroductionKeys.has(introductionKey)) {
    return;
  }
  if (options.skipIconRecord !== true) {
    recordRoundOverlayIcon(kind, cleanTitle, cleanDetail, options);
  }

  const isChaosGlitch = options.chaosGlitch === true;
  const isFinalPointOverlay = options.finalPointOverlay === true || options.finalResult === true;
  const hasOverlayBudget = state.statFlashRoundOverlayCount < 3;
  const shouldShowFullOverlay = isChaosGlitch
    || isFinalPointOverlay
    || (isModeIntroduction ? isFirstRound : isFirstRound || hasOverlayBudget);
  if (!shouldShowFullOverlay) {
    return;
  }
  if (!isFirstRound && !isChaosGlitch && !isFinalPointOverlay) {
    state.statFlashRoundOverlayCount += 1;
  }
  if (isModeIntroduction && isFirstRound) {
    state.statFlashModeIntroductionKeys.add(introductionKey);
  }
  const focusedOwner = getFocusedOwner();
  const sourceOwner = options.sourceOwner || "";
  const sourceAttribution = sourceOwner && sourceOwner !== focusedOwner
    ? `${getOwnerLabel(sourceOwner)} used ${cleanTitle}`
    : "";

  const flashEntry = {
    kind: getPerformanceOverlayKind(kind),
    title: sourceAttribution || cleanTitle,
    detail: cleanDetail,
    overlayVariant: options.overlayVariant === "ultimatum"
      || cleanTitle.toLowerCase() === "ultimatum"
      ? "ultimatum"
      : "",
    durationMs: getStatFlashDuration(cleanDetail, { ...options, sourceAttribution: Boolean(sourceAttribution) }),
    soundName: options.soundName || getStatFlashSoundName(kind, cleanDetail, options),
    flickerText: state.performanceMode !== "low-power" && state.performanceMode !== "minimal" && Boolean(options.flickerText || shouldFlickerStatFlashText(kind, cleanDetail)),
    onTextChange: typeof options.onTextChange === "function" ? options.onTextChange : null
  };
  if (isPointLossSoundName(flashEntry.soundName)) {
    state.pointLossSoundToken += 1;
  }
  if (options.priority) {
    state.statFlashQueue.unshift(flashEntry);
  } else {
    state.statFlashQueue.push(flashEntry);
  }
  playNextStatFlash();
}

function isPointLossSoundName(soundName) {
  return ["genericLosePoint", "burnLoss", "bombLoss", "zapLoss"].includes(soundName);
}

function playUnassignedPointLossSound(deltas, tokenBefore = state.pointLossSoundToken) {
  const focusedOwner = getFocusedOwner();
  if ((deltas?.[focusedOwner] || 0) < 0 && state.pointLossSoundToken === tokenBefore) {
    playSound("genericLosePoint");
    state.pointLossSoundToken += 1;
  }
}

function shouldFlickerStatFlashText(kind, detail) {
  if (normalizeStatFlashKind(kind) !== "chaos") {
    return false;
  }
  const cleanDetail = String(detail || "").replace(/\s+/g, "");
  return cleanDetail.length >= 8 && /^[^A-Za-z]+$/.test(cleanDetail);
}

function getStatFlashSoundName(kind, detail, options = {}) {
  if (options.silent) {
    return "";
  }
  const normalizedKind = normalizeStatFlashKind(kind);
  if (normalizedKind === "chaos") {
    return "glitch";
  }
  if (normalizedKind === "doom") {
    return "bombLoss";
  }
  if (normalizedKind === "burning") {
    return "burnLoss";
  }
  if (normalizedKind === "lightning") {
    return "zapLoss";
  }
  if (normalizedKind === "bomb") {
    return "bombLoss";
  }
  if (options.unit === "Point" && normalizedKind === "positive") {
    return "pointGain";
  }
  if (options.unit === "Point" && normalizedKind === "negative") {
    return "genericLosePoint";
  }
  if (/\+\d[\d,.\s%]*\s*Points?/i.test(String(detail || ""))) {
    return "pointGain";
  }
  if (/-\d[\d,.\s%]*\s*Points?/i.test(String(detail || ""))) {
    return "genericLosePoint";
  }
  return "";
}

function getStatFlashDuration(detail, options = {}) {
  const explicitDuration = Number(options.durationMs);
  if (Number.isFinite(explicitDuration)) {
    return clampNumber(explicitDuration, 900, 3200, 1150);
  }

  const lineCount = String(detail || "").split("\n").filter(Boolean).length;
  let duration = 1150;
  if (options.complex || lineCount > 1) {
    duration = 2300;
  } else if (String(detail || "").length > 44) {
    duration = 2050;
  } else if (String(detail || "").length > 24) {
    duration = 1700;
  }
  return options.sourceAttribution ? Math.min(3200, Math.max(1650, duration + 350)) : duration;
}

function getTargetedFlashOptions(sourceOwner, targetOwner, options = {}) {
  return {
    ...options,
    owners: [targetOwner],
    sourceOwner,
    iconSrc: options.iconSrc || "assets/overlays/customer.svg",
    iconClassName: options.iconClassName || "targeted"
  };
}

function playNextStatFlash() {
  if (state.statFlashActive || !state.statFlashQueue.length) {
    return;
  }

  const flash = ensureStatFlashElement();
  const next = state.statFlashQueue.shift();
  const title = flash.querySelector(".stat-flash-title");
  const detail = flash.querySelector(".stat-flash-detail");
  title.textContent = next.title;
  detail.textContent = next.detail;
  if (next.onTextChange) {
    next.onTextChange(next.detail);
  }
  flash.style.setProperty("--stat-flash-duration", `${next.durationMs}ms`);
  flash.classList.remove("positive", "negative", "mixed", "shield", "chaos", "burning", "lightning", "bomb", "bounty", "sudden-death", "outage", "no-mercy", "black-market", "casino", "doom", "sabotage", "coin", "ultimatum", "hidden", "stat-flash-playing");
  void flash.offsetWidth;
  flash.classList.add(next.kind, "stat-flash-playing");
  if (next.overlayVariant) {
    flash.classList.add(next.overlayVariant);
  }
  if (next.soundName) {
    playSound(next.soundName);
  }
  if (next.flickerText) {
    const updateFlickerText = () => {
      const text = randomChaosText(getRandomInt(12, 20));
      detail.textContent = text;
      if (next.onTextChange) {
        next.onTextChange(text);
      }
    };
    updateFlickerText();
    state.statFlashTextTimerId = window.setInterval(updateFlickerText, 90);
  }
  state.statFlashActive = true;

  if (state.statFlashTimerId) {
    window.clearTimeout(state.statFlashTimerId);
  }
  state.statFlashTimerId = window.setTimeout(() => {
    if (state.statFlashTextTimerId) {
      window.clearInterval(state.statFlashTextTimerId);
      state.statFlashTextTimerId = null;
    }
    flash.classList.add("hidden");
    flash.classList.remove("stat-flash-playing");
    state.statFlashActive = false;
    state.statFlashTimerId = null;
    playNextStatFlash();
  }, next.durationMs);
}

function clearStatFlashes(options = {}) {
  state.statFlashQueue = [];
  state.statFlashActive = false;
  if (options.clearIcons !== false) {
    state.statFlashMatchKey = "";
    state.statFlashRoundKey = "";
    state.statFlashRoundOverlayCount = 0;
    state.statFlashModeIntroductionKeys = new Set();
    state.roundOverlayIcons = [];
    renderRoundOverlayIcons();
  }
  if (state.statFlashTimerId) {
    window.clearTimeout(state.statFlashTimerId);
    state.statFlashTimerId = null;
  }
  if (state.statFlashTextTimerId) {
    window.clearInterval(state.statFlashTextTimerId);
    state.statFlashTextTimerId = null;
  }
  const flash = document.querySelector("#statFlash");
  if (flash) {
    flash.classList.add("hidden");
    flash.classList.remove("stat-flash-playing", "positive", "negative", "mixed", "shield", "chaos", "burning", "lightning", "bomb", "bounty", "sudden-death", "outage", "no-mercy", "black-market", "casino", "doom", "sabotage", "coin", "ultimatum");
  }
}

function formatSignedStat(amount, unit) {
  const rounded = Math.round(amount || 0);
  return `${rounded > 0 ? "+" : ""}${rounded.toLocaleString()} ${unit}${Math.abs(rounded) === 1 ? "" : "s"}`;
}

function getStatFlashKindFromAmounts(amounts) {
  const cleanAmounts = amounts.filter((amount) => amount !== 0);
  const hasPositive = cleanAmounts.some((amount) => amount > 0);
  const hasNegative = cleanAmounts.some((amount) => amount < 0);
  if (hasPositive && hasNegative) {
    return "mixed";
  }
  return hasNegative ? "negative" : "positive";
}

function queueDeltaStatFlash(title, deltas, unit = "Point", options = {}) {
  const entries = Object.entries(deltas || {}).filter(([, amount]) => amount !== 0);
  if (!entries.length) {
    return;
  }

  const focusOwner = getFocusedOwner();
  const focusEntry = entries.find(([owner]) => owner === focusOwner);
  if (!focusEntry) {
    return;
  }

  const kind = options.kind || getStatFlashKindFromAmounts([focusEntry[1]]);
  const detail = formatSignedStat(focusEntry[1], unit);
  queueStatFlash(kind, title, detail, { ...options, unit });
}

function getCocktailFlashKind(result) {
  const normalized = String(result || "").toLowerCase();
  if (normalized.includes("shield")
    || normalized.includes("guard")
    || normalized.includes("encrypted")
    || normalized.includes("antivirus")) {
    return "shield";
  }
  if (normalized.includes("blocked")) {
    return "positive";
  }
  if (normalized.includes("lose")
    || normalized.includes("debt")
    || normalized.includes("dead weight")
    || normalized.includes("chaos")
    || normalized.includes("failed investment")
    || normalized.includes("combustion")
    || normalized.includes("time bomb")) {
    return "negative";
  }
  return "positive";
}

function shouldQueueCocktailResultFlash(result) {
  const normalized = String(Array.isArray(result) ? result.join("\n") : result || "").toLowerCase();
  if (!normalized.trim()) {
    return false;
  }
  return !normalized.includes("chaos:")
    && !normalized.includes("answer scrambled")
    && !normalized.includes("blocked")
    && !normalized.includes("antivirus blocked")
    && !normalized.includes("blocked error 404")
    && !normalized.includes("blocked curse")
    && !normalized.includes("blocked sabotage")
    && !normalized.includes("blocked cocktail mix");
}

function queueCocktailResultFlash(title, result, options = {}) {
  if (!shouldQueueCocktailResultFlash(result)) {
    return false;
  }
  queueStatFlash(getCocktailFlashKind(result), title, result, { complex: true, ...options });
  return true;
}

function ensureFloatingDescriptionTooltip() {
  let tooltip = document.querySelector("#floatingDescriptionTooltip");
  if (tooltip) {
    return tooltip;
  }
  tooltip = document.createElement("div");
  tooltip.id = "floatingDescriptionTooltip";
  tooltip.className = "floating-description-tooltip hidden";
  document.body.appendChild(tooltip);
  return tooltip;
}

function positionFloatingDescriptionTooltip(target, tooltip) {
  const rect = target.getBoundingClientRect();
  const tooltipRect = tooltip.getBoundingClientRect();
  const gap = 8;
  const left = Math.min(
    Math.max(8, rect.left + (rect.width / 2) - (tooltipRect.width / 2)),
    Math.max(8, window.innerWidth - tooltipRect.width - 8)
  );
  const topCandidate = rect.top - tooltipRect.height - gap;
  tooltip.style.left = `${left}px`;
  tooltip.style.top = `${Math.max(8, topCandidate)}px`;
}

function attachFloatingDescriptionTooltip(element) {
  if (!element?.dataset?.description) {
    return;
  }
  if (element.dataset.floatingTooltipAttached === "true") {
    return;
  }
  element.dataset.floatingTooltipAttached = "true";
  const show = () => {
    if (!element.dataset.description) {
      setHidden(ensureFloatingDescriptionTooltip(), true);
      document.body?.removeAttribute("data-floating-tooltip-active");
      return;
    }
    const tooltip = ensureFloatingDescriptionTooltip();
    tooltip.textContent = window.CardsAgainstAiI18n?.t
      ? window.CardsAgainstAiI18n.t(element.dataset.description)
      : element.dataset.description;
    setHidden(tooltip, false);
    document.body?.setAttribute("data-floating-tooltip-active", "true");
    positionFloatingDescriptionTooltip(element, tooltip);
  };
  const hide = () => {
    setHidden(ensureFloatingDescriptionTooltip(), true);
    document.body?.removeAttribute("data-floating-tooltip-active");
  };
  element.addEventListener("mouseenter", show);
  element.addEventListener("focus", show);
  element.addEventListener("mousemove", () => {
    const tooltip = ensureFloatingDescriptionTooltip();
    if (!tooltip.classList.contains("hidden")) {
      positionFloatingDescriptionTooltip(element, tooltip);
    }
  });
  element.addEventListener("mouseleave", hide);
  element.addEventListener("blur", hide);
}

function setCollapsed(element, isCollapsed) {
  element.classList.toggle("collapsed", isCollapsed);
  element.setAttribute("aria-hidden", String(isCollapsed));
}

function isGameScreenActive() {
  return Boolean(elements?.gameStage && !elements.gameStage.classList.contains("hidden"));
}

function allowsOneShotAnimations() {
  return state.performanceMode === "full" || state.performanceMode === "balanced";
}

function allowsCardStack() {
  return state.performanceMode === "full" || state.performanceMode === "balanced";
}

function allowsProfileCustomizationDisplay(options = {}) {
  return state.performanceMode !== "minimal" || options.preview;
}

function getPerformanceOverlayKind(kind) {
  if (state.performanceMode !== "minimal") {
    return normalizeStatFlashKind(kind);
  }
  const normalized = normalizeStatFlashKind(kind);
  if (["negative", "burning", "lightning", "bomb", "sudden-death", "no-mercy", "doom", "sabotage"].includes(normalized)) {
    return "negative";
  }
  if (["mixed", "chaos", "outage", "black-market", "casino"].includes(normalized)) {
    return "mixed";
  }
  return "positive";
}

function shouldPlayMenuBackgroundVideo() {
  if (!elements.modeScreen || !elements.menuBackgroundVideo) {
    return false;
  }
  const backgroundScreenVisible = [
    elements.modeScreen,
    elements.roomScreen,
    elements.joinScreen,
    elements.roomLobbyScreen
  ].some((screen) => screen && !screen.classList.contains("hidden"));
  if (!backgroundScreenVisible || document.visibilityState === "hidden") {
    return false;
  }
  if (state.performanceMode === "low-power" || state.performanceMode === "minimal") {
    return false;
  }
  return !(typeof window.matchMedia === "function" && window.matchMedia("(prefers-reduced-motion: reduce)").matches);
}

function syncMenuBackgroundVideoSource(video = elements.menuBackgroundVideo) {
  if (!video) {
    return false;
  }
  const sourceKey = state.performanceMode === "full" ? "fullSrc" : "balancedSrc";
  let changed = false;
  video.querySelectorAll("source").forEach((source) => {
    const nextSource = source.dataset[sourceKey] || source.dataset.balancedSrc || source.getAttribute("src");
    if (nextSource && source.getAttribute("src") !== nextSource) {
      source.setAttribute("src", nextSource);
      changed = true;
    }
  });
  if (changed) {
    video.load();
  }
  return changed;
}

function syncMenuBackgroundVideo() {
  const video = elements.menuBackgroundVideo;
  const shouldPlay = shouldPlayMenuBackgroundVideo();
  document.body?.toggleAttribute("data-menu-active", shouldPlay);
  if (!video) {
    return;
  }
  syncMenuBackgroundVideoSource(video);
  if (!shouldPlay) {
    video.pause();
    return;
  }
  const playPromise = video.play();
  if (playPromise && typeof playPromise.catch === "function") {
    playPromise.catch(() => {});
  }
}

function applyPerformanceMode(mode = state.performanceMode) {
  const normalized = normalizePerformanceMode(mode);
  state.performanceMode = normalized;
  document.body?.setAttribute("data-performance-mode", normalized);
  document.body?.toggleAttribute("data-game-active", isGameScreenActive());
  if (!allowsCardStack()) {
    clearQuestionCardPile();
    if (elements.answerStackButton) {
      setHidden(elements.answerStackButton, true);
    }
    elements.cardsArea?.classList.remove("answer-stack-mode");
  }
  refreshPerformanceModeSurfaces();
  syncMenuBackgroundVideo();
}

function refreshPerformanceModeSurfaces() {
  renderProfile();
  renderLeaderboard();
  renderRoomPlayers();
  renderRoomChat();
  renderHostedRooms({ force: true });
  refreshAnswerCardCustomizationSurfaces();
  if (state.performanceMode === "minimal") {
    applyProfileCustomizationSurface(getBlackCardElement(), defaultProfileCustomization);
  }
}

function updatePerformanceMode(value) {
  const mode = normalizePerformanceMode(value);
  localStorage.setItem(performanceModeStorageKey, mode);
  applyPerformanceMode(mode);
  cacheUserStorageSnapshotNow();
  scheduleUserStorageSnapshot();
  syncSettingsControls();
  renderScore();
  playSound("click");
}

function hideModalWithMotion(element) {
  if (!element || element.classList.contains("hidden")) {
    return;
  }
  if (modalCloseTimers.has(element)) {
    return;
  }
  element.classList.remove("motion-opening");
  element.classList.add("closing");
  const timerId = window.setTimeout(() => {
    modalCloseTimers.delete(element);
    element.classList.remove("closing");
    setHidden(element, true);
  }, 240);
  modalCloseTimers.set(element, timerId);
}

function normalizeTriviaAnswer(answer) {
  return String(answer || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/&/g, "and")
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .replace(/\b(the|a|an)\b/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

const commonTriviaAbbreviationAliases = new Map([
  ["youtube", ["yt", "u tube"]],
  ["instagram", ["ig", "insta"]],
  ["facebook", ["fb"]],
  ["tiktok", ["tt", "tik tok"]],
  ["twitter", ["x", "twttr"]],
  ["reddit", ["rdt"]],
  ["discord", ["dc"]],
  ["snapchat", ["sc"]],
  ["wikipedia", ["wiki"]],
  ["javascript", ["js"]],
  ["typescript", ["ts"]],
  ["artificial intelligence", ["ai"]],
  ["virtual reality", ["vr"]],
  ["augmented reality", ["ar"]],
  ["united states", ["us", "usa", "u s", "u s a"]],
  ["united states of america", ["us", "usa", "u s", "u s a"]],
  ["united kingdom", ["uk", "u k"]],
  ["european union", ["eu", "e u"]],
  ["united nations", ["un", "u n"]],
  ["world war", ["ww"]],
  ["world wide web", ["www"]],
  ["national basketball association", ["nba"]],
  ["national football league", ["nfl"]],
  ["major league baseball", ["mlb"]],
  ["national hockey league", ["nhl"]]
]);

function getTriviaAnswerAcronym(value) {
  return normalizeTriviaAnswer(value)
    .split(" ")
    .filter(Boolean)
    .map((word) => word[0])
    .join("");
}

function getKnownTriviaAbbreviations(normalizedAccepted) {
  const aliases = new Set();
  const compactAccepted = String(normalizedAccepted || "").replace(/\s+/g, "");
  const directAliases = commonTriviaAbbreviationAliases.get(normalizedAccepted)
    || commonTriviaAbbreviationAliases.get(compactAccepted);
  (directAliases || []).forEach((alias) => aliases.add(normalizeTriviaAnswer(alias)));
  const acronym = getTriviaAnswerAcronym(normalizedAccepted);
  if (acronym && acronym.length >= 2) {
    aliases.add(acronym);
  }
  return [...aliases].filter(Boolean);
}

function isKnownTriviaAbbreviation(normalizedAnswer, normalizedAccepted) {
  if (!normalizedAnswer || !normalizedAccepted) {
    return false;
  }
  return getKnownTriviaAbbreviations(normalizedAccepted).includes(normalizedAnswer);
}

function levenshteinDistance(a, b) {
  if (a === b) return 0;
  if (!a.length) return b.length;
  if (!b.length) return a.length;
  const previous = Array.from({ length: b.length + 1 }, (_, index) => index);
  const current = new Array(b.length + 1);
  for (let i = 1; i <= a.length; i += 1) {
    current[0] = i;
    for (let j = 1; j <= b.length; j += 1) {
      current[j] = Math.min(
        previous[j] + 1,
        current[j - 1] + 1,
        previous[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)
      );
    }
    previous.splice(0, previous.length, ...current);
  }
  return previous[b.length];
}

function getCharacterOverlapRatio(left, right) {
  const counts = new Map();
  String(left || "").split("").forEach((char) => {
    counts.set(char, (counts.get(char) || 0) + 1);
  });
  let shared = 0;
  String(right || "").split("").forEach((char) => {
    const count = counts.get(char) || 0;
    if (count > 0) {
      shared += 1;
      counts.set(char, count - 1);
    }
  });
  return shared / Math.max(String(right || "").length, 1);
}

function isMessyTriviaTypo(answer, acceptedAnswer) {
  const answerWord = normalizeTriviaAnswer(answer);
  const acceptedWord = normalizeTriviaAnswer(acceptedAnswer);
  const shortest = Math.min(answerWord.length, acceptedWord.length);
  const longest = Math.max(answerWord.length, acceptedWord.length);
  return shortest >= 7
    && longest - shortest <= 2
    && answerWord[0] === acceptedWord[0]
    && answerWord[answerWord.length - 1] === acceptedWord[acceptedWord.length - 1]
    && getCharacterOverlapRatio(answerWord, acceptedWord) >= 0.8;
}

function createLooseTriviaPhoneticKey(value) {
  const cleaned = normalizeTriviaAnswer(value)
    .replace(/ph/g, "f")
    .replace(/ght/g, "t")
    .replace(/[cq]/g, "k")
    .replace(/x/g, "ks")
    .replace(/z/g, "s")
    .replace(/(.)\1+/g, "$1")
    .replace(/[sxz]+$/g, "");
  if (!cleaned) {
    return "";
  }
  return `${cleaned[0]}${cleaned.slice(1).replace(/[aeiouy\s]/g, "")}`;
}

function isLooseTriviaPhoneticMatch(answer, acceptedAnswer) {
  const answerWord = normalizeTriviaAnswer(answer);
  const acceptedWord = normalizeTriviaAnswer(acceptedAnswer);
  const shortest = Math.min(answerWord.length, acceptedWord.length);
  if (shortest < 7) {
    return false;
  }
  const answerPhonetic = createLooseTriviaPhoneticKey(answerWord);
  const acceptedPhonetic = createLooseTriviaPhoneticKey(acceptedWord);
  if (!answerPhonetic || !acceptedPhonetic || answerPhonetic[0] !== acceptedPhonetic[0]) {
    return false;
  }
  if (answerPhonetic === acceptedPhonetic && Math.max(answerPhonetic.length, acceptedPhonetic.length) >= 2) {
    return true;
  }
  const phoneticDistance = levenshteinDistance(answerPhonetic, acceptedPhonetic);
  const phoneticLongest = Math.max(answerPhonetic.length, acceptedPhonetic.length, 1);
  const phoneticSimilarity = 1 - (phoneticDistance / phoneticLongest);
  const wordDistance = levenshteinDistance(answerWord, acceptedWord);
  const wordLongest = Math.max(answerWord.length, acceptedWord.length, 1);
  const wordSimilarity = 1 - (wordDistance / wordLongest);
  return Math.min(answerPhonetic.length, acceptedPhonetic.length) >= 4
    && phoneticDistance <= 2
    && phoneticSimilarity >= 0.58
    && wordSimilarity >= 0.5
    && getCharacterOverlapRatio(answerWord, acceptedWord) >= 0.64;
}

function isNearTriviaMatch(answer, acceptedAnswer) {
  const normalized = normalizeTriviaAnswer(answer);
  const accepted = normalizeTriviaAnswer(acceptedAnswer);
  if (!normalized || !accepted) return false;
  if (normalized === accepted) return true;
  if (accepted.length >= 5 && (normalized.includes(accepted) || accepted.includes(normalized))) return true;
  if (isLooseTriviaPhoneticMatch(normalized, accepted)) return true;
  if (isMessyTriviaTypo(normalized, accepted)) return true;
  const distance = levenshteinDistance(normalized, accepted);
  const allowedDistance = accepted.length >= 10 ? 2 : 1;
  return distance <= allowedDistance;
}

function scoreTriviaAnswer(card, isCorrect = false) {
  const answerKey = [state.canonicalAnswer, ...state.acceptedAnswers].filter(Boolean);
  const normalized = normalizeTriviaAnswer(card);
  const canonical = normalizeTriviaAnswer(state.canonicalAnswer);
  const words = normalized ? normalized.split(" ") : [];
  let score = isCorrect ? 64 : 18;

  if (canonical && normalized === canonical) {
    score += 60;
  } else if (answerKey.some((answer) => normalizeTriviaAnswer(answer) === normalized)) {
    score += 42;
  } else if (answerKey.some((answer) => isNearTriviaMatch(card, answer))) {
    score += 28;
  }

  if (isCorrect && /[A-Z][a-z]{5,}/.test(card)) {
    score += 14;
  }

  if (isCorrect && words.length >= 2 && words.length <= 5) {
    score += 10;
  }

  if (isCorrect && /[0-9]/.test(card)) {
    score += 6;
  }

  if (!isCorrect && words.length <= 1) {
    score -= 8;
  }

  return Math.max(0, Math.min(140, score));
}

function pickBadgeForScore(score, isWinner) {
  const tiers = isWinner ? winnerBadgeTiers : loserBadgeTiers;
  return tiers.find((tier) => score >= tier.minScore) || tiers[tiers.length - 1];
}

function getCardRatings(cards, winnerIndex, correctIndexes = [winnerIndex]) {
  const correctSet = new Set(correctIndexes);
  return cards.map((card, index) => {
    const isCorrect = correctSet.has(index);
    if (isMultipleChoiceRound()) {
      return getMultipleChoiceRatingForOwner(getOwnerFromCardIndex(index), isCorrect);
    }
    const score = scoreTriviaAnswer(card, isCorrect);
    const badge = pickBadgeForScore(score, isCorrect);
    return {
      label: badge.label,
      bonus: isCorrect ? badge.bonus : 0,
      correct: isCorrect,
      score
    };
  });
}

function getRoundCardOwners() {
  if (Array.isArray(state.roundCardOwners) && state.roundCardOwners.length) {
    return state.roundCardOwners;
  }
  if (isRoomMode()) {
    return getActiveOwners();
  }
  return isDuelMode() ? ["player", "opponent"] : ["player", ...getActiveBotOwnerIds()];
}

function getAnswerCardNodes() {
  return [...elements.cardsArea.querySelectorAll(".white-card")];
}

function normalizeAnswerDamageMap(value = {}) {
  const source = value && typeof value === "object" ? value : {};
  return Object.fromEntries(
    Object.entries(source)
      .filter(([owner, damaged]) => owner && damaged)
      .map(([owner, damaged]) => [String(owner), Boolean(damaged)])
  );
}

function markAnswerCardDamaged(owner, amount = 0) {
  if (!owner || !getActiveOwners().includes(owner) || Math.max(0, Number(amount) || 0) <= 0) {
    return false;
  }
  state.roundAnswerDamageByOwner = normalizeAnswerDamageMap(state.roundAnswerDamageByOwner);
  state.roundAnswerDamageByOwner[owner] = true;
  return true;
}

function isAnswerCardDamaged(owner) {
  return Boolean(normalizeAnswerDamageMap(state.roundAnswerDamageByOwner)[owner]);
}

function getDamagedAnswerParticipantIds() {
  return Object.keys(normalizeAnswerDamageMap(state.roundAnswerDamageByOwner))
    .map(getRoomParticipantIdForOwner)
    .filter(Boolean);
}

function applyDamagedAnswerParticipantIds(participantIds = []) {
  if (!Array.isArray(participantIds)) {
    return false;
  }
  const nextDamage = {};
  participantIds
    .map((participantId) => getRoomOwnerForParticipantId(participantId))
    .filter((owner) => owner && getActiveOwners().includes(owner))
    .forEach((owner) => {
      nextDamage[owner] = true;
    });
  state.roundAnswerDamageByOwner = normalizeAnswerDamageMap({
    ...state.roundAnswerDamageByOwner,
    ...nextDamage
  });
  return Object.keys(nextDamage).length > 0;
}

const answerDamagePowerTypes = new Set([
  "sabotage",
  "lightning_strike",
  "zap_strike",
  "get_good",
  "shameless",
  "loose_cannon",
  "hitman",
  "execution",
  "haha_you_lose",
  "lawsuit",
  "red_button",
  "thermal_scythe"
]);

function getTargetedPowerDamageAmount(entry, deltas = {}) {
  const meta = getEntryMeta(entry);
  const target = getEntryTarget(entry);
  if (
    !entry?.power?.targeted
    || !answerDamagePowerTypes.has(entry.power.type)
    || !target
    || target === entry.owner
    || !getActiveOwners().includes(target)
  ) {
    return 0;
  }
  const immediateLoss = Math.max(0, Number(meta.appliedLoss) || 0, Number(meta.stolenAmount) || 0);
  if (immediateLoss > 0) {
    return immediateLoss;
  }
  return Math.abs(Math.min(0, Number(deltas?.[target]) || 0));
}

function markTargetedPowerAnswerDamage(entry, deltas = {}) {
  const amount = getTargetedPowerDamageAmount(entry, deltas);
  return markAnswerCardDamaged(getEntryTarget(entry), amount);
}

function collectTargetedPowerAnswerDamage(playedEntries = [], deltas = {}) {
  const damagedOwners = new Set(Object.keys(normalizeAnswerDamageMap(state.roundAnswerDamageByOwner)));
  playedEntries.forEach((entry) => {
    if (markTargetedPowerAnswerDamage(entry, deltas)) {
      damagedOwners.add(getEntryTarget(entry));
    }
  });
  state.roundAnswerDamageByOwner = normalizeAnswerDamageMap(
    Object.fromEntries([...damagedOwners].map((owner) => [owner, true]))
  );
  return [...damagedOwners].filter((owner) => getActiveOwners().includes(owner));
}

function decorateAwardWithAnswerDamage(awarded, playedEntries = getPlayedPowerEntries(), deltas = awarded?.deltas || {}) {
  if (!awarded || typeof awarded !== "object") {
    return awarded;
  }
  const damagedOwners = collectTargetedPowerAnswerDamage(playedEntries, deltas);
  awarded.damagedOwners = damagedOwners;
  awarded.damagedParticipantIds = isRoomMode() ? damagedOwners.map(getRoomParticipantIdForOwner).filter(Boolean) : [];
  return awarded;
}

function createAnswerCardNode(owner, cardIndex = 0) {
  const card = document.createElement("article");
  card.className = "white-card";
  card.dataset.owner = owner;
  card.dataset.cardIndex = String(cardIndex);
  const ownerPlayer = getPlayer(owner);
  card.classList.toggle("bot-answer-card", Boolean(ownerPlayer?.bot || ownerPlayer?.type === "bot"));
  card.tabIndex = 0;
  const answerOwner = document.createElement("div");
  answerOwner.className = "answer-owner";
  const avatar = document.createElement("span");
  avatar.className = "answer-avatar";
  avatar.setAttribute("aria-hidden", "true");
  renderAvatar(avatar, ownerPlayer || { label: getOwnerLabel(owner) });
  const label = document.createElement("span");
  renderPlayerNameWithTitle(label, owner, getOwnerLabel(owner));
  answerOwner.append(avatar, label);
  const badge = document.createElement("strong");
  badge.className = "rating-badge hidden";
  badge.tabIndex = -1;
  const text = document.createElement("p");
  const gradingReason = document.createElement("small");
  gradingReason.className = "grading-reason hidden";
  const hintMarker = document.createElement("span");
  hintMarker.className = "answer-hint-marker hidden";
  hintMarker.dataset.tooltip = "Used a hint this round.";
  hintMarker.setAttribute("aria-label", "Used a hint this round.");
  const hintIcon = document.createElement("img");
  hintIcon.src = "assets/ui/lighting-bulb.svg";
  hintIcon.alt = "";
  hintIcon.setAttribute("aria-hidden", "true");
  hintMarker.appendChild(hintIcon);
  card.append(answerOwner, badge, text, gradingReason, hintMarker);
  if (shouldUseAnswerCardCustomization(owner)) {
    applyProfileCustomizationSurface(card, getProfileCardCustomizationForOwner(owner) || defaultProfileCustomization, {
      forceCustom: isRoomMode()
    });
  } else {
    applyProfileCustomizationSurface(card, defaultProfileCustomization);
  }
  return card;
}

function updateRatingBadge(badge, rating, reason = "") {
  if (!badge) {
    return;
  }
  const visible = Boolean(rating);
  badge.textContent = visible ? `${rating.label}${rating.bonus ? ` +${rating.bonus}` : ""}` : "";
  badge.classList.toggle("rating-correct", Boolean(rating?.correct));
  badge.classList.toggle("rating-incorrect", Boolean(rating && !rating.correct));
  setHidden(badge, !visible);
  if (visible && reason) {
    badge.dataset.description = reason;
    badge.tabIndex = 0;
    attachFloatingDescriptionTooltip(badge);
  } else {
    delete badge.dataset.description;
    badge.removeAttribute("title");
    badge.tabIndex = -1;
  }
}

function shouldShowInlineGradingReason(reason = "") {
  return /^(?:AI reviewed|AI took a second look)/i.test(String(reason || ""));
}

function updateInlineGradingReason(element, reason = "") {
  if (!element) {
    return;
  }
  const visibleReason = shouldShowInlineGradingReason(reason) ? reason : "";
  element.textContent = visibleReason;
  setHidden(element, !visibleReason);
}

function renderAnswerCardsForOwners(owners = getRoundCardOwners(), indexes = owners.map((_, index) => index)) {
  const cardOwners = owners.length ? owners : getRoundCardOwners();
  getAnswerCardNodes().forEach((card) => card.remove());
  const anchor = elements.answerStackButton || null;
  cardOwners.forEach((owner, position) => {
    const card = createAnswerCardNode(owner, indexes[position] ?? position);
    card.style.order = String(position + 1);
    elements.cardsArea.insertBefore(card, anchor);
  });
  elements.cardsArea.classList.toggle("two-card-mode", cardOwners.length === 2);
  elements.cardsArea.style.setProperty("--answer-card-count", String(Math.min(Math.max(cardOwners.length, 1), 3)));
  if (elements.answerStackButton) {
    elements.cardsArea.appendChild(elements.answerStackButton);
  }
}

function renderCardBadges(cards, winnerIndex, ratings = getCardRatings(cards, winnerIndex), awarded = null) {
  getAnswerCardNodes().forEach((card) => {
    const badge = card.querySelector(".rating-badge");
    const cardIndex = Number(card.dataset.cardIndex);
    const owner = card.dataset.owner || getOwnerFromCardIndex(cardIndex);
    const payout = awarded?.payoutDetails?.[owner];
    const bribedOutcome = payout?.bribedWinner || payout?.bribedLoser;
    const rating = bribedOutcome
      ? {
        ...(ratings[cardIndex] || {}),
        label: payout.tag,
        bonus: 0,
        correct: Boolean(payout.bribedWinner)
      }
      : ratings[cardIndex];
    const reason = state.currentRoundGradingReasons?.[cardIndex] || "";
    updateRatingBadge(badge, rating, reason);
    const gradingReason = card.querySelector(".grading-reason");
    updateInlineGradingReason(gradingReason, reason);
    card.classList.toggle("answer-incorrect", Boolean(rating && !rating.correct));
  });
}

function applyAnswerCardContent(card, cards, ratings, correctIndexes = []) {
  const cardIndex = Number(card.dataset.cardIndex);
  const owner = card.dataset.owner || getRoundCardOwners()[cardIndex] || "";
  const text = card.querySelector("p");
  if (text) {
    text.textContent = cards[cardIndex] || "";
  }
  const badge = card.querySelector(".rating-badge");
  const rating = ratings?.[cardIndex];
  const reason = state.currentRoundGradingReasons?.[cardIndex] || "";
  updateRatingBadge(badge, rating, reason);
  const gradingReason = card.querySelector(".grading-reason");
  updateInlineGradingReason(gradingReason, reason);
  card.classList.toggle("answer-priority", correctIndexes.includes(cardIndex));
  card.classList.toggle("answer-incorrect", Boolean(rating && !rating.correct));
  const hintMarker = card.querySelector(".answer-hint-marker");
  const participantId = getRoomParticipantIdForOwner(owner);
  const participant = participantId
    ? state.roomParticipants.find((entry) => entry.id === participantId)
    : null;
  const usedHint = Boolean(
    state.roundHintUsage[owner]
      || participant?.usedHintRound === state.round
      || state.roomGame?.answers?.[participantId]?.usedHint
  );
  setHidden(hintMarker, !usedHint);
}

function getOwnAnswerCardIndex(cards) {
  const owners = getRoundCardOwners();
  const ownOwner = isRoomMode() && state.currentOwner !== "spectator" ? state.currentOwner : "player";
  const ownIndex = owners.indexOf(ownOwner);
  return ownIndex >= 0 && ownIndex < cards.length ? ownIndex : 0;
}

function getBestOtherAnswerIndex(cards, correctIndexes = [], preferredIndex = -1, ownIndex = getOwnAnswerCardIndex(cards)) {
  let picked = -1;
  const add = (index) => {
    if (picked < 0 && Number.isInteger(index) && index >= 0 && index < cards.length && index !== ownIndex) {
      picked = index;
    }
  };
  add(preferredIndex);
  correctIndexes.forEach(add);
  cards.forEach((_, index) => add(index));
  return picked;
}

function getAnswerStackCycleIndexes(cards) {
  if (state.isSpectator && isRoomMode()) {
    const pinnedCount = getSpectatorPinnedAnswerCardCount(cards);
    return cards.map((_, index) => index).filter((index) => index >= pinnedCount);
  }
  const ownIndex = getOwnAnswerCardIndex(cards);
  return cards.map((_, index) => index).filter((index) => index !== ownIndex);
}

function getSpectatorAnswerCardSlotLimit(cards = []) {
  return (cards || []).length > 9 && allowsCardStack() ? 8 : 9;
}

function getSpectatorPinnedAnswerCardCount(cards = []) {
  return Math.max(0, getSpectatorAnswerCardSlotLimit(cards) - 1);
}

function getAnswerStackCycleSlotPosition() {
  if (state.isSpectator && isRoomMode()) {
    return Math.max(0, state.visibleAnswerCardIndexes.length - 1);
  }
  return 1;
}

function getAnswerStackHiddenCount(cards) {
  if ((cards || []).length <= 3) {
    return 0;
  }
  const cycleIndexes = getAnswerStackCycleIndexes(cards);
  const currentCycleIndex = state.visibleAnswerCardIndexes?.[getAnswerStackCycleSlotPosition()];
  return cycleIndexes.filter((index) => index !== currentCycleIndex).length;
}

function fillVisibleAnswerCards(cards, ratings) {
  getAnswerCardNodes().forEach((card) => {
    applyAnswerCardContent(card, cards, ratings, state.currentRoundCorrectIndexes || []);
  });
}

function cycleAnswerStack() {
  if (!allowsCardStack()) {
    return;
  }
  const cards = state.currentRoundCards || [];
  const owners = getRoundCardOwners();
  const ratings = state.currentRoundCardRatings || [];
  const cycleIndexes = getAnswerStackCycleIndexes(cards);
  const cycleSlotPosition = getAnswerStackCycleSlotPosition();
  const currentCycleIndex = state.visibleAnswerCardIndexes?.[cycleSlotPosition];
  const nextIndexes = cycleIndexes.filter((index) => index !== currentCycleIndex);
  if (!nextIndexes.length) {
    return;
  }

  const card = getAnswerCardNodes()[cycleSlotPosition];
  if (!card) {
    return;
  }
  const nextIndex = nextIndexes[state.answerCardCycleCursor % nextIndexes.length];
  state.answerCardCycleCursor += 1;
  state.visibleAnswerCardIndexes[cycleSlotPosition] = nextIndex;

  card.classList.remove("answer-card-cycle-in");
  card.classList.add("answer-card-cycle-out");
  window.setTimeout(() => {
    const owner = owners[nextIndex] || "player";
    const nextCard = createAnswerCardNode(owner, nextIndex);
    nextCard.style.order = String(cycleSlotPosition + 1);
    applyAnswerCardContent(nextCard, cards, ratings, state.currentRoundCorrectIndexes || []);
    if (state.isSpectator && isRoomMode()) {
      decorateSpectatorAnswerCard(nextCard, nextIndex);
    }
    nextCard.classList.add("answer-card-cycle-in");
    card.replaceWith(nextCard);
    window.setTimeout(() => nextCard.classList.remove("answer-card-cycle-in"), 360);
    const hiddenAnswerCount = getAnswerStackHiddenCount(cards);
    if (elements.answerStackButton && elements.answerStackCount) {
      elements.answerStackCount.textContent = `+${hiddenAnswerCount}`;
      setHidden(elements.answerStackButton, hiddenAnswerCount === 0);
    }
  }, 130);
  playSound("switchCards");
}

function renderAnswerCardLayout(cards, correctIndexes = [], preferredIndex = -1) {
  const owners = getRoundCardOwners().slice(0, cards.length);
  const ownIndex = getOwnAnswerCardIndex(cards);
  const bestOtherIndex = getBestOtherAnswerIndex(cards, correctIndexes, preferredIndex, ownIndex);
  if (state.isSpectator && isRoomMode()) {
    const maxVisibleCards = getSpectatorAnswerCardSlotLimit(cards);
    const directIndexes = cards.map((_, index) => index).slice(0, maxVisibleCards);
    state.visibleAnswerCardIndexes = directIndexes;
  } else if (!allowsCardStack()) {
    state.visibleAnswerCardIndexes = [ownIndex];
    if (bestOtherIndex >= 0 && bestOtherIndex !== ownIndex) {
      state.visibleAnswerCardIndexes.push(bestOtherIndex);
    }
  } else if (cards.length <= 3) {
    const directIndexes = [ownIndex];
    if (bestOtherIndex >= 0 && !directIndexes.includes(bestOtherIndex)) {
      directIndexes.push(bestOtherIndex);
    }
    cards.forEach((_, index) => {
      if (!directIndexes.includes(index)) {
        directIndexes.push(index);
      }
    });
    state.visibleAnswerCardIndexes = directIndexes;
  } else {
    state.visibleAnswerCardIndexes = bestOtherIndex >= 0 ? [ownIndex, bestOtherIndex] : [ownIndex];
  }
  state.answerCardCycleCursor = 0;
  renderAnswerCardsForOwners(
    state.visibleAnswerCardIndexes.map((index) => owners[index]),
    state.visibleAnswerCardIndexes
  );
  const cardNodes = getAnswerCardNodes();
  const correctSet = new Set(correctIndexes);
  cardNodes.forEach((node) => {
    if (!node) {
      return;
    }
    const cardIndex = Number(node.dataset.cardIndex);
    node.style.order = String((state.visibleAnswerCardIndexes.indexOf(cardIndex) + 1) || 1);
    node.classList.toggle("answer-priority", correctSet.has(cardIndex));
    if (state.isSpectator && isRoomMode()) {
      decorateSpectatorAnswerCard(node, cardIndex);
    }
  });

  const hiddenAnswerCount = getAnswerStackHiddenCount(cards);
  if (elements.answerStackButton && elements.answerStackCount) {
    const stackOrder = state.isSpectator && isRoomMode() ? "9" : "3";
    elements.answerStackButton.style.order = stackOrder;
    elements.answerStackCount.textContent = `+${hiddenAnswerCount}`;
    const showStackButton = allowsCardStack() && hiddenAnswerCount > 0;
    setHidden(elements.answerStackButton, !showStackButton);
    elements.cardsArea.classList.toggle("answer-stack-mode", showStackButton);
    elements.cardsArea.classList.toggle("spectator-answer-mode", Boolean(state.isSpectator && isRoomMode()));
    elements.cardsArea.classList.toggle("two-card-mode", !showStackButton && state.visibleAnswerCardIndexes.length === 2);
    elements.cardsArea.style.setProperty("--answer-card-count", String(state.isSpectator && isRoomMode()
      ? Math.min(9, Math.max(1, state.visibleAnswerCardIndexes.length + (showStackButton ? 1 : 0)))
      : showStackButton ? 3 : Math.max(1, state.visibleAnswerCardIndexes.length)));
    if (state.isSpectator && isRoomMode()) {
      elements.cardsArea.style.setProperty("--spectator-answer-columns", String(Math.min(3, Math.max(1, state.visibleAnswerCardIndexes.length + (showStackButton ? 1 : 0)))));
    } else {
      elements.cardsArea.style.removeProperty("--spectator-answer-columns");
    }
  }
}

function getSpectatorAnswerDraftForOwner(owner) {
  const participantId = getRoomParticipantIdForOwner(owner);
  const draft = participantId ? state.spectatorAnswerDrafts[participantId] : null;
  if (!draft) {
    return null;
  }
  if (Number(draft.round) !== Number(state.round) || !roomPayloadMatchesCurrentMatch(draft)) {
    return null;
  }
  return draft;
}

function getSpectatorAnswerTextForOwner(owner) {
  const draft = getSpectatorAnswerDraftForOwner(owner);
  if (draft && !state.roomSubmissions[owner]) {
    return cleanAnswerDraft(draft.answer || "");
  }
  const participantId = getRoomParticipantIdForOwner(owner);
  const participant = participantId ? state.roomParticipants.find((entry) => entry.id === participantId) : null;
  if (
    participant
    && Number(participant.submittedRound) === Number(state.round)
    && participantSubmissionMatchesCurrentMatch(participant)
  ) {
    return cleanAnswerDraft(participant.answer || getLockedRoundAnswer(owner));
  }
  return cleanAnswerDraft(getLockedRoundAnswer(owner));
}

function decorateSpectatorAnswerCard(card, cardIndex) {
  if (!card || !state.isSpectator || !isRoomMode()) {
    return;
  }
  const owner = getRoundCardOwners()[cardIndex] || "";
  const participantId = getRoomParticipantIdForOwner(owner);
  const participant = participantId ? state.roomParticipants.find((entry) => entry.id === participantId) : null;
  const text = card.querySelector("p");
  const answer = getSpectatorAnswerTextForOwner(owner);
  const displayAnswer = answer.trim() ? answer : "";
  const submitted = Boolean(state.roomSubmissions[owner])
    || Boolean(
      participant
      && Number(participant.submittedRound) === Number(state.round)
      && participantSubmissionMatchesCurrentMatch(participant)
    );
  card.classList.add("spectator-answer-card");
  card.classList.toggle("spectator-draft-empty", !displayAnswer);
  if (text) {
    text.textContent = displayAnswer || (submitted ? "Submitted blank" : "Typing...");
  }
  card.querySelector(".answer-owner .spectator-submitted-pill")?.remove();
  const existingPill = card.querySelector(":scope > .spectator-submitted-pill");
  if (submitted && !existingPill) {
    const pill = document.createElement("span");
    pill.className = "spectator-submitted-pill";
    pill.textContent = "Submitted";
    card.appendChild(pill);
  } else if (!submitted && existingPill) {
    existingPill.remove();
  }
  updateRatingBadge(card.querySelector(".rating-badge"), null, "");
}

function renderSpectatorAnswerCards() {
  if (!state.isSpectator || !isRoomMode() || elements.gameStage.classList.contains("hidden")) {
    return false;
  }
  if (!elements.verdictPanel.classList.contains("hidden") || state.gradingActive || state.matchEnded) {
    return false;
  }
  const owners = getActiveOwners();
  if (!owners.length) {
    setHidden(elements.cardsArea, true);
    return false;
  }
  const cards = owners.map((owner) => getSpectatorAnswerTextForOwner(owner));
  state.roundCardOwners = owners;
  state.currentRoundCards = cards;
  state.currentRoundCardRatings = [];
  state.currentRoundCorrectIndexes = [];
  renderAnswerCardLayout(cards, [], -1);
  elements.cardsArea.classList.add("spectator-answer-mode");
  setHidden(elements.cardsArea, false);
  return true;
}

function clearCardBadges() {
  document.querySelectorAll(".white-card .rating-badge").forEach((badge) => {
    updateRatingBadge(badge, null, "");
  });
  getAnswerCardNodes().forEach((card) => {
    card.style.order = "";
    card.classList.remove("answer-priority", "answer-incorrect", "winner");
    const gradingReason = card.querySelector(".grading-reason");
    if (gradingReason) {
      gradingReason.textContent = "";
      setHidden(gradingReason, true);
    }
  });
  if (elements.answerStackButton) {
    setHidden(elements.answerStackButton, true);
  }
  elements.cardsArea.classList.remove("answer-stack-mode");
  elements.cardsArea.classList.remove("spectator-answer-mode");
}

function renderQuestionImagePlaceholder(message = "Waiting for image...", options = {}) {
  state.questionImageLoadId += 1;
  setHidden(elements.questionImageWrap, false);
  elements.questionImageWrap.classList.remove("image-loaded");
  elements.questionImage.onload = null;
  elements.questionImage.onerror = null;
  elements.questionImage.removeAttribute("src");
  elements.questionImage.alt = "";
  setHidden(elements.questionImage, true);
  elements.questionImagePlaceholder.textContent = message;
  setHidden(elements.questionImagePlaceholder, false);
  elements.questionImageCredit.textContent = "";
  setHidden(elements.questionImageCredit, true);
  if (!options.skipFit) {
    scheduleBlackCardFit();
  }
}

function renderQuestionImage(image = state.questionImage, options = {}) {
  if (!image?.url && state.questionType === "text") {
    state.questionImageLoadId += 1;
    elements.questionImageWrap.classList.remove("image-loaded");
    elements.questionImage.onload = null;
    elements.questionImage.onerror = null;
    elements.questionImage.removeAttribute("src");
    elements.questionImage.alt = "";
    elements.questionImageCredit.textContent = "";
    setHidden(elements.questionImageWrap, true);
    setHidden(elements.questionImage, true);
    setHidden(elements.questionImagePlaceholder, true);
    setHidden(elements.questionImageCredit, true);
    if (!options.skipFit) {
      scheduleBlackCardFit();
    }
    return;
  }

  const safeImage = image && image.url ? image : null;
  const hasImage = Boolean(safeImage && safeImage.url);
  if (!hasImage) {
    state.questionImageLoadId += 1;
    setHidden(elements.questionImageWrap, false);
    elements.questionImageWrap.classList.remove("image-loaded");
    elements.questionImage.onload = null;
    elements.questionImage.onerror = null;
    elements.questionImage.removeAttribute("src");
    elements.questionImage.alt = "";
    setHidden(elements.questionImage, true);
    elements.questionImagePlaceholder.textContent = "Image not retrieved";
    setHidden(elements.questionImagePlaceholder, false);
    elements.questionImageCredit.textContent = "";
    setHidden(elements.questionImageCredit, true);
    if (!options.skipFit) {
      scheduleBlackCardFit();
    }
    return;
  }

  const loadId = state.questionImageLoadId + 1;
  state.questionImageLoadId = loadId;
  setHidden(elements.questionImageWrap, false);
  elements.questionImageWrap.classList.remove("image-loaded");
  const showLoadedImage = () => {
    if (state.questionImageLoadId !== loadId) return;
    elements.questionImageWrap.classList.add("image-loaded");
    setHidden(elements.questionImage, false);
    setHidden(elements.questionImagePlaceholder, true);
    if (!options.skipFit) {
      scheduleBlackCardFit();
    }
  };
  elements.questionImage.onload = () => {
    showLoadedImage();
  };
  elements.questionImage.onerror = () => {
    if (state.questionImageLoadId !== loadId) return;
    elements.questionImageWrap.classList.remove("image-loaded");
    renderQuestionImagePlaceholder("Image not retrieved", options);
  };
  elements.questionImage.alt = safeImage.alt || "Trivia question reference image";
  elements.questionImageCredit.textContent = safeImage.credit || "";
  setHidden(elements.questionImageCredit, !safeImage.credit);
  elements.questionImage.removeAttribute("src");
  setHidden(elements.questionImage, false);
  elements.questionImagePlaceholder.textContent = "Waiting for image...";
  setHidden(elements.questionImagePlaceholder, true);
  elements.questionImage.src = safeImage.url;
  if (elements.questionImage.complete && elements.questionImage.naturalWidth > 0) {
    showLoadedImage();
  }
  if (!options.skipFit) {
    scheduleBlackCardFit();
  }
}

function renderPowerLog(awarded) {
  elements.powerLog.replaceChildren();
  const events = (awarded.events || []).filter((event) => typeof event === "string" || !event.secret);
  setHidden(elements.powerLogToggle, events.length === 0);
  if (!events.length) {
    elements.powerLog.classList.add("power-log-collapsed");
    setHidden(elements.powerLog, true);
    return;
  }

  elements.powerLogToggle.textContent = `Power Effects (${events.length})`;
  elements.powerLogToggle.setAttribute("aria-expanded", "false");
  elements.powerLog.classList.add("power-log-collapsed");
  setHidden(elements.powerLog, true);

  events.forEach((event) => {
    const item = document.createElement("span");
    item.className = "power-play";
    const text = typeof event === "string" ? event : event.text;
    const power = typeof event === "string" ? null : getPowerById(event.powerId);
    item.textContent = text;
    if (power) {
      item.dataset.rarity = power.rarity;
      item.classList.toggle("chaos-infused", isChaosInfusedPower(power));
      item.dataset.description = power.description;
      attachFloatingDescriptionTooltip(item);
    }
    elements.powerLog.appendChild(item);
  });
}

function setPowerLogExpanded(isExpanded) {
  elements.powerLogToggle.setAttribute("aria-expanded", String(isExpanded));
  if (isExpanded) {
    setHidden(elements.powerLog, false);
    window.requestAnimationFrame(() => {
      elements.powerLog.classList.remove("power-log-collapsed");
    });
    return;
  }

  elements.powerLog.classList.add("power-log-collapsed");
  window.setTimeout(() => {
    if (elements.powerLog.classList.contains("power-log-collapsed")) {
      setHidden(elements.powerLog, true);
    }
  }, 280);
}

function createActiveEffect(owner, powerId, name, description, options = {}) {
  const effectPowerId = options.chaosInfused && canPowerBecomeChaosInfused(powerId)
    ? getChaosInfusedPowerId(powerId)
    : powerId;
  const power = getPowerById(effectPowerId);
  return {
    owner,
    label: owner === "table" ? "Table" : getOwnerLabel(owner),
    name,
    description,
    rarity: power?.rarity || "grey",
    powerId: effectPowerId,
    chaosInfused: Boolean(options.chaosInfused || isChaosInfusedPower(effectPowerId)),
    private: Boolean(options.private)
  };
}

