function showWaitingForHostRoundSetup(round = state.round) {
  stopLoadingMessages();
  elements.loadingPanel.dataset.loadingState = "waiting-host";
  elements.loadingText.textContent = `Waiting for the host to deal round ${round}...`;
  setHidden(elements.loadingPanel, false);
  setHidden(elements.errorPanel, true);
  setHidden(elements.inputPanel, true);
}

function showRoomRoundSetupSyncWait(message = "Waiting for the room to sync the next question...") {
  stopLoadingMessages();
  elements.loadingPanel.dataset.loadingState = "waiting-host";
  elements.loadingText.textContent = message;
  setHidden(elements.loadingPanel, false);
  setHidden(elements.errorPanel, true);
  setHidden(elements.inputPanel, true);
}

function isCurrentRoundVisiblyPlayable() {
  return Boolean(
    state.questionId
      && state.blackCard
      && elements.gameStage
      && !elements.gameStage.classList.contains("hidden")
      && elements.inputPanel
      && !elements.inputPanel.classList.contains("hidden")
  );
}

function clearStaleRoundSetupWaitIfPlayable() {
  if (!isCurrentRoundVisiblyPlayable()) {
    return false;
  }
  stopLoadingMessages();
  setHidden(elements.loadingPanel, true);
  setHidden(elements.errorPanel, true);
  return true;
}

async function recoverFromStaleRoomRoundSetup(error, context = {}) {
  if (!isRoomMode() || !isStaleRoomSetupError(error)) {
    return false;
  }

  const round = Number(context.round || state.round) || state.round;
  setHidden(elements.errorPanel, true);
  stopLoadingMessages();

  if (!isCurrentRoundSetupWork(context)) {
    return true;
  }

  if (state.questionId && elements.inputPanel && !elements.inputPanel.classList.contains("hidden")) {
    return true;
  }

  let setup = getSyncedRoomSetupForRound(round);
  if (!setup) {
    elements.loadingText.textContent = isCurrentHost()
      ? "Resyncing the shared round..."
      : `Waiting for the host to deal round ${round}...`;
    setHidden(elements.loadingPanel, false);
    setHidden(elements.errorPanel, true);
    await requestRoomRealtimeCatchup("stale-round-setup", { force: true, snapshot: true });
    if (!isCurrentRoundSetupWork(context)) {
      return true;
    }
    setup = getSyncedRoomSetupForRound(round);
  }

  if (setup && isCurrentRoundSetupWork(context)) {
    applyRoundSetup(setup, { skipPublish: true });
    applyRoomGamePowerState();
    return true;
  }

  if (isCurrentRoundSetupWork(context) && !state.questionId) {
    showWaitingForHostRoundSetup(round);
    elements.loadingText.textContent = isCurrentHost()
      ? "Waiting for the room to finish syncing this round..."
      : `Waiting for the host to deal round ${round}...`;
  }

  return true;
}

function getRoundSetupRenderKey(setup, options = {}) {
  const matchKey = String(
    options.matchId
      || setup?.matchId
      || getCurrentRoomMatchId()
      || `local-${state.matchWorkToken}`
  ).trim();
  const roundKey = Number(options.round || setup?.round || state.round) || 0;
  const questionKey = [
    String(setup?.id || "").trim(),
    normalizePromptText(setup?.blackCard)
  ].join(":");
  return [matchKey, roundKey, questionKey].join("|");
}

function renderRound() {
  syncStatFlashRoundPresentation();
  stopNextRoundCountdown();
  stopLoadingMessages();
  clearCardBadges();
  const blackCard = getBlackCardElement();
  const judgePanel = elements.judgeAvatar.closest(".judge-panel");
  const beforeBlackCardHeight = blackCard.getBoundingClientRect().height;
  blackCard.getAnimations?.().forEach((animation) => {
    if (!("animationName" in animation)) {
      animation.cancel();
    }
  });
  blackCard.style.height = `${beforeBlackCardHeight}px`;
  blackCard.style.overflow = "hidden";
  blackCard.classList.remove("completed", "answer-reveal", "dealt", "incoming-question-card");
  blackCard.classList.add("preparing-question-card");
  delete blackCard.dataset.questionStacked;
  const difficulty = normalizeDifficulty(state.questionDifficulty);
  judgePanel.classList.remove("entering");
  elements.judgeAvatar.textContent = state.judge.avatar;
  elements.judgeName.textContent = state.judge.name;
  elements.judgeBio.textContent = `${state.judge.title}. ${state.judge.bio}`;
  elements.judgeTags.replaceChildren(
    ...state.judge.likes.map((tag) => {
      const chip = document.createElement("span");
      chip.textContent = tag;
      return chip;
    })
  );
  elements.blackCardText.textContent = state.blackCard;
  showQuestionHint("");
  elements.questionThemeBadge.textContent = state.triviaTheme || "Mixed Trivia";
  elements.questionDifficultyBadge.textContent = getDifficultyLabel(difficulty);
  elements.questionDifficultyBadge.className = `difficulty-badge difficulty-${difficulty}`;
  renderQuestionImage(state.questionImage, { skipFit: true });
  animateBlackCardToNaturalHeightAfterLayout(blackCard, beforeBlackCardHeight, { allowShrink: true, durationMs: 620 });
  elements.answerInput.value = "";
  elements.playerTwoInput.value = "";
  state.localEntryStep = 1;
  state.localAnswers = { playerOne: "", playerTwo: "" };
  resetRoundAnswers();
  state.answerRemainingTimes = Object.fromEntries(getActiveOwners().map((owner) => [owner, state.timerSeconds]));
  resetRoomSubmissions();
  resetPlayedPowersForRound();
  if (state.renderingSyncedRoomResume) {
    state.currentTableEvent = null;
    state.tableEventSabotageUsed = {};
    state.blackMarketPurchases = {};
    applyTableEventStageClasses();
  } else {
    rollRoundTableEvent();
    rollRoundAmplifiedMultiplier();
  }
  state.timerPenalties = createOwnerValueMap(0);
  state.forcedWinnerOwner = null;
  elements.answerInput.disabled = state.isSpectator;
  elements.playerTwoInput.disabled = false;
  elements.submitButton.disabled = state.isSpectator;
  if (!state.renderingSyncedRoomResume) {
    applyRoundStartEffects();
    applyRoundStartTableEventEffects();
    applyRoomRoundStartModifiers();
    applyPendingLegendaryPowerRewards();
  }
  updateModeUi();
  if (!state.isSpectator) {
    focusAnswerControl();
  }
  scheduleBotPowerUpsForRound();
  scheduleRoomBotAnswersForRound();
  renderSubmissionStatus();
  startTimer();
  if (isRoomRealtimeHealthy()) {
    flushPendingRoomRealtimePayloads(state.roomSettings.code);
  }
  scheduleHostRoomSubmissionDeadline();

  getAnswerCardNodes().forEach((card) => card.classList.remove("winner", "launching"));
  elements.cardsArea.classList.remove("revealed");
  elements.verdictPanel.classList.remove("revealed");
  document.querySelector(".table-surface").classList.remove("winner-moment");
  setHidden(elements.inputPanel, false);
  renderMultipleChoiceOptions();
  renderTableEventControls();
  setHidden(elements.answerProgressPanel, false);
  setHidden(elements.powerPanel, false);
  renderBotPowerDebugPanel();
  setHidden(elements.effectPanel, false);
  setHidden(elements.loadingPanel, true);
  setHidden(elements.cardsArea, true);
  setHidden(elements.verdictPanel, true);
  setHidden(elements.powerLog, true);
  setHidden(elements.roundRecap, true);
  resetReactionPanel();
  setHidden(elements.errorPanel, true);
  setHidden(elements.endPanel, true);
  scheduleIncomingQuestionCardAnimation(blackCard);
  restartAnimation(judgePanel, "entering");
  renderPowerUps();
  renderHintControls();
  renderScore();
  if (!state.renderingSyncedRoomResume) {
    try {
      void publishRoomScoreState("round-start-score");
    } catch (error) {
      console.warn("Round-start score sync failed after render:", error);
    }
  }
  if (state.isSpectator) {
    stopTimer();
    setHidden(elements.inputPanel, true);
    setHidden(elements.answerProgressPanel, true);
    setHidden(elements.powerPanel, true);
    setHidden(elements.roomSubmitStatus, true);
    renderSpectatorAnswerCards();
    addSystemChat("Spectator mode: you can chat and watch the table, but you will join play next match.", { private: true, audience: "spectator" });
  }
}

function updateModeUi() {
  document.body?.toggleAttribute("data-game-active", isGameScreenActive());
  const isDuel = isDuelMode();
  const multipleChoice = isMultipleChoiceRound();
  elements.gameStage.classList.toggle("wild-fire-active", isMatchModifierEnabled("wildFire"));
  elements.gameStage.classList.toggle("spectator-mode", Boolean(state.isSpectator && isRoomMode()));
  applyTableEventStageClasses();
  updateWildFireBurningState();
  renderSpectatorCountIndicator();
  renderTopModeLabel();
  renderAnswerCardsForOwners(getRoundCardOwners());
  renderBotPowerDebugPanel();
  elements.answerInput.placeholder = isRoomMode()
    ? `${getOwnerLabel(state.currentOwner)} answer`
    : isDuel
    ? state.localEntryStep === 1
      ? `${getOwnerLabel("player")} answer`
      : `${getOwnerLabel("opponent")} answer`
    : "Your trivia answer";
  elements.playerTwoInput.required = false;
  elements.playerTwoInput.disabled = true;
  setHidden(elements.playerTwoInput, true);
  setHidden(elements.answerInput.closest(".input-fields"), multipleChoice);
  setHidden(elements.multipleChoiceOptions, !multipleChoice);
  setHidden(elements.submitButton, multipleChoice);
  elements.submitButton.textContent = isDuel && !isRoomMode() && state.localEntryStep === 1 ? "Lock In" : "Submit";
  document.querySelector("#inputTitle").textContent = isRoomMode()
    ? `${getOwnerLabel(state.currentOwner)}, ${multipleChoice ? "choose an answer." : "enter your trivia answer."}`
    : isDuel
    ? state.localEntryStep === 1
      ? `${getOwnerLabel("player")}, ${multipleChoice ? "choose an answer." : "enter your trivia answer. It disappears after locking."}`
      : `${getOwnerLabel("opponent")}, your turn. ${getOwnerLabel("player")}'s answer is hidden.`
    : multipleChoice ? "Choose the correct answer." : "Answer the trivia question.";
  renderMultipleChoiceOptions();
  renderHintControls();
  setHidden(elements.exitGameButton, isRoomMode() && !isCurrentHost());
  setHidden(elements.leaveGameButton, false);
  renderRoomChat();
  renderPowerUps();
  renderSpectatorAnswerCards();
}

function renderMultipleChoiceOptions() {
  if (!elements.multipleChoiceOptions) {
    return;
  }
  elements.multipleChoiceOptions.replaceChildren();
  if (!isMultipleChoiceRound()) {
    return;
  }
  const owner = getCurrentPowerOwner();
  const lockedAnswer = getLockedRoundAnswer(owner);
  const submitted = (isRoomMode() && state.roomSubmissions[state.currentOwner])
    || (state.mode === "bots" && state.roomSubmissions.player);
  const disabled = Boolean(state.isSpectator || submitted || state.matchEnded || elements.inputPanel.classList.contains("hidden"));
  getCurrentMultipleChoiceOptions().forEach((answer, index) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "multiple-choice-option";
    button.dataset.answerChoice = answer;
    button.disabled = disabled;
    button.textContent = `${String.fromCharCode(65 + index)}. ${answer}`;
    button.setAttribute("aria-label", `Choose ${answer} for ${getOwnerLabel(owner)}`);
    button.setAttribute("aria-pressed", String(Boolean(lockedAnswer) && normalizeMultipleChoiceOption(lockedAnswer) === normalizeMultipleChoiceOption(answer)));
    button.classList.toggle("selected", Boolean(lockedAnswer) && normalizeMultipleChoiceOption(lockedAnswer) === normalizeMultipleChoiceOption(answer));
    elements.multipleChoiceOptions.appendChild(button);
  });
}

function focusAnswerControl() {
  if (isMultipleChoiceRound()) {
    elements.multipleChoiceOptions?.querySelector(".multiple-choice-option:not(:disabled)")?.focus();
    return;
  }
  elements.answerInput.focus();
}

function syncCurrentRoundSetupMetadata(setup) {
  if (!setup || typeof setup !== "object") {
    return;
  }
  const difficulty = normalizeDifficulty(setup.difficulty || state.questionDifficulty);
  const theme = String(setup.triviaTheme || setup.theme || state.triviaTheme || "Mixed Trivia").trim();
  state.questionDifficulty = difficulty;
  state.triviaTheme = theme;
  if (elements.questionThemeBadge) {
    elements.questionThemeBadge.textContent = theme || "Mixed Trivia";
  }
  if (elements.questionDifficultyBadge) {
    elements.questionDifficultyBadge.textContent = getDifficultyLabel(difficulty);
    elements.questionDifficultyBadge.className = `difficulty-badge difficulty-${difficulty}`;
  }
}

function applyRoundSetup(setup, options = {}) {
  const renderKey = getRoundSetupRenderKey(setup, options);
  const shouldRender = options.forceRender === true || state.roundSetupRenderKey !== renderKey;
  stopLoadingMessages();
  setHidden(elements.errorPanel, true);
  state.roomRoundResult = null;
  state.questionId = setup.id || "";
  state.blackCard = setup.blackCard;
  removeReservedQuestionSetup(setup);
  removeCachedRoundSetup(setup);
  state.questionType = setup.type === "text" ? "text" : "image";
  state.questionStyle = setup.questionStyle === MULTIPLE_CHOICE_STYLE ? MULTIPLE_CHOICE_STYLE : "standard";
  state.questionLanguage = normalizeQuestionLanguage(setup.language);
  state.gradingStrictness = normalizeGradingStrictness(setup.gradingStrictness);
  state.questionDifficulty = normalizeDifficulty(setup.difficulty);
  state.triviaTheme = setup.triviaTheme || "Mixed Trivia";
  state.questionImage = setup.image && setup.image.url ? setup.image : null;
  state.canonicalAnswer = setup.canonicalAnswer || "";
  state.acceptedAnswers = setup.acceptedAnswers || [];
  state.judge = setup.judge;
  state.botCards = setup.botCards || [];
  state.rejectedAnswers = setup.rejectedAnswers || [];
  state.multipleChoiceOptions = Array.isArray(setup.multipleChoiceOptions) ? setup.multipleChoiceOptions.slice(0, 4) : [];
  state.recentJudgeNames = [...state.recentJudgeNames, state.judge.name].slice(-5);
  state.recentBlackCards = [...state.recentBlackCards, state.blackCard].slice(-20);
  state.recentTriviaThemes = [...state.recentTriviaThemes, state.triviaTheme].filter(Boolean).slice(-triviaThemes.length);
  recordQuestionUsage(setup);
  preloadRoundExperience(setup);
  if (!shouldRender) {
    syncCurrentRoundSetupMetadata(setup);
    if (!options.skipPublish) {
      try {
        publishRoomRoundSetup(setup);
      } catch (error) {
        console.warn("Round setup publish failed during metadata sync:", error);
      }
    }
    scheduleNextSetupPrefetch();
    return;
  }
  state.roundSetupRenderKey = renderKey;
  const wasRenderingSyncedRoomResume = state.renderingSyncedRoomResume;
  state.renderingSyncedRoomResume = Boolean(options.resumeSyncedRoom);
  try {
    renderRound();
  } finally {
    state.renderingSyncedRoomResume = wasRenderingSyncedRoomResume;
  }
  if (!options.skipPublish) {
    try {
      publishRoomRoundSetup(setup);
    } catch (error) {
      console.warn("Round setup publish failed after render:", error);
    }
  }
  scheduleNextSetupPrefetch();
  playSound("reveal");
}

