function populateDevToolThemeSelects() {
  const themeOptions = triviaThemes.map((theme) => `<option value="${theme}">${theme}</option>`).join("");
  elements.devQuestionThemeFilter.innerHTML = `<option value="all">All themes</option>${themeOptions}`;
  elements.devCreateTheme.innerHTML = themeOptions;
}

function bindDevToolEvents() {
  elements.devToolBackButton.addEventListener("click", closeDevToolScreen);
  elements.adminLogoutButton.addEventListener("click", logoutAdmin);
  elements.devToolTabs.addEventListener("click", (event) => {
    const button = event.target.closest("[data-dev-tab]");
    if (button) {
      requestDevToolTab(button.dataset.devTab);
    }
  });
  elements.devQuestionSearchInput.addEventListener("input", filterQuestionDebugBank);
  elements.devQuestionThemeFilter.addEventListener("change", filterQuestionDebugBank);
  elements.devQuestionTypeFilter.addEventListener("change", filterQuestionDebugBank);
  elements.devQuestionLanguageFilter.addEventListener("change", filterQuestionDebugBank);
  elements.devQuestionPrevButton.addEventListener("click", () => selectQuestionDebugIndex(state.questionDebugIndex - 1));
  elements.devQuestionNextButton.addEventListener("click", () => selectQuestionDebugIndex(state.questionDebugIndex + 1));
  elements.devQuestionResults.addEventListener("click", (event) => {
    const button = event.target.closest("[data-question-debug-index]");
    if (button) {
      selectQuestionDebugIndex(Number(button.dataset.questionDebugIndex));
    }
  });
  elements.devQuestionEditButton.addEventListener("click", startEditingDebugQuestion);
  elements.devQuestionDeleteButton.addEventListener("click", deleteSelectedDebugQuestion);
  elements.devQuestionFindDuplicatesButton.addEventListener("click", renderDuplicateQuestionReport);
  elements.devQuestionCheckImagesButton.addEventListener("click", checkQuestionImageUrls);
  elements.devQuestionLeastSeenButton.addEventListener("click", () => renderQuestionUsageReport("least"));
  elements.devQuestionMostRepeatedButton.addEventListener("click", () => renderQuestionUsageReport("most"));
  elements.devQuestionPassNewButton.addEventListener("click", passNewQuestionBatch);
  elements.devQuestionToolsResults.addEventListener("click", (event) => {
    const button = event.target.closest("[data-question-tool-focus]");
    if (button) {
      focusQuestionDebugById(button.dataset.questionToolFocus);
    }
  });
  elements.devQuestionGradeSubmitButton.addEventListener("click", submitDevQuestionGradingTest);
  elements.devQuestionGradeClearButton.addEventListener("click", () => {
    elements.devQuestionGradeAnswer.value = "";
    resetDevQuestionGradingTester();
    resetDevQuestionAiShield();
    elements.devQuestionGradeAnswer.focus();
    playSound("click");
  });
  elements.devQuestionGradeAnswer.addEventListener("keydown", (event) => {
    if ((event.metaKey || event.ctrlKey) && event.key === "Enter") {
      event.preventDefault();
      submitDevQuestionGradingTest();
    }
  });
  elements.devQuestionGradeAnswer.addEventListener("input", () => {
    resetDevQuestionAiShield("Answer changed. Check the shield again when ready.");
  });
  elements.devQuestionGradeMode.addEventListener("change", () => {
    resetDevQuestionGradingTester();
    renderDevQuestionGradingTester(getSelectedDebugQuestion());
    resetDevQuestionAiShield();
  });
  elements.devQuestionGradeOptions.addEventListener("click", (event) => {
    const button = event.target.closest("[data-dev-grade-option]");
    if (!button) {
      return;
    }
    elements.devQuestionGradeAnswer.value = button.dataset.devGradeOption || "";
    resetDevQuestionAiShield();
    submitDevQuestionGradingTest();
  });
  elements.devQuestionShieldSubmitButton.addEventListener("click", submitDevQuestionAiShieldTest);
  elements.devQuestionShieldBotToggle.addEventListener("change", () => {
    resetDevQuestionAiShield("Shield input changed. Run the check again.");
  });
  elements.devRoomRefreshButton.addEventListener("click", loadDevRooms);
  elements.devRoomList.addEventListener("click", handleDevRoomClick);
  elements.devRoomDiagnosticsRefreshButton.addEventListener("click", () => {
    renderRoomDiagnosticsPanel();
    playSound("click");
  });
  elements.devRoomDiagnosticsCatchupButton.addEventListener("click", () => {
    requestRoomRealtimeCatchup("dev-tool", { force: true, snapshot: true });
    renderRoomDiagnosticsPanel();
    playSound("click");
  });
  elements.devRoomDiagnosticsClearButton.addEventListener("click", clearRoomDiagnosticsTimeline);
  elements.devSubmissionRefreshButton.addEventListener("click", loadDevQuestionSubmissions);
  elements.devSubmissionList.addEventListener("click", handleDevSubmissionListClick);
  elements.devSubmissionReviewPanel.addEventListener("click", handleDevSubmissionClick);
  elements.devSubmissionReviewPanel.addEventListener("input", updateDevSubmissionReviewPreview);
  elements.devSubmissionReviewPanel.addEventListener("change", updateDevSubmissionReviewPreview);
  elements.devOverlayGrid.addEventListener("click", (event) => {
    const button = event.target.closest("[data-overlay-debug]");
    if (button) {
      triggerOverlayDebug(button.dataset.overlayDebug);
      elements.devOverlayStatus.textContent = `${button.dataset.overlayDebug} overlay triggered.`;
    }
  });
  elements.devOverlayClearButton.addEventListener("click", () => {
    clearStatFlashes();
    elements.devOverlayStatus.textContent = "Overlay queue cleared.";
    playSound("click");
  });
  elements.devVictoryAnimationSelect.addEventListener("change", renderDevVictoryPreview);
  elements.devVictoryPlayButton.addEventListener("click", playDevVictoryAnimation);
  elements.devVictoryRefreshButton.addEventListener("click", () => {
    renderDevVictoryPreview();
    elements.devVictoryStatus.textContent = "Preview refreshed from your current profile.";
    playSound("click");
  });
  elements.devPowerOwnerSelect.addEventListener("change", () => renderPowerDebug("dev"));
  elements.devPowerSearchInput.addEventListener("input", () => renderPowerDebug("dev"));
  elements.devPowerSelect.addEventListener("change", () => renderPowerDebug("dev"));
  elements.devPowerChaosToggle.addEventListener("change", () => renderPowerDebug("dev"));
  elements.devPowerAddButton.addEventListener("click", () => addDebugPowerToHand("dev"));
  elements.devPowerFillButton.addEventListener("click", () => fillDebugPowerHand("dev"));
  elements.devPowerClearButton.addEventListener("click", () => clearDebugPowerHand("dev"));
  elements.devAchievementSearchInput.addEventListener("input", renderAchievementDebug);
  elements.devAchievementRarityFilter.addEventListener("change", renderAchievementDebug);
  elements.devAchievementTypeFilter.addEventListener("change", renderAchievementDebug);
  elements.devAchievementResetMilestonesButton.addEventListener("click", resetAchievementMilestonesFromDebug);
  elements.devAchievementGrid.addEventListener("click", handleAchievementDebugClick);
  elements.devAchievementGrid.addEventListener("change", handleAchievementDebugChange);
  elements.devProfileGrid.addEventListener("click", handleProfileDebugClick);
  elements.devProfileUnlockAllButton.addEventListener("click", () => setAllProfileDebugStates("enabled"));
  elements.devProfileLockAllButton.addEventListener("click", () => setAllProfileDebugStates("disabled"));
  elements.devProfileResetButton.addEventListener("click", () => setAllProfileDebugStates("reset"));
  elements.devCreateType.addEventListener("change", updateDevCreateImageFields);
  elements.devCreateQuestionStyle.addEventListener("change", updateDevCreateImageFields);
  elements.devCreateLanguage.addEventListener("change", () => {
    syncDevCreateIdPrefix();
    updateDevCreatePreview();
  });
  elements.devCreateStrictness.addEventListener("change", updateDevCreatePreview);
  elements.devCreateTheme.addEventListener("change", () => {
    syncDevCreateIdPrefix();
    updateDevCreatePreview();
  });
  elements.devCreateId.addEventListener("input", () => {
    elements.devCreateId.setCustomValidity("");
    normalizeDevCreateIdInput();
  });
  [elements.devCreateCanonical, elements.devCreateBots].forEach((input) => {
    input?.addEventListener("input", () => {
      input.setCustomValidity("");
    });
  });
  elements.devQuestionCreateForm.addEventListener("input", updateDevCreatePreview);
  elements.devQuestionCreateForm.addEventListener("change", updateDevCreatePreview);
  elements.devCreateSaveAsNewButton.addEventListener("click", saveEditedQuestionAsNew);
  elements.devCreateExitButton.addEventListener("click", exitDevQuestionEdit);
  elements.devCreateClearButton.addEventListener("click", clearDevQuestionCreateFormWithConfirm);
  elements.devQuestionCreateForm.addEventListener("submit", submitDevQuestionCreateForm);
}

function buildUserQuestionScreen() {
  if (elements.userQuestionScreen) {
    return;
  }

  const screen = document.createElement("section");
  screen.className = "user-question-screen hidden";
  screen.id = "userQuestionScreen";
  screen.setAttribute("aria-labelledby", "userQuestionTitle");
  screen.innerHTML = `
    <div class="room-header">
      <div>
        <p class="eyebrow">Community cards</p>
        <h1 id="userQuestionTitle">CREATE QUESTIONS</h1>
      </div>
      <div class="lobby-actions">
        <button type="button" class="icon-button" id="userQuestionBackButton">Back</button>
      </div>
    </div>
    <div class="dev-create-layout user-question-layout">
      <form class="dev-create-form" id="userQuestionForm">
        <div class="dev-create-grid dev-create-meta-grid">
          <label><span>Theme</span><select id="userQuestionTheme"></select></label>
          <label><span>Difficulty</span><select id="userQuestionDifficulty"><option value="easy">Easy</option><option value="medium">Medium</option><option value="hard">Hard</option></select></label>
          <label><span>Question type</span><select id="userQuestionType"><option value="text">Text</option><option value="image">Image</option></select></label>
          <label><span>Question style</span><select id="userQuestionStyle"><option value="standard">Standard</option><option value="multiple-choice">Multiple choice</option></select></label>
          <label><span>Strictness</span><select id="userQuestionStrictness"><option value="normal">Normal</option><option value="forgiving">Forgiving</option><option value="strict">Strict</option><option value="exact">Exact</option></select></label>
          <label><span>ID</span><input id="userQuestionId" required placeholder="popculture-short-unique-id"></label>
        </div>
        <label class="dev-create-question-field"><span>Question</span><textarea id="userQuestionText" required rows="5" placeholder="Question text"></textarea></label>
        <div class="dev-create-answer-grid">
          <label class="dev-create-canonical dev-create-answer-expandable"><span>Main answer</span><textarea id="userQuestionCanonical" required rows="3" placeholder="Main answer"></textarea></label>
          <label class="dev-create-answer-field-collapsible" id="userQuestionAcceptedWrap"><span>Accepted answers</span><textarea id="userQuestionAccepted" rows="3" placeholder="first, second, third" autocomplete="off" autocapitalize="none" autocorrect="off" spellcheck="false"></textarea></label>
        </div>
        <div class="dev-create-answer-grid">
          <label class="dev-create-bots dev-create-answer-expandable" id="userQuestionBotsWrap"><span>Incorrect answers</span><textarea id="userQuestionBots" required rows="3" placeholder="wrong one, wrong two, wrong three"></textarea></label>
          <label class="dev-create-answer-field-collapsible" id="userQuestionRejectedWrap"><span>Rejected answers</span><textarea id="userQuestionRejected" rows="3" placeholder="bad answer, too vague"></textarea></label>
        </div>
        <fieldset class="dev-create-image-fields hidden" id="userQuestionImageFields">
          <legend>Image</legend>
          <label><span>Image URL</span><input id="userQuestionImageUrl" placeholder="https://..."></label>
          <div class="dev-create-grid">
            <label><span>Alt text</span><input id="userQuestionImageAlt" placeholder="Short image description"></label>
            <label><span>Credit</span><input id="userQuestionImageCredit" placeholder="Wikimedia Commons"></label>
          </div>
        </fieldset>
        <div class="dev-create-actions">
          <button type="submit" class="primary-button" id="userQuestionSubmitButton">Submit for 250 Coins</button>
          <button type="button" class="icon-button" id="userQuestionSaveDraftButton">Save Draft</button>
          <button type="button" class="icon-button danger-button" id="userQuestionClearButton">Clear</button>
          <div class="debug-status" id="userQuestionStatus">Submissions are reviewed by an admin before they enter the question bank.</div>
        </div>
      </form>
      <aside class="dev-create-preview-shell">
        <p class="eyebrow">Live preview</p>
        <section class="black-card dev-create-preview-card text-only" id="userQuestionPreview" aria-labelledby="userQuestionPreviewText">
          <div class="question-meta">
            <p>Draft card</p>
            <div class="question-badges" id="userQuestionPreviewMeta"></div>
          </div>
          <figure class="question-image">
            <img id="userQuestionPreviewImage" alt="">
            <div class="question-image-placeholder" id="userQuestionPreviewPlaceholder">Image preview</div>
            <figcaption id="userQuestionPreviewCredit"></figcaption>
          </figure>
          <h2 id="userQuestionPreviewText">Question preview</h2>
        </section>
        <section class="user-question-submissions">
          <div class="dev-panel-heading">
            <div>
              <p class="eyebrow">Your cards</p>
              <h2>Review Status</h2>
            </div>
          </div>
          <div id="userQuestionSubmissionList" class="user-question-submission-list"></div>
        </section>
      </aside>
    </div>
  `;
  elements.modeScreen.insertAdjacentElement("afterend", screen);
  elements.userQuestionScreen = screen;
  elements.userQuestionForm = screen.querySelector("#userQuestionForm");
  elements.userQuestionBackButton = screen.querySelector("#userQuestionBackButton");
  elements.userQuestionTheme = screen.querySelector("#userQuestionTheme");
  elements.userQuestionDifficulty = screen.querySelector("#userQuestionDifficulty");
  elements.userQuestionType = screen.querySelector("#userQuestionType");
  elements.userQuestionStyle = screen.querySelector("#userQuestionStyle");
  elements.userQuestionStrictness = screen.querySelector("#userQuestionStrictness");
  elements.userQuestionId = screen.querySelector("#userQuestionId");
  elements.userQuestionText = screen.querySelector("#userQuestionText");
  elements.userQuestionCanonical = screen.querySelector("#userQuestionCanonical");
  elements.userQuestionAcceptedWrap = screen.querySelector("#userQuestionAcceptedWrap");
  elements.userQuestionAccepted = screen.querySelector("#userQuestionAccepted");
  elements.userQuestionBotsWrap = screen.querySelector("#userQuestionBotsWrap");
  elements.userQuestionBots = screen.querySelector("#userQuestionBots");
  elements.userQuestionRejectedWrap = screen.querySelector("#userQuestionRejectedWrap");
  elements.userQuestionRejected = screen.querySelector("#userQuestionRejected");
  elements.userQuestionImageFields = screen.querySelector("#userQuestionImageFields");
  elements.userQuestionImageUrl = screen.querySelector("#userQuestionImageUrl");
  elements.userQuestionImageAlt = screen.querySelector("#userQuestionImageAlt");
  elements.userQuestionImageCredit = screen.querySelector("#userQuestionImageCredit");
  elements.userQuestionSubmitButton = screen.querySelector("#userQuestionSubmitButton");
  elements.userQuestionClearButton = screen.querySelector("#userQuestionClearButton");
  elements.userQuestionStatus = screen.querySelector("#userQuestionStatus");
  elements.userQuestionSubmissionList = screen.querySelector("#userQuestionSubmissionList");
  elements.userQuestionPreview = screen.querySelector("#userQuestionPreview");
  elements.userQuestionPreviewMeta = screen.querySelector("#userQuestionPreviewMeta");
  elements.userQuestionPreviewImage = screen.querySelector("#userQuestionPreviewImage");
  elements.userQuestionPreviewPlaceholder = screen.querySelector("#userQuestionPreviewPlaceholder");
  elements.userQuestionPreviewCredit = screen.querySelector("#userQuestionPreviewCredit");
  elements.userQuestionPreviewText = screen.querySelector("#userQuestionPreviewText");
  elements.userQuestionSaveDraftButton = screen.querySelector("#userQuestionSaveDraftButton");
  elements.userQuestionTheme.innerHTML = triviaThemes.map((theme) => `<option value="${theme}">${theme}</option>`).join("");
  elements.userQuestionTheme.addEventListener("change", () => {
    syncUserQuestionIdPrefix();
    updateUserQuestionPreview();
  });
  elements.userQuestionType.addEventListener("change", updateUserQuestionImageFields);
  elements.userQuestionStyle.addEventListener("change", updateUserQuestionImageFields);
  elements.userQuestionStrictness.addEventListener("change", updateUserQuestionPreview);
  elements.userQuestionId.addEventListener("input", () => {
    elements.userQuestionId.setCustomValidity("");
    normalizeUserQuestionIdInput();
  });
  [elements.userQuestionCanonical, elements.userQuestionBots].forEach((input) => {
    input?.addEventListener("input", () => {
      input.setCustomValidity("");
    });
  });
  elements.userQuestionForm.addEventListener("input", updateUserQuestionPreview);
  elements.userQuestionForm.addEventListener("change", updateUserQuestionPreview);
  elements.userQuestionForm.addEventListener("input", scheduleUserQuestionDraftSave);
  elements.userQuestionForm.addEventListener("change", scheduleUserQuestionDraftSave);
  elements.userQuestionForm.addEventListener("submit", submitUserQuestion);
  elements.userQuestionBackButton.addEventListener("click", closeUserQuestionScreen);
  elements.userQuestionSaveDraftButton.addEventListener("click", () => saveUserQuestionDraft());
  elements.userQuestionClearButton.addEventListener("click", clearUserQuestionForm);
  updateUserQuestionImageFields();
  syncUserQuestionIdPrefix();
  restoreUserQuestionDraft();
  updateUserQuestionPreview();
}

function normalizeUserQuestionIdInput() {
  const input = elements.userQuestionId;
  input.value = formatDevQuestionId(input.value, { keepTrailingDash: true });
}

function syncUserQuestionIdPrefix() {
  const prefix = getThemeIdPrefix(elements.userQuestionTheme.value);
  const current = formatDevQuestionId(elements.userQuestionId.value);
  if (!current || getKnownThemeIdPrefixes().has(current.split("-")[0])) {
    elements.userQuestionId.value = `${prefix}-`;
  }
}

function getUserQuestionDraftStorageUserKey() {
  const rawUserId = state.supabaseUser?.id || state.clientId || "guest";
  return String(rawUserId).replace(/[^a-zA-Z0-9_-]/g, "").slice(0, 140) || "guest";
}

function getUserQuestionDraftStorageKey() {
  return `${userQuestionDraftStorageKey}:${getUserQuestionDraftStorageUserKey()}`;
}

function getUserQuestionDraftValues() {
  return {
    version: 1,
    savedAt: Date.now(),
    theme: elements.userQuestionTheme?.value || "",
    difficulty: elements.userQuestionDifficulty?.value || "medium",
    type: elements.userQuestionType?.value || "text",
    questionStyle: elements.userQuestionStyle?.value || "standard",
    strictness: elements.userQuestionStrictness?.value || "normal",
    id: elements.userQuestionId?.value || "",
    question: elements.userQuestionText?.value || "",
    canonicalAnswer: elements.userQuestionCanonical?.value || "",
    acceptedAnswers: elements.userQuestionAccepted?.value || "",
    incorrectAnswers: elements.userQuestionBots?.value || "",
    rejectedAnswers: elements.userQuestionRejected?.value || "",
    imageUrl: elements.userQuestionImageUrl?.value || "",
    imageAlt: elements.userQuestionImageAlt?.value || "",
    imageCredit: elements.userQuestionImageCredit?.value || ""
  };
}

function hasUserQuestionDraftContent(draft) {
  return [
    draft?.question,
    draft?.canonicalAnswer,
    draft?.acceptedAnswers,
    draft?.incorrectAnswers,
    draft?.rejectedAnswers,
    draft?.imageUrl,
    draft?.imageAlt,
    draft?.imageCredit,
    String(draft?.id || "").replace(/-+$/g, "")
  ].some((value) => String(value || "").trim());
}

function saveUserQuestionDraft(options = {}) {
  if (!elements.userQuestionForm) {
    return false;
  }
  if (state.userQuestionDraftSaveTimerId) {
    window.clearTimeout(state.userQuestionDraftSaveTimerId);
    state.userQuestionDraftSaveTimerId = null;
  }
  const draft = getUserQuestionDraftValues();
  if (!hasUserQuestionDraftContent(draft)) {
    clearUserQuestionDraft({ announce: false });
    if (options.announce !== false) {
      elements.userQuestionStatus.textContent = "There is nothing to save yet.";
    }
    return false;
  }
  const saved = writeJsonStorage(getUserQuestionDraftStorageKey(), draft);
  state.userQuestionDraftStorageUserKey = getUserQuestionDraftStorageUserKey();
  if (options.announce !== false) {
    elements.userQuestionStatus.textContent = saved
      ? "Draft saved locally on this device."
      : "Could not save the draft locally.";
  }
  return saved;
}

function scheduleUserQuestionDraftSave() {
  if (!elements.userQuestionForm) {
    return;
  }
  if (state.userQuestionDraftSaveTimerId) {
    window.clearTimeout(state.userQuestionDraftSaveTimerId);
  }
  state.userQuestionDraftSaveTimerId = window.setTimeout(() => {
    state.userQuestionDraftSaveTimerId = null;
    saveUserQuestionDraft({ announce: false });
  }, userQuestionDraftSaveDelayMs);
}

function clearUserQuestionDraft(options = {}) {
  if (state.userQuestionDraftSaveTimerId) {
    window.clearTimeout(state.userQuestionDraftSaveTimerId);
    state.userQuestionDraftSaveTimerId = null;
  }
  try {
    localStorage.removeItem(getUserQuestionDraftStorageKey());
  } catch {}
  if (options.announce !== false && elements.userQuestionStatus) {
    elements.userQuestionStatus.textContent = "Local draft cleared.";
  }
}

function restoreUserQuestionDraft() {
  if (!elements.userQuestionForm) {
    return false;
  }
  const storageUserKey = getUserQuestionDraftStorageUserKey();
  const draft = readJsonStorage(getUserQuestionDraftStorageKey(), null);
  state.userQuestionDraftStorageUserKey = storageUserKey;
  if (!draft || draft.version !== 1 || !hasUserQuestionDraftContent(draft)) {
    return false;
  }

  const selectValues = [
    [elements.userQuestionTheme, draft.theme],
    [elements.userQuestionDifficulty, draft.difficulty],
    [elements.userQuestionType, draft.type],
    [elements.userQuestionStyle, draft.questionStyle],
    [elements.userQuestionStrictness, draft.strictness]
  ];
  selectValues.forEach(([select, value]) => {
    if (select && [...select.options].some((option) => option.value === value)) {
      select.value = value;
    }
  });
  elements.userQuestionId.value = String(draft.id || "").slice(0, 160);
  elements.userQuestionText.value = String(draft.question || "");
  elements.userQuestionCanonical.value = String(draft.canonicalAnswer || "");
  elements.userQuestionAccepted.value = String(draft.acceptedAnswers || "");
  elements.userQuestionBots.value = String(draft.incorrectAnswers || "");
  elements.userQuestionRejected.value = String(draft.rejectedAnswers || "");
  elements.userQuestionImageUrl.value = String(draft.imageUrl || "");
  elements.userQuestionImageAlt.value = String(draft.imageAlt || "");
  elements.userQuestionImageCredit.value = String(draft.imageCredit || "");
  updateUserQuestionImageFields();
  elements.userQuestionStatus.textContent = "Draft restored from this device.";
  return true;
}

function syncQuestionCreateAnswerFields({
  form,
  acceptedWrap,
  rejectedWrap,
  acceptedInput,
  rejectedInput,
  canonicalInput,
  botsWrap,
  strictnessInput,
  isMultipleChoice,
  standardCanonicalLabel,
  standardBotsLabel
}) {
  form?.classList.toggle("question-form-multiple-choice", isMultipleChoice);
  [acceptedWrap, rejectedWrap].forEach((wrap) => {
    if (!wrap) return;
    wrap.classList.add("dev-create-answer-field-collapsible");
    wrap.classList.toggle("answer-field-collapsed", isMultipleChoice);
    wrap.setAttribute("aria-hidden", String(isMultipleChoice));
  });
  [acceptedInput, rejectedInput].forEach((input) => {
    if (!input) return;
    input.disabled = isMultipleChoice;
    input.required = false;
  });
  const canonicalLabel = canonicalInput?.closest("label")?.querySelector("span");
  if (canonicalLabel) {
    canonicalLabel.textContent = isMultipleChoice ? "Correct answer" : standardCanonicalLabel;
  }
  const botsLabel = botsWrap?.querySelector("span");
  if (botsLabel) {
    botsLabel.textContent = isMultipleChoice ? "Incorrect answers" : standardBotsLabel;
  }
  if (strictnessInput) {
    const strictnessLabel = strictnessInput.closest("label");
    strictnessInput.disabled = isMultipleChoice;
    strictnessInput.title = isMultipleChoice
      ? "Multiple-choice questions use exact option matching."
      : getGradingStrictnessDescription(strictnessInput.value);
    strictnessLabel?.classList.toggle("field-muted", isMultipleChoice);
  }
}

function updateUserQuestionImageFields() {
  const isImage = elements.userQuestionType.value === "image";
  const isMultipleChoice = elements.userQuestionStyle?.value === MULTIPLE_CHOICE_STYLE;
  setHidden(elements.userQuestionImageFields, !isImage);
  elements.userQuestionImageUrl.required = isImage;
  syncQuestionCreateAnswerFields({
    form: elements.userQuestionForm,
    acceptedWrap: elements.userQuestionAcceptedWrap,
    rejectedWrap: elements.userQuestionRejectedWrap,
    acceptedInput: elements.userQuestionAccepted,
    rejectedInput: elements.userQuestionRejected,
    canonicalInput: elements.userQuestionCanonical,
    botsWrap: elements.userQuestionBotsWrap,
    strictnessInput: elements.userQuestionStrictness,
    isMultipleChoice,
    standardCanonicalLabel: "Main answer",
    standardBotsLabel: "Wrong bot answers"
  });
  elements.userQuestionBots.placeholder = isMultipleChoice ? "wrong one, wrong two, wrong three" : "wrong one, wrong two";
  updateUserQuestionPreview();
}

function updateUserQuestionPreview() {
  if (!elements.userQuestionPreview) return;
  const type = elements.userQuestionType.value === "image" ? "image" : "text";
  const style = elements.userQuestionStyle?.value === MULTIPLE_CHOICE_STYLE ? MULTIPLE_CHOICE_STYLE : "standard";
  const theme = elements.userQuestionTheme.value || "Theme";
  const difficulty = normalizeDifficulty(elements.userQuestionDifficulty.value);
  const question = elements.userQuestionText.value.trim() || "Question preview";
  const imageUrl = elements.userQuestionImageUrl.value.trim();
  const imageAlt = elements.userQuestionImageAlt.value.trim() || "Question image preview";
  const imageCredit = elements.userQuestionImageCredit.value.trim();
  elements.userQuestionPreview.classList.toggle("text-only", type !== "image");
  elements.userQuestionPreviewMeta.replaceChildren();
  [theme, type === "image" ? "Image" : "Text", style === MULTIPLE_CHOICE_STYLE ? "Multiple choice" : getGradingStrictnessLabel(elements.userQuestionStrictness?.value), difficulty].filter(Boolean).forEach((text) => {
    const badge = document.createElement("span");
    badge.textContent = text;
    elements.userQuestionPreviewMeta.appendChild(badge);
  });
  elements.userQuestionPreviewText.textContent = question;
  elements.userQuestionPreviewCredit.textContent = imageCredit;
  setHidden(elements.userQuestionPreviewCredit, !imageCredit);
  elements.userQuestionPreviewImage.onload = () => {
    setHidden(elements.userQuestionPreviewImage, false);
    setHidden(elements.userQuestionPreviewPlaceholder, true);
  };
  elements.userQuestionPreviewImage.onerror = () => {
    elements.userQuestionPreviewPlaceholder.textContent = "Image failed to load.";
    setHidden(elements.userQuestionPreviewImage, true);
    setHidden(elements.userQuestionPreviewPlaceholder, false);
  };
  if (type === "image" && imageUrl) {
    elements.userQuestionPreviewImage.alt = imageAlt;
    if (elements.userQuestionPreviewImage.dataset.previewUrl !== imageUrl) {
      elements.userQuestionPreviewImage.dataset.previewUrl = imageUrl;
      elements.userQuestionPreviewImage.removeAttribute("src");
      elements.userQuestionPreviewPlaceholder.textContent = "Loading image...";
      setHidden(elements.userQuestionPreviewImage, true);
      setHidden(elements.userQuestionPreviewPlaceholder, false);
      elements.userQuestionPreviewImage.src = imageUrl;
    }
  } else {
    elements.userQuestionPreviewImage.removeAttribute("src");
    delete elements.userQuestionPreviewImage.dataset.previewUrl;
    elements.userQuestionPreviewImage.alt = "";
    elements.userQuestionPreviewPlaceholder.textContent = type === "image" ? "Image URL preview" : "Text-only question";
    setHidden(elements.userQuestionPreviewImage, true);
    setHidden(elements.userQuestionPreviewPlaceholder, type === "image");
  }
}

function getUserQuestionPayload() {
  const payload = {
    id: formatDevQuestionId(elements.userQuestionId.value),
    type: elements.userQuestionType.value,
    questionStyle: elements.userQuestionStyle?.value === MULTIPLE_CHOICE_STYLE ? MULTIPLE_CHOICE_STYLE : "standard",
    gradingStrictness: elements.userQuestionStyle?.value === MULTIPLE_CHOICE_STYLE
      ? "exact"
      : normalizeGradingStrictness(elements.userQuestionStrictness?.value),
    theme: elements.userQuestionTheme.value,
    difficulty: elements.userQuestionDifficulty.value,
    question: elements.userQuestionText.value.trim(),
    canonicalAnswer: elements.userQuestionCanonical.value.trim(),
    acceptedAnswers: parseCommaSeparatedAnswers(elements.userQuestionAccepted.value),
    botCards: parseCommaSeparatedAnswers(elements.userQuestionBots.value),
    rejectedAnswers: parseCommaSeparatedAnswers(elements.userQuestionRejected.value)
  };
  if (payload.questionStyle === MULTIPLE_CHOICE_STYLE) {
    const incorrect = parseCommaSeparatedAnswers(elements.userQuestionBots.value);
    payload.acceptedAnswers = [];
    payload.botCards = [];
    payload.rejectedAnswers = [];
    payload.multipleChoiceOptions = getMultipleChoiceDraftOptions(payload.canonicalAnswer, incorrect);
  }
  if (payload.type === "image") {
    payload.image = {
      url: elements.userQuestionImageUrl.value.trim(),
      alt: elements.userQuestionImageAlt.value.trim(),
      credit: elements.userQuestionImageCredit.value.trim()
    };
  }
  return payload;
}

function clearUserQuestionForm() {
  clearUserQuestionDraft({ announce: false });
  elements.userQuestionForm.reset();
  updateUserQuestionImageFields();
  syncUserQuestionIdPrefix();
  elements.userQuestionStatus.textContent = "Question form cleared.";
  updateUserQuestionPreview();
  playSound("click");
}

async function submitUserQuestion(event) {
  event.preventDefault();
  if (!elements.userQuestionForm.reportValidity()) return;
  if (!validateQuestionEditorId(elements.userQuestionId, elements.userQuestionTheme.value, elements.userQuestionStatus)) {
    return;
  }
  if (elements.userQuestionStyle?.value === MULTIPLE_CHOICE_STYLE
    && !validateMultipleChoiceDraft(
      elements.userQuestionCanonical.value,
      parseCommaSeparatedAnswers(elements.userQuestionBots.value),
      elements.userQuestionBots,
      elements.userQuestionStatus
    )) {
    return;
  }
  if (loadCurrencyBalance() < userQuestionSubmissionCost) {
    elements.userQuestionStatus.textContent = `You need ${formatCoins(userQuestionSubmissionCost)} to submit a question.`;
    playSound("error");
    return;
  }
  const payload = getUserQuestionPayload();
  spendCurrency(userQuestionSubmissionCost, "question-submission");
  renderProfile();
  elements.userQuestionSubmitButton.disabled = true;
  elements.userQuestionStatus.textContent = "Submitting for admin review...";
  try {
    const result = await postUserQuestionSubmission(payload);
    clearUserQuestionDraft({ announce: false });
    elements.userQuestionStatus.textContent = "Submitted for review. An admin will approve or deny it.";
    elements.userQuestionForm.reset();
    updateUserQuestionImageFields();
    syncUserQuestionIdPrefix();
    updateUserQuestionPreview();
    await loadUserQuestionSubmissions();
    playSound("reveal");
  } catch (error) {
    saveUserQuestionDraft({ announce: false });
    addCurrency(userQuestionSubmissionCost);
    renderProfile();
    const message = /invalid authentication token/i.test(error.message || "")
      ? "Your sign-in session needs refreshing before submitting questions."
      : error.message || "Submission failed.";
    elements.userQuestionStatus.textContent = `${message} Your ${formatCoins(userQuestionSubmissionCost)} were refunded.`;
    playSound("error");
  } finally {
    elements.userQuestionSubmitButton.disabled = false;
  }
}

function isQuestionSubmissionAuthError(response, result = {}) {
  const message = String(result?.error || "").toLowerCase();
  return [401, 403].includes(Number(response?.status))
    && /auth|token|session|creator/.test(message);
}

async function postUserQuestionSubmission(payload) {
  const body = JSON.stringify({
    question: payload,
    creator: { id: state.supabaseUser?.id || state.clientId, name: state.profile.name || "Player" }
  });
  const send = async (options = {}) => {
    const response = await fetch("/api/question-submissions", {
      method: "POST",
      headers: { "Content-Type": "application/json", ...(await getQuestionSubmissionAuthHeaders(options)) },
      body
    });
    const result = await response.json().catch(() => ({}));
    return { response, result };
  };
  let { response, result } = await send();
  if (!response.ok && isQuestionSubmissionAuthError(response, result)) {
    ({ response, result } = await send({ forceRefresh: true }));
  }
  if (!response.ok) {
    throw new Error(result.error || `Submission failed with status ${response.status}.`);
  }
  return result;
}

function loadSubmissionSeenIds() {
  try {
    const parsed = JSON.parse(localStorage.getItem(questionSubmissionSeenStorageKey) || "[]");
    return Array.isArray(parsed) ? parsed.filter(Boolean) : [];
  } catch {
    return [];
  }
}

function saveSubmissionSeenIds(ids) {
  localStorage.setItem(questionSubmissionSeenStorageKey, JSON.stringify([...new Set(ids.filter(Boolean))]));
}

function loadRefundedSubmissionIds() {
  try {
    const parsed = JSON.parse(localStorage.getItem(questionSubmissionRefundedStorageKey) || "[]");
    return Array.isArray(parsed) ? parsed.filter(Boolean) : [];
  } catch {
    return [];
  }
}

function saveRefundedSubmissionIds(ids) {
  localStorage.setItem(questionSubmissionRefundedStorageKey, JSON.stringify([...new Set(ids.filter(Boolean))]));
}

async function loadUserQuestionSubmissions({ markSeen = false } = {}) {
  if (!isPlayerSignedIn()) {
    state.userQuestionSubmissions = [];
    renderUserQuestionSubmissions();
    updateQuestionSubmissionNotificationDot();
    syncUserQuestionSubmissionPolling();
    return;
  }
  try {
    const creatorId = state.supabaseUser?.id || state.clientId;
    const result = await fetchUserQuestionSubmissions(creatorId);
    state.userQuestionSubmissions = Array.isArray(result.submissions) ? result.submissions : [];
    processQuestionSubmissionRefunds();
    if (markSeen) {
      saveSubmissionSeenIds([...loadSubmissionSeenIds(), ...getResolvedUserSubmissionIds()]);
    }
    syncSpecialBadgesToProfile();
    renderUserQuestionSubmissions();
    updateQuestionSubmissionNotificationDot();
    syncUserQuestionSubmissionPolling();
  } catch (error) {
    if (elements.userQuestionStatus) {
      elements.userQuestionStatus.textContent = /invalid authentication token/i.test(error.message || "")
        ? "Sign in again to load your submitted questions."
        : error.message || "Could not load your submissions.";
    }
  }
}

async function fetchUserQuestionSubmissions(creatorId) {
  const url = `/api/question-submissions?creatorId=${encodeURIComponent(creatorId)}`;
  const send = async (options = {}) => {
    const response = await fetch(url, {
      cache: "no-store",
      headers: await getQuestionSubmissionAuthHeaders(options)
    });
    const result = await response.json().catch(() => ({}));
    return { response, result };
  };
  let { response, result } = await send();
  if (!response.ok && isQuestionSubmissionAuthError(response, result)) {
    ({ response, result } = await send({ forceRefresh: true }));
  }
  if (!response.ok) {
    throw new Error(result.error || "Could not load your submissions.");
  }
  return result;
}

function hasPendingUserQuestionSubmissions() {
  return state.userQuestionSubmissions.some((submission) => submission.status === "pending" || submission.status === "review");
}

function syncUserQuestionSubmissionPolling() {
  if (state.userQuestionSubmissionPollId) {
    window.clearInterval(state.userQuestionSubmissionPollId);
    state.userQuestionSubmissionPollId = null;
  }
  if (elements.menuCreateQuestionsButton && !state.realtimeLobbyReady && hasPendingUserQuestionSubmissions()) {
    state.userQuestionSubmissionPollId = window.setInterval(() => loadUserQuestionSubmissions(), 60000);
  }
}

function getResolvedUserSubmissionIds() {
  return state.userQuestionSubmissions
    .filter((submission) => submission.status === "approved" || submission.status === "denied")
    .map((submission) => submission.id);
}

function processQuestionSubmissionRefunds() {
  const refunded = loadRefundedSubmissionIds();
  let changed = false;
  state.userQuestionSubmissions.forEach((submission) => {
    if (submission.status === "denied" && !refunded.includes(submission.id)) {
      addCurrency(submission.cost || userQuestionSubmissionCost);
      refunded.push(submission.id);
      changed = true;
    }
  });
  if (changed) {
    saveRefundedSubmissionIds(refunded);
    renderProfile();
  }
}

function updateQuestionSubmissionNotificationDot() {
  if (!elements.menuCreateQuestionsButton) return;
  const seen = loadSubmissionSeenIds();
  const unseenCount = state.userQuestionSubmissions
    .filter((submission) => (submission.status === "approved" || submission.status === "denied") && !seen.includes(submission.id))
    .length;
  elements.menuCreateQuestionsButton.classList.toggle("has-notification", unseenCount > 0);
  elements.menuCreateQuestionsButton.dataset.notificationCount = unseenCount ? String(unseenCount) : "";
}

function renderUserQuestionSubmissions() {
  if (!elements.userQuestionSubmissionList) return;
  elements.userQuestionSubmissionList.replaceChildren();
  if (!state.userQuestionSubmissions.length) {
    const empty = document.createElement("p");
    empty.className = "debug-status";
    empty.textContent = "No submitted questions yet.";
    elements.userQuestionSubmissionList.appendChild(empty);
    return;
  }
  state.userQuestionSubmissions.slice(0, 12).forEach((submission) => {
    const card = document.createElement("article");
    card.className = "user-question-submission-card";
    card.dataset.status = submission.status;
    const title = document.createElement("strong");
    title.textContent = submission.question?.canonicalAnswer || submission.question?.id || "Submitted question";
    const status = document.createElement("span");
    status.textContent = submission.status;
    const detail = document.createElement("p");
    detail.textContent = submission.status === "denied"
      ? `Denied: ${submission.review?.reason || "No reason provided."} ${formatCoins(submission.cost || userQuestionSubmissionCost)} refunded.`
      : submission.status === "approved"
        ? "Approved and added to the question bank."
        : "Pending admin review.";
    card.append(title, status, detail);
    elements.userQuestionSubmissionList.appendChild(card);
  });
}

async function openUserQuestionScreen() {
  buildUserQuestionScreen();
  setHidden(elements.modeScreen, true);
  setHidden(elements.userQuestionScreen, false);
  if (state.userQuestionDraftStorageUserKey !== getUserQuestionDraftStorageUserKey()) {
    restoreUserQuestionDraft();
  }
  await loadUserQuestionSubmissions({ markSeen: true });
  playSound("click");
}

function closeUserQuestionScreen() {
  saveUserQuestionDraft({ announce: false });
  setHidden(elements.userQuestionScreen, true);
  setHidden(elements.modeScreen, false);
  saveSubmissionSeenIds([...loadSubmissionSeenIds(), ...getResolvedUserSubmissionIds()]);
  updateQuestionSubmissionNotificationDot();
  playSound("click");
}

async function loadDevQuestionSubmissions() {
  if (!elements.devSubmissionStatus) return;
  try {
    elements.devSubmissionStatus.textContent = "Loading player submissions...";
    const response = await fetch("/api/admin/question-submissions", { credentials: "same-origin", cache: "no-store" });
    const result = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(result.error || `Review queue failed with status ${response.status}.`);
    state.devQuestionSubmissions = Array.isArray(result.submissions) ? result.submissions : [];
    renderDevQuestionSubmissions();
  } catch (error) {
    elements.devSubmissionStatus.textContent = error.message || "Could not load player submissions.";
    playSound("error");
  }
}

function renderDevQuestionSubmissions() {
  elements.devSubmissionList.replaceChildren();
  elements.devSubmissionReviewPanel.replaceChildren();
  const pending = state.devQuestionSubmissions.filter((submission) => submission.status === "pending");
  if (!pending.length) {
    const empty = document.createElement("p");
    empty.className = "debug-status";
    empty.textContent = "No pending player-created cards.";
    elements.devSubmissionList.appendChild(empty);
    state.devSelectedSubmissionId = "";
    elements.devSubmissionStatus.textContent = `${state.devQuestionSubmissions.length} total submission${state.devQuestionSubmissions.length === 1 ? "" : "s"}, 0 pending.`;
    return;
  }
  if (!pending.some((submission) => submission.id === state.devSelectedSubmissionId)) {
    state.devSelectedSubmissionId = "";
  }
  pending.forEach((submission) => elements.devSubmissionList.appendChild(createDevSubmissionButton(submission)));
  renderDevSubmissionReviewPanel();
  elements.devSubmissionStatus.textContent = `${pending.length} pending player-created card${pending.length === 1 ? "" : "s"} need review.`;
}

function createDevSubmissionButton(submission) {
  const question = submission.question || {};
  const button = document.createElement("button");
  button.type = "button";
  button.className = "dev-submission-list-button";
  button.dataset.submissionSelect = submission.id;
  button.dataset.selected = String(submission.id === state.devSelectedSubmissionId);
  const id = document.createElement("strong");
  id.textContent = `ID:${question.id || submission.id}`;
  const meta = document.createElement("span");
  meta.textContent = `${submission.creator?.name || "Player"} | ${question.canonicalAnswer || "No answer yet"}`;
  button.append(id, meta);
  return button;
}

function handleDevSubmissionListClick(event) {
  const button = event.target.closest("[data-submission-select]");
  if (!button) return;
  state.devSelectedSubmissionId = button.dataset.submissionSelect || "";
  renderDevQuestionSubmissions();
  playSound("click");
}

function renderDevSubmissionReviewPanel() {
  elements.devSubmissionReviewPanel.replaceChildren();
  const submission = state.devQuestionSubmissions.find((entry) => entry.id === state.devSelectedSubmissionId && entry.status === "pending");
  if (!submission) {
    const empty = document.createElement("p");
    empty.className = "debug-status";
    empty.textContent = "Select a submitted card to review.";
    elements.devSubmissionReviewPanel.appendChild(empty);
    return;
  }

  elements.devSubmissionReviewPanel.appendChild(createDevSubmissionCard(submission));
  updateDevSubmissionReviewPreview();
}

function createDevSubmissionCard(submission) {
  const question = submission.question || {};
  const card = document.createElement("article");
  card.className = "dev-submission-card";
  card.dataset.submissionId = submission.id;
  const header = document.createElement("div");
  header.className = "dev-panel-heading";
  const title = document.createElement("div");
  const eyebrow = document.createElement("p");
  eyebrow.className = "eyebrow";
  eyebrow.textContent = `${submission.creator?.name || "Player"} · ${new Date(submission.createdAt || Date.now()).toLocaleString()}`;
  const h3 = document.createElement("h3");
  h3.textContent = question.canonicalAnswer || question.id || "Submitted card";
  title.append(eyebrow, h3);
  header.appendChild(title);

  const grid = document.createElement("div");
  grid.className = "dev-submission-edit-grid";
  grid.append(
    createReviewSelect("theme", "Theme", triviaThemes, question.theme || triviaThemes[0]),
    createReviewSelect("difficulty", "Difficulty", ["easy", "medium", "hard"], normalizeDifficulty(question.difficulty)),
    createReviewSelect("type", "Type", ["text", "image"], question.type === "image" ? "image" : "text"),
    createReviewSelect("questionStyle", "Style", ["standard", "multiple-choice"], question.questionStyle === MULTIPLE_CHOICE_STYLE ? MULTIPLE_CHOICE_STYLE : "standard"),
    createReviewSelect("gradingStrictness", "Strictness", gradingStrictnessOptions, normalizeGradingStrictness(question.gradingStrictness)),
    createReviewField("id", "ID", question.id || "", "input")
  );
  const body = document.createElement("div");
  body.className = "dev-submission-body";
  body.append(
    createReviewField("question", "Question", question.question || "", "textarea"),
    createReviewField("canonicalAnswer", "Main answer", question.canonicalAnswer || "", "textarea"),
    createReviewField("acceptedAnswers", "Accepted answers", (question.acceptedAnswers || []).join(", "), "textarea"),
    createReviewField("botCards", question.questionStyle === MULTIPLE_CHOICE_STYLE ? "Incorrect answers" : "Wrong bot answers", question.questionStyle === MULTIPLE_CHOICE_STYLE
      ? (question.multipleChoiceOptions || []).filter((answer) => normalizeMultipleChoiceOption(answer) !== normalizeMultipleChoiceOption(question.canonicalAnswer)).join(", ")
      : (question.botCards || []).join(", "), "textarea"),
    createReviewField("rejectedAnswers", "Rejected answers", (question.rejectedAnswers || []).join(", "), "textarea"),
    createReviewField("imageUrl", "Image URL", question.image?.url || "", "input"),
    createReviewField("imageAlt", "Image alt", question.image?.alt || "", "input"),
    createReviewField("imageCredit", "Image credit", question.image?.credit || "", "input")
  );
  const denyReason = createReviewField("denyReason", "Deny reason", "", "textarea");
  denyReason.classList.add("dev-submission-deny-reason");
  denyReason.querySelector("[data-review-field]")?.setAttribute("placeholder", "Example: similar question already exists, content not permitted, answer is unclear");
  const actions = document.createElement("div");
  actions.className = "dev-create-actions";
  const approve = document.createElement("button");
  approve.type = "button";
  approve.className = "primary-button";
  approve.dataset.submissionAction = "approve";
  approve.textContent = "Approve";
  const deny = document.createElement("button");
  deny.type = "button";
  deny.className = "icon-button danger-button";
  deny.dataset.submissionAction = "deny";
  deny.textContent = "Deny";
  actions.append(approve, deny);

  const previewShell = document.createElement("aside");
  previewShell.className = "dev-create-preview-shell dev-submission-preview-shell";
  previewShell.innerHTML = `
    <p class="eyebrow">Review preview</p>
    <section class="black-card dev-create-preview-card text-only" data-review-preview-card aria-label="Submitted card preview">
      <div class="question-meta">
        <p>Submitted card</p>
        <div class="question-badges" data-review-preview-meta></div>
      </div>
      <figure class="question-image">
        <img data-review-preview-image alt="">
        <div class="question-image-placeholder" data-review-preview-placeholder>Image preview</div>
        <figcaption data-review-preview-credit></figcaption>
      </figure>
      <h2 data-review-preview-question>Question preview</h2>
    </section>
  `;

  const editor = document.createElement("div");
  editor.className = "dev-submission-editor";
  editor.append(grid, body, denyReason, actions);
  card.append(header, editor, previewShell);
  return card;
}

function createReviewField(name, labelText, value, type) {
  const label = document.createElement("label");
  label.dataset.reviewFieldWrap = name;
  const span = document.createElement("span");
  span.textContent = labelText;
  const input = type === "textarea" ? document.createElement("textarea") : document.createElement("input");
  input.dataset.reviewField = name;
  input.value = value;
  if (type === "textarea") {
    input.rows = 3;
  }
  label.append(span, input);
  return label;
}

function createReviewSelect(name, labelText, options, value) {
  const label = document.createElement("label");
  const span = document.createElement("span");
  span.textContent = labelText;
  const select = document.createElement("select");
  select.dataset.reviewField = name;
  options.forEach((option) => {
    const item = document.createElement("option");
    item.value = option;
    item.textContent = name === "gradingStrictness" ? getGradingStrictnessLabel(option) : option;
    item.selected = option === value;
    select.appendChild(item);
  });
  label.append(span, select);
  return label;
}

function getReviewCardPayload(card) {
  const field = (name) => card.querySelector(`[data-review-field="${name}"]`)?.value || "";
  const payload = {
    id: formatDevQuestionId(field("id")),
    type: field("type") === "image" ? "image" : "text",
    questionStyle: field("questionStyle") === MULTIPLE_CHOICE_STYLE ? MULTIPLE_CHOICE_STYLE : "standard",
    gradingStrictness: field("questionStyle") === MULTIPLE_CHOICE_STYLE
      ? "exact"
      : normalizeGradingStrictness(field("gradingStrictness")),
    theme: field("theme"),
    difficulty: normalizeDifficulty(field("difficulty")),
    question: field("question").trim(),
    canonicalAnswer: field("canonicalAnswer").trim(),
    acceptedAnswers: parseCommaSeparatedAnswers(field("acceptedAnswers")),
    botCards: parseCommaSeparatedAnswers(field("botCards")),
    rejectedAnswers: parseCommaSeparatedAnswers(field("rejectedAnswers"))
  };
  if (payload.questionStyle === MULTIPLE_CHOICE_STYLE) {
    const incorrect = parseCommaSeparatedAnswers(field("botCards")).slice(0, 3);
    payload.acceptedAnswers = [];
    payload.botCards = [];
    payload.rejectedAnswers = [];
    payload.multipleChoiceOptions = getMultipleChoiceDraftOptions(payload.canonicalAnswer, incorrect);
  }
  if (payload.type === "image") {
    payload.image = {
      url: field("imageUrl").trim(),
      alt: field("imageAlt").trim(),
      credit: field("imageCredit").trim()
    };
  }
  return payload;
}

function validateReviewMultipleChoiceDraft(card) {
  const style = card?.querySelector('[data-review-field="questionStyle"]')?.value || "standard";
  if (style !== MULTIPLE_CHOICE_STYLE) {
    return true;
  }
  return validateMultipleChoiceDraft(
    card.querySelector('[data-review-field="canonicalAnswer"]')?.value || "",
    parseCommaSeparatedAnswers(card.querySelector('[data-review-field="botCards"]')?.value || ""),
    card.querySelector('[data-review-field="botCards"]'),
    elements.devSubmissionStatus
  );
}

function updateDevSubmissionReviewPreview() {
  const card = elements.devSubmissionReviewPanel?.querySelector("[data-submission-id]");
  if (!card) return;
  const payload = getReviewCardPayload(card);
  const preview = card.querySelector("[data-review-preview-card]");
  const meta = card.querySelector("[data-review-preview-meta]");
  const question = card.querySelector("[data-review-preview-question]");
  const image = card.querySelector("[data-review-preview-image]");
  const placeholder = card.querySelector("[data-review-preview-placeholder]");
  const credit = card.querySelector("[data-review-preview-credit]");
  if (!preview || !meta || !question || !image || !placeholder || !credit) return;

  const isImage = payload.type === "image";
  const strictnessSelect = card.querySelector('[data-review-field="gradingStrictness"]');
  if (strictnessSelect) {
    strictnessSelect.disabled = payload.questionStyle === MULTIPLE_CHOICE_STYLE;
    strictnessSelect.closest("label")?.classList.toggle("field-muted", payload.questionStyle === MULTIPLE_CHOICE_STYLE);
  }
  preview.classList.toggle("text-only", !isImage);
  meta.replaceChildren();
  [payload.theme || "Theme", isImage ? "Image" : "Text", payload.questionStyle === MULTIPLE_CHOICE_STYLE ? "Multiple choice" : getGradingStrictnessLabel(payload.gradingStrictness), payload.difficulty].filter(Boolean).forEach((text) => {
    const badge = document.createElement("span");
    badge.textContent = text;
    meta.appendChild(badge);
  });

  question.textContent = payload.question || "Question preview";
  credit.textContent = payload.image?.credit || "";
  setHidden(credit, !credit.textContent);
  image.onload = () => {
    setHidden(image, false);
    setHidden(placeholder, true);
  };
  image.onerror = () => {
    placeholder.textContent = "Image failed to load.";
    setHidden(image, true);
    setHidden(placeholder, false);
  };

  if (isImage && payload.image?.url) {
    image.alt = payload.image.alt || "Submitted question image";
    if (image.dataset.previewUrl !== payload.image.url) {
      image.dataset.previewUrl = payload.image.url;
      image.removeAttribute("src");
      placeholder.textContent = "Loading image...";
      setHidden(image, true);
      setHidden(placeholder, false);
      image.src = payload.image.url;
    }
  } else {
    image.removeAttribute("src");
    delete image.dataset.previewUrl;
    image.alt = "";
    placeholder.textContent = isImage ? "Image URL preview" : "Text-only question";
    setHidden(image, true);
    setHidden(placeholder, isImage);
  }
}

async function handleDevSubmissionClick(event) {
  const button = event.target.closest("[data-submission-action]");
  if (!button) return;
  const card = button.closest("[data-submission-id]");
  const id = card?.dataset.submissionId;
  if (!id) return;
  const action = button.dataset.submissionAction;
  if (action === "approve" && !validateReviewMultipleChoiceDraft(card)) {
    return;
  }
  button.disabled = true;
  try {
    const body = action === "approve"
      ? { question: getReviewCardPayload(card) }
      : { reason: getRequiredDenyReason(card) };
    if (action === "deny" && !body.reason) {
      button.disabled = false;
      return;
    }
    elements.devSubmissionStatus.textContent = `${action === "approve" ? "Approving" : "Denying"} submission...`;
    const response = await fetch(`/api/admin/question-submissions/${encodeURIComponent(id)}/${action}`, {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body)
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(result.error || `${action} failed with status ${response.status}.`);
    elements.devSubmissionStatus.textContent = action === "approve"
      ? `Approved ${result.submission?.question?.id || id}.`
      : `Denied ${result.submission?.question?.id || id}.`;
    if (result.submission) {
      broadcastRealtimeAppEvent("question-submission-updated", {
        creatorId: result.submission.creator?.id || "",
        submission: {
          id: result.submission.id,
          status: result.submission.status,
          question: result.submission.question,
          cost: result.submission.cost || userQuestionSubmissionCost,
          createdAt: result.submission.createdAt || 0,
          updatedAt: result.submission.updatedAt || Date.now(),
          review: result.submission.review || null,
          creator: result.submission.creator || null
        }
      });
    }
    await loadDevQuestionSubmissions();
    state.questionDebugBank = [];
    playSound("reveal");
  } catch (error) {
    elements.devSubmissionStatus.textContent = error.message || "Review action failed.";
    playSound("error");
  } finally {
    button.disabled = false;
  }
}

function getRequiredDenyReason(card) {
  const input = card?.querySelector('[data-review-field="denyReason"]');
  const reason = String(input?.value || "").trim();
  if (!reason && input) {
    input.setCustomValidity("A denial reason is required.");
    input.reportValidity();
    input.setCustomValidity("");
  }
  return reason;
}

async function loadDevRooms() {
  if (!elements.devRoomStatus) return;
  try {
    elements.devRoomStatus.textContent = "Loading rooms...";
    const response = await fetch("/api/admin/rooms", { credentials: "same-origin", cache: "no-store" });
    const result = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(result.error || `Room load failed with status ${response.status}.`);
    state.devRooms = Array.isArray(result.rooms) ? result.rooms : [];
    renderDevRooms();
  } catch (error) {
    elements.devRoomStatus.textContent = error.message || "Could not load rooms.";
    playSound("error");
  }
}

function renderDevRooms() {
  elements.devRoomList.replaceChildren();
  if (!state.devRooms.length) {
    const empty = document.createElement("p");
    empty.className = "debug-status";
    empty.textContent = "No rooms are currently stored.";
    elements.devRoomList.appendChild(empty);
    elements.devRoomStatus.textContent = "0 rooms stored.";
    return;
  }
  state.devRooms.forEach((room) => {
    const card = document.createElement("article");
    card.className = "dev-room-card";
    card.dataset.roomCode = room.code;
    const summary = document.createElement("div");
    const title = document.createElement("strong");
    title.textContent = room.code;
    const meta = document.createElement("span");
    meta.textContent = `${room.status} | ${room.activePlayers || 0}/${room.settings?.maxPlayers || 0} players | host ${room.host?.name || "Host"}`;
    const participants = document.createElement("p");
    participants.textContent = (room.participants || [])
      .map((participant) => `${participant.host ? "Host " : ""}${participant.name}${participant.bot ? " bot" : ""}${participant.spectator ? " spectator" : ""}`)
      .join(", ") || "No participants.";
    summary.append(title, meta, participants);
    const actions = document.createElement("div");
    actions.className = "dev-room-actions";
    const close = document.createElement("button");
    close.type = "button";
    close.className = "icon-button";
    close.dataset.devRoomAction = "close";
    close.textContent = "Close";
    const remove = document.createElement("button");
    remove.type = "button";
    remove.className = "icon-button danger-button";
    remove.dataset.devRoomAction = "delete";
    remove.textContent = "Delete";
    actions.append(close, remove);
    card.append(summary, actions);
    elements.devRoomList.appendChild(card);
  });
  elements.devRoomStatus.textContent = `${state.devRooms.length} room${state.devRooms.length === 1 ? "" : "s"} stored.`;
}

async function handleDevRoomClick(event) {
  const button = event.target.closest("[data-dev-room-action]");
  if (!button) return;
  const card = button.closest("[data-room-code]");
  const code = card?.dataset.roomCode;
  if (!code) return;
  const action = button.dataset.devRoomAction;
  button.disabled = true;
  try {
    const response = await fetch(`/api/admin/rooms/${encodeURIComponent(code)}${action === "close" ? "/close" : ""}`, {
      method: action === "delete" ? "DELETE" : "POST",
      credentials: "same-origin"
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(result.error || `${action} failed with status ${response.status}.`);
    elements.devRoomStatus.textContent = action === "delete" ? `Deleted ${code}.` : `Closed ${code}.`;
    await loadDevRooms();
    playSound("reveal");
  } catch (error) {
    elements.devRoomStatus.textContent = error.message || "Room action failed.";
    playSound("error");
  } finally {
    button.disabled = false;
  }
}

function getCurrentDevToolTab() {
  const selected = elements.devToolTabs?.querySelector("[data-dev-tab].selected");
  return selected?.dataset.devTab || "questions";
}

async function requestDevToolTab(tab) {
  if (getCurrentDevToolTab() === "create" && tab !== "create" && !(await confirmDiscardDevCreateProgress())) {
    return;
  }
  const returnId = getCurrentDevToolTab() === "create" ? (state.questionEditReturnId || state.questionEditOriginalId) : "";
  if (getCurrentDevToolTab() === "create" && tab !== "create") {
    resetDevQuestionCreateForm({ keepStatus: false });
  }
  setDevToolTab(tab);
  if (tab === "questions" && returnId) {
    focusQuestionDebugById(returnId);
  }
}

function setDevToolTab(tab) {
  const selectedTab = ["questions", "rooms", "diagnostics", "submissions", "create", "achievements", "profile", "overlays", "victory", "powers"].includes(tab) ? tab : "questions";
  elements.devToolTabs.querySelectorAll("[data-dev-tab]").forEach((button) => {
    button.classList.toggle("selected", button.dataset.devTab === selectedTab);
  });
  elements.devToolScreen.querySelectorAll("[data-dev-panel]").forEach((panel) => {
    setHidden(panel, panel.dataset.devPanel !== selectedTab);
  });
  if (selectedTab === "questions") {
    loadQuestionDebugBank();
  }
  if (selectedTab === "rooms") {
    loadDevRooms();
  }
  if (selectedTab === "diagnostics") {
    renderRoomDiagnosticsPanel();
  }
  if (selectedTab === "submissions") {
    loadDevQuestionSubmissions();
  }
  if (selectedTab === "achievements") {
    renderAchievementDebug();
  }
  if (selectedTab === "profile") {
    renderProfileDebug();
  }
  if (selectedTab === "victory") {
    renderDevVictoryPreview();
  }
  if (selectedTab === "powers") {
    renderPowerDebug();
  }
}

function getPowerDebugRefs(scope = "dev") {
  if (scope === "bot-match") {
    return {
      panel: elements.botPowerDebugPanel,
      pauseStatus: elements.botPowerDebugPauseStatus,
      ownerSelect: elements.botPowerOwnerSelect,
      searchInput: elements.botPowerSearchInput,
      powerSelect: elements.botPowerSelect,
      chaosToggle: elements.botPowerChaosToggle,
      pauseToggle: elements.botPowerPauseToggle,
      unlimitedToggle: elements.botPowerUnlimitedToggle,
      status: elements.botPowerStatus,
      hand: elements.botPowerHand
    };
  }
  return {
    panel: elements.devToolScreen,
    ownerSelect: elements.devPowerOwnerSelect,
    searchInput: elements.devPowerSearchInput,
    powerSelect: elements.devPowerSelect,
    chaosToggle: elements.devPowerChaosToggle,
    status: elements.devPowerStatus,
    hand: elements.devPowerHand
  };
}

function getPowerDebugOwners(scope = "dev") {
  if (scope === "bot-match") {
    const owners = getActiveOwners().filter((owner) => owner === "player" || isBotOwner(owner));
    return owners.length ? owners : ["player"];
  }
  const owners = getActiveOwners();
  return owners.length ? owners : ["player"];
}

function matchesPowerDebugSearch(power, searchText) {
  if (!searchText) {
    return true;
  }
  const haystack = [
    power.id,
    power.baseId,
    power.originalName,
    power.name,
    power.short,
    power.description,
    getDisplayedPowerDescription(power, "player"),
    rarityInfo[power.rarity]?.label
  ].join(" ").toLowerCase();
  return haystack.includes(searchText);
}

function renderPowerDebugPowerOptions(scope = "dev") {
  const refs = getPowerDebugRefs(scope);
  if (!refs.powerSelect) {
    return;
  }
  const selected = refs.powerSelect.value || "small_bounty";
  const searchText = String(refs.searchInput?.value || "").trim().toLowerCase();
  const showChaosVersions = Boolean(refs.chaosToggle?.checked);
  const optionPowers = powerDeck
    .flatMap((power) => {
      const chaosPower = canPowerBecomeChaosInfused(power.id)
        ? getPowerById(getChaosInfusedPowerId(power.id))
        : null;
      return showChaosVersions ? [chaosPower] : [power, chaosPower];
    })
    .filter(Boolean);
  const matches = optionPowers.filter((power) => matchesPowerDebugSearch(power, searchText));
  refs.powerSelect.replaceChildren();
  ["grey", "blue", "purple", "gold", "doom"].forEach((rarity) => {
    const rarityMatches = matches.filter((power) => getPowerById(getBasePowerId(power.id))?.rarity === rarity);
    if (!rarityMatches.length) {
      return;
    }
    const group = document.createElement("optgroup");
    group.label = rarityInfo[rarity].label;
    rarityMatches.forEach((power) => {
      const option = document.createElement("option");
      option.value = power.id;
      option.textContent = `${power.name} (${power.id})`;
      group.appendChild(option);
    });
    refs.powerSelect.appendChild(group);
  });
  if (!matches.length) {
    const option = document.createElement("option");
    option.value = "";
    option.textContent = showChaosVersions ? "No matching chaos powers" : "No matching power-ups";
    option.disabled = true;
    refs.powerSelect.appendChild(option);
  }
  const normalizedSelected = showChaosVersions ? getChaosInfusedPowerId(selected) : selected;
  refs.powerSelect.value = matches.some((power) => power.id === normalizedSelected) ? normalizedSelected : matches[0]?.id || "";
}

function renderPowerDebug(scope = "dev") {
  const refs = getPowerDebugRefs(scope);
  if (!refs.ownerSelect || !refs.powerSelect || !refs.hand) {
    return;
  }
  const owners = getPowerDebugOwners(scope);
  const selectedOwner = owners.includes(refs.ownerSelect.value) ? refs.ownerSelect.value : owners[0];
  refs.ownerSelect.replaceChildren(...owners.map((owner) => {
    const option = document.createElement("option");
    option.value = owner;
    option.textContent = getOwnerLabel(owner);
    return option;
  }));
  refs.ownerSelect.value = selectedOwner;
  renderPowerDebugPowerOptions(scope);
  refs.chaosToggle.disabled = false;
  const hand = state.powerHands[selectedOwner] || [];
  refs.hand.replaceChildren(...hand.map((powerId) => {
    const power = getPowerById(powerId);
    const card = document.createElement(scope === "bot-match" ? "button" : "article");
    card.className = scope === "bot-match" ? "profile-debug-card bot-power-debug-card" : "profile-debug-card";
    if (scope === "bot-match") {
      card.type = "button";
      card.dataset.owner = selectedOwner;
      card.dataset.powerId = powerId;
      card.dataset.tooltip = "Click to remove this power-up";
    }
    if (power?.rarity) {
      card.dataset.rarity = power.rarity;
    }
    card.dataset.state = isChaosInfusedPower(powerId) ? "enabled" : "natural";
    card.classList.toggle("chaos-infused", isChaosInfusedPower(powerId));
    card.innerHTML = `<strong>${power?.name || powerId}</strong><span>${power?.short || "Unknown"}</span><p>${isChaosInfusedPower(powerId) ? "Chaos-infused" : rarityInfo[power?.rarity]?.label || "Power-up"}</p>`;
    return card;
  }));
  if (!hand.length) {
    const empty = document.createElement("p");
    empty.className = "debug-status";
    empty.textContent = "Selected owner has no power-ups.";
    refs.hand.appendChild(empty);
  }
}

function renderAllPowerDebugPanels() {
  renderPowerDebug("dev");
  renderPowerDebug("bot-match");
}

function getSelectedDebugPowerId(scope = "dev") {
  const refs = getPowerDebugRefs(scope);
  const basePowerId = refs.powerSelect?.value || "";
  if (isChaosInfusedPower(basePowerId)) {
    return basePowerId;
  }
  if (refs.chaosToggle?.checked && canPowerBecomeChaosInfused(basePowerId)) {
    return getChaosInfusedPowerId(basePowerId);
  }
  return basePowerId;
}

function setPowerDebugStatus(scope, message) {
  const refs = getPowerDebugRefs(scope);
  if (refs.status) {
    refs.status.textContent = message;
  }
}

function publishPowerDebugState() {
  if (isRoomMode() && isCurrentHost()) {
    publishRoomPowerState(getRoomPowerStatePayload()).catch(() => {});
  }
}

function forceDebugBotPowerUse(owner, powerId) {
  if (state.mode !== "bots" || !isBotOwner(owner) || !powerId) {
    return null;
  }
  state.botPowerSchedule = state.botPowerSchedule || {};
  state.botPowerSchedule[owner] = {
    ...(state.botPowerSchedule[owner] || {}),
    triggerAt: state.timerRemaining,
    used: false,
    forcedPowerId: powerId
  };
  const used = commitSingleBotPowerUp(owner, { forcePowerId: powerId });
  if (used && state.botPowerSchedule[owner]) {
    state.botPowerSchedule[owner].used = true;
  }
  return used;
}

function addDebugPowerSlot(owner, powerId) {
  if (!owner || !powerId) {
    return false;
  }
  const limit = getPowerHandLimit(owner);
  if (limit <= 0) {
    return false;
  }
  const hand = [...(state.powerHands[owner] || [])].slice(0, limit);
  if (hand.length < limit) {
    hand.push(powerId);
    state.powerHands[owner] = hand;
    markFreshPowerUps(owner, [powerId]);
  } else {
    playPowerHandExitAnimation(owner, { indexes: [limit - 1] });
    hand[limit - 1] = powerId;
    clearFreshPowerAnimations(owner);
    state.powerHands[owner] = hand;
    markPowerHandAnimation(owner, [powerId], "refresh", { playExit: false });
  }
  return true;
}

function addDebugPowerToHand(scope = "dev") {
  const owner = getPowerDebugRefs(scope).ownerSelect?.value;
  const powerId = getSelectedDebugPowerId(scope);
  const power = getPowerById(powerId);
  if (!owner || !power) {
    setPowerDebugStatus(scope, "Choose a valid owner and power-up.");
    return;
  }
  if (getPowerHandLimit(owner) <= 0) {
    setPowerDebugStatus(scope, "Start a match before adding power-ups.");
    return;
  }
  addDebugPowerSlot(owner, powerId);
  const botUsed = scope === "bot-match" && isBotOwner(owner)
    ? forceDebugBotPowerUse(owner, powerId)
    : null;
  const botSuffix = botUsed === true
    ? " The bot used it immediately."
    : botUsed === false
      ? " The bot could not use it right now."
      : "";
  setPowerDebugStatus(scope, `Added ${power.name} to ${getOwnerLabel(owner)}.${botSuffix}`);
  renderAllPowerDebugPanels();
  renderPowerUps();
  publishPowerDebugState();
  playSound("reveal");
}

function removeDebugPowerFromHand(scope = "dev", owner, powerId) {
  if (!owner || !powerId || !state.powerHands[owner]?.length) {
    return;
  }
  const removeIndex = state.powerHands[owner].indexOf(powerId);
  if (removeIndex < 0) {
    return;
  }
  playPowerHandExitAnimation(owner, { indexes: [removeIndex] });
  state.powerHands[owner] = state.powerHands[owner].filter((_, index) => index !== removeIndex);
  state.freshPowerUps[owner] = (state.freshPowerUps[owner] || []).filter((id) => id !== powerId);
  setSelectedPowerIds(owner, getSelectedPowerIds(owner).filter((id) => id !== powerId));
  if (state.botPowerSchedule?.[owner]?.forcedPowerId === powerId) {
    delete state.botPowerSchedule[owner].forcedPowerId;
  }
  setPowerDebugStatus(scope, `Removed ${getPowerById(powerId)?.name || powerId} from ${getOwnerLabel(owner)}.`);
  renderAllPowerDebugPanels();
  renderPowerUps();
  publishPowerDebugState();
  playSound("click");
}

function fillDebugPowerHand(scope = "dev") {
  const owner = getPowerDebugRefs(scope).ownerSelect?.value;
  if (!owner || getPowerHandLimit(owner) <= 0) {
    setPowerDebugStatus(scope, "Start a match before filling a hand.");
    return;
  }
  const powerId = getSelectedDebugPowerId(scope);
  if (!getPowerById(powerId)) {
    setPowerDebugStatus(scope, "Choose a valid power-up before filling a hand.");
    return;
  }
  const limit = getPowerHandLimit(owner);
  const hand = [powerId];
  while (hand.length < limit) {
    const drawnPowerId = drawPowerCard(hand, getPowerDrawOptions(owner));
    if (!drawnPowerId) {
      break;
    }
    hand.push(drawnPowerId);
  }
  clearFreshPowerAnimations(owner);
  state.powerHands[owner] = hand;
  markPowerHandAnimation(owner, hand, "refresh");
  const botUsed = scope === "bot-match" && isBotOwner(owner)
    ? forceDebugBotPowerUse(owner, powerId)
    : null;
  const botSuffix = botUsed === true
    ? " The bot used the first card immediately."
    : botUsed === false
      ? " The bot could not use the first card right now."
      : "";
  setPowerDebugStatus(scope, `Filled ${getOwnerLabel(owner)}'s hand starting with ${getPowerById(powerId).name}.${botSuffix}`);
  renderAllPowerDebugPanels();
  renderPowerUps();
  publishPowerDebugState();
  playSound("reveal");
}

function clearDebugPowerHand(scope = "dev") {
  const owner = getPowerDebugRefs(scope).ownerSelect?.value;
  if (!owner) {
    return;
  }
  playPowerHandExitAnimation(owner);
  state.powerHands[owner] = [];
  state.freshPowerUps[owner] = [];
  clearSelectedPowerUps(owner);
  if (state.botPowerSchedule?.[owner]) {
    delete state.botPowerSchedule[owner].forcedPowerId;
  }
  setPowerDebugStatus(scope, `Cleared ${getOwnerLabel(owner)}'s hand.`);
  renderAllPowerDebugPanels();
  renderPowerUps();
  publishPowerDebugState();
  playSound("click");
}

function isAchievementProgressBased(achievement) {
  return Boolean(achievement.progressKey || achievement.completionRarity || achievement.completionAll);
}

function getAchievementDebugRows() {
  const query = normalizeTriviaAnswer(elements.devAchievementSearchInput?.value || "");
  const rarityFilter = elements.devAchievementRarityFilter?.value || "all";
  const typeFilter = elements.devAchievementTypeFilter?.value || "all";
  return achievementCatalog
    .filter((achievement) => {
      const isTitle = Boolean(achievementTitleMap[achievement.id]);
      const isProgress = isAchievementProgressBased(achievement);
      const haystack = normalizeTriviaAnswer(`${achievement.name} ${achievement.id} ${achievement.rarity} ${achievement.description}`);
      if (query && !haystack.includes(query)) {
        return false;
      }
      if (rarityFilter !== "all" && achievement.rarity !== rarityFilter) {
        return false;
      }
      if (typeFilter === "title" && !isTitle) {
        return false;
      }
      if (typeFilter === "progress" && !isProgress) {
        return false;
      }
      if (typeFilter === "hidden" && !achievement.hidden) {
        return false;
      }
      return true;
    })
    .sort((a, b) => getRarityRank(a.rarity) - getRarityRank(b.rarity) || a.name.localeCompare(b.name));
}

function renderAchievementDebug() {
  if (!elements.devAchievementGrid) {
    return;
  }
  const records = loadUnlockedAchievements();
  const progress = loadAchievementProgress();
  const rows = getAchievementDebugRows();
  elements.devAchievementGrid.replaceChildren();
  rows.forEach((achievement) => {
    const unlocked = Boolean(records[achievement.id]);
    const isTitle = Boolean(achievementTitleMap[achievement.id]);
    const isProgress = isAchievementProgressBased(achievement);
    const target = getLongTermProgressTarget(achievement);
    const value = Math.min(target, getLongTermProgressValue(achievement, records, progress));
    const row = document.createElement("article");
    row.className = "achievement-debug-card";
    row.dataset.rarity = achievement.rarity;
    row.dataset.achievementId = achievement.id;
    row.dataset.unlocked = String(unlocked);
    const top = document.createElement("div");
    top.className = "achievement-debug-card-top";
    const title = document.createElement("div");
    title.innerHTML = `<strong>${achievement.name}</strong><span>${rarityInfo[achievement.rarity].label} ${isTitle ? "tag" : "achievement"}${achievement.hidden ? " · hidden" : ""}</span>`;
    const statePill = document.createElement("em");
    statePill.textContent = unlocked ? "Unlocked" : "Locked";
    top.append(title, statePill);

    const condition = document.createElement("p");
    condition.textContent = achievement.description;
    if (achievement.hidden) {
      condition.dataset.hiddenCondition = "true";
    }

    const progressWrap = document.createElement("div");
    progressWrap.className = "achievement-debug-progress";
    if (isProgress) {
      const bar = document.createElement("span");
      bar.style.width = `${Math.max(0, Math.min(100, (value / target) * 100))}%`;
      const label = document.createElement("small");
      label.textContent = `${Math.floor(value).toLocaleString()}/${target.toLocaleString()}`;
      progressWrap.append(bar, label);
    } else {
      progressWrap.textContent = "No progress counter";
    }

    const controls = document.createElement("div");
    controls.className = "achievement-debug-actions";
    if (achievement.progressKey) {
      const input = document.createElement("input");
      input.type = "number";
      input.min = "0";
      input.step = "1";
      input.value = String(getProgressValue(progress, achievement.progressKey));
      input.dataset.achievementProgressInput = achievement.id;
      input.setAttribute("aria-label", `${achievement.name} progress`);
      controls.appendChild(input);
      const setButton = document.createElement("button");
      setButton.type = "button";
      setButton.className = "icon-button";
      setButton.dataset.achievementDebugAction = "set-progress";
      setButton.textContent = "Set Progress";
      controls.appendChild(setButton);
    }
    const toggleButton = document.createElement("button");
    toggleButton.type = "button";
    toggleButton.className = unlocked ? "icon-button danger-button" : "icon-button";
    toggleButton.dataset.achievementDebugAction = unlocked ? "disable" : "enable";
    toggleButton.textContent = unlocked ? "Disable" : "Enable";
    controls.appendChild(toggleButton);

    row.append(top, condition, progressWrap, controls);
    elements.devAchievementGrid.appendChild(row);
  });
  elements.devAchievementStatus.textContent = `${rows.length} achievement${rows.length === 1 ? "" : "s"} shown. Hidden conditions are fully visible here.`;
}

function resetAchievementMilestonesFromDebug() {
  saveClaimedAchievementMilestones([]);
  renderProfile();
  renderAchievementDebug();
  if (isModalOpen(elements.achievementsModal)) {
    renderAchievementLibrary();
  }
  if (isModalOpen(elements.profileCustomModal)) {
    renderProfileCustomizationModal();
  }
  elements.devAchievementStatus.textContent = "Achievement milestones reset.";
  playSound("click");
}

function handleAchievementDebugClick(event) {
  const button = event.target.closest("[data-achievement-debug-action]");
  if (!button) {
    return;
  }
  const card = button.closest("[data-achievement-id]");
  const achievement = achievementCatalog.find((entry) => entry.id === card?.dataset.achievementId);
  if (!achievement) {
    return;
  }
  const action = button.dataset.achievementDebugAction;
  const records = loadUnlockedAchievements();
  const progress = loadAchievementProgress();
  if (action === "enable") {
    setAchievementDebugDisabled(achievement.id, false);
    records[achievement.id] = records[achievement.id] || { unlockedAt: new Date().toISOString(), debug: true };
    elements.devAchievementStatus.textContent = `${achievement.name} enabled.`;
  }
  if (action === "disable") {
    delete records[achievement.id];
    setAchievementDebugDisabled(achievement.id, true);
    saveUnseenAchievements(loadUnseenAchievements().filter((id) => id !== achievement.id));
    if (state.profile.equippedTitleId === achievement.id) {
      setEquippedAchievement("");
    }
    elements.devAchievementStatus.textContent = `${achievement.name} disabled.`;
  }
  if (action === "set-progress" && achievement.progressKey) {
    const input = card.querySelector(`[data-achievement-progress-input="${achievement.id}"]`);
    setProgressValue(progress, achievement.progressKey, input?.value || 0);
    elements.devAchievementStatus.textContent = `${achievement.name} progress set.`;
  }
  saveUnlockedAchievements(records);
  saveAchievementProgress(progress);
  refreshLongTermAchievementUnlocks(records, progress);
  renderAchievementDebug();
  if (isModalOpen(elements.achievementsModal)) {
    renderAchievementLibrary();
  }
  playSound("click");
}

function handleAchievementDebugChange(event) {
  if (event.target.matches("[data-achievement-progress-input]")) {
    event.target.value = String(Math.max(0, Math.floor(Number(event.target.value) || 0)));
  }
}

function getProfileDebugItems() {
  return [
    ...profileCardStyles.map((item) => ({ ...item, type: "style", key: getProfileCustomizationKey("style", item.id) })),
    ...profileCardColours.map((item) => ({ ...item, type: "color", key: getProfileCustomizationKey("color", item.id) })),
    ...profileCardEffects.map((item) => ({ ...item, type: "effect", key: getProfileCustomizationKey("effect", item.id) })),
    ...profileCardPatterns.map((item) => ({ ...item, type: "pattern", key: getProfileCustomizationKey("pattern", item.id) })),
    ...profileFonts.map((item) => ({ ...item, type: "font", key: getProfileCustomizationKey("font", item.id) })),
    { ...profileTitleColourCustomization, type: "titleColor", key: getProfileCustomizationKey("titleColor", profileTitleColourCustomization.id) }
  ];
}

function renderProfileDebug() {
  if (!elements.devProfileGrid) {
    return;
  }
  const records = loadUnlockedAchievements();
  const progress = loadAchievementProgress();
  const debug = loadDebugProfileCustomizations();
  const badgeDebug = loadDebugSpecialBadges();
  elements.devProfileGrid.replaceChildren();
  specialPlayerBadges.forEach((badge) => {
    const natural = getNaturalSpecialBadgeIds().includes(badge.id);
    const stateLabel = badgeDebug.enabled.includes(badge.id)
      ? "enabled"
      : badgeDebug.disabled.includes(badge.id)
        ? "disabled"
        : natural ? "natural" : "locked";
    const card = document.createElement("article");
    card.className = "profile-debug-card";
    card.dataset.specialBadgeId = badge.id;
    card.dataset.state = stateLabel;
    const title = document.createElement("div");
    title.innerHTML = `<strong>${badge.name} Badge</strong><span>Special player badge</span>`;
    const condition = document.createElement("p");
    condition.textContent = badge.id === "creator"
      ? `${badge.condition} Current approved cards: ${getApprovedCreatorQuestionCount().toLocaleString()}.`
      : badge.condition;
    const progressText = document.createElement("small");
    progressText.textContent = stateLabel === "natural"
      ? "Unlocked naturally"
      : stateLabel === "enabled"
        ? "Forced enabled"
        : stateLabel === "disabled"
          ? "Disabled by dev tool"
          : "Not unlocked";
    const actions = document.createElement("div");
    actions.className = "profile-debug-card-actions";
    ["enabled", "disabled", "reset"].forEach((action) => {
      const button = document.createElement("button");
      button.type = "button";
      button.dataset.specialBadgeAction = action;
      button.textContent = action === "enabled" ? "Enable" : action === "disabled" ? "Disable" : "Reset";
      actions.appendChild(button);
    });
    card.append(title, condition, progressText, actions);
    elements.devProfileGrid.appendChild(card);
  });
  getProfileDebugItems().forEach((item) => {
    const status = getProfileUnlockStatus(item, item.type, records, progress);
    const card = document.createElement("article");
    card.className = "profile-debug-card";
    card.dataset.profileDebugKey = item.key;
    card.dataset.state = debug.enabled.includes(item.key) ? "enabled" : debug.disabled.includes(item.key) ? "disabled" : "natural";
    const typeLabel = item.type === "style"
      ? "Card theme"
      : item.type === "color"
        ? "Gradient colour"
        : item.type === "effect"
          ? "Card effect"
          : item.type === "pattern"
            ? "Card pattern"
            : "Prefix colour";
    const title = document.createElement("div");
    title.innerHTML = `<strong>${item.name}</strong><span>${typeLabel}</span>`;
    const condition = document.createElement("p");
    condition.textContent = item.condition || "Always unlocked.";
    const progressText = document.createElement("small");
    progressText.textContent = `${status.unlocked ? "Unlocked" : "Locked"} · ${status.text}`;
    const actions = document.createElement("div");
    actions.className = "profile-debug-card-actions";
    ["enabled", "disabled", "reset"].forEach((action) => {
      const button = document.createElement("button");
      button.type = "button";
      button.dataset.profileDebugAction = action;
      button.textContent = action === "enabled" ? "Enable" : action === "disabled" ? "Disable" : "Reset";
      actions.appendChild(button);
    });
    card.append(title, condition, progressText, actions);
    elements.devProfileGrid.appendChild(card);
  });
  elements.devProfileStatus.textContent = `${specialPlayerBadges.length} badge controls and ${getProfileDebugItems().length} profile customization items shown.`;
}

function handleProfileDebugClick(event) {
  const badgeButton = event.target.closest("[data-special-badge-action]");
  if (badgeButton) {
    const id = badgeButton.closest("[data-special-badge-id]")?.dataset.specialBadgeId;
    if (!id) {
      return;
    }
    setSpecialBadgeDebugState(id, badgeButton.dataset.specialBadgeAction);
    renderProfileDebug();
    elements.devProfileStatus.textContent = `${specialPlayerBadgeMap[id]?.name || id} badge ${badgeButton.dataset.specialBadgeAction}.`;
    playSound("click");
    return;
  }
  const button = event.target.closest("[data-profile-debug-action]");
  if (!button) {
    return;
  }
  const key = button.closest("[data-profile-debug-key]")?.dataset.profileDebugKey;
  if (!key) {
    return;
  }
  setProfileCustomizationDebugState(key, button.dataset.profileDebugAction);
  renderProfileDebug();
  if (isModalOpen(elements.profileCustomModal)) {
    renderProfileCustomizationModal();
  }
  elements.devProfileStatus.textContent = `${key} ${button.dataset.profileDebugAction}.`;
  playSound("click");
}

function setAllProfileDebugStates(mode) {
  const keys = getProfileDebugItems().map((item) => item.key);
  if (mode === "reset") {
    saveDebugProfileCustomizations({ enabled: [], disabled: [] });
    elements.devProfileStatus.textContent = "Profile customization debug reset.";
  } else {
    saveDebugProfileCustomizations({
      enabled: mode === "enabled" ? keys : [],
      disabled: mode === "disabled" ? keys.filter((key) => key !== "style:default" && key !== "pattern:none") : []
    });
    elements.devProfileStatus.textContent = mode === "enabled" ? "All profile customizations enabled." : "All profile customizations disabled.";
  }
  renderProfileDebug();
  if (isModalOpen(elements.profileCustomModal)) {
    renderProfileCustomizationModal();
  }
  playSound("click");
}

function openDevToolScreen(tab = "questions") {
  buildDevToolScreen();
  playSound("click");
  setHidden(elements.modeScreen, true);
  setHidden(elements.roomScreen, true);
  setHidden(elements.joinScreen, true);
  setHidden(elements.roomLobbyScreen, true);
  setHidden(elements.gameStage, true);
  setHidden(elements.roomChat, true);
  setHidden(elements.devToolScreen, false);
  setDevToolTab(tab);
}

function buildAdminAuthModal() {
  if (elements.adminAuthModal) {
    return;
  }

  const modal = document.createElement("div");
  modal.className = "admin-auth-modal hidden";
  modal.id = "adminAuthModal";
  modal.setAttribute("role", "dialog");
  modal.setAttribute("aria-modal", "true");
  modal.setAttribute("aria-labelledby", "adminAuthTitle");
  modal.innerHTML = `
    <section class="admin-auth-panel">
      <div class="settings-header">
        <div>
          <p class="eyebrow">Admin access</p>
          <h2 id="adminAuthTitle">Unlock Dev Tool</h2>
        </div>
        <button type="button" class="icon-button" id="adminAuthCancelButton" aria-label="Close admin login">Close</button>
      </div>
      <form class="admin-auth-form" id="adminAuthForm">
        <label for="adminTokenInput">
          <span>Admin token</span>
          <input id="adminTokenInput" type="password" autocomplete="current-password" placeholder="Paste ADMIN_TOKEN">
        </label>
        <button type="submit">Sign In</button>
      </form>
      <p class="debug-status" id="adminAuthStatus">Use the private ADMIN_TOKEN from Vercel. This unlocks local browser access only for this session.</p>
    </section>
  `;
  document.body.appendChild(modal);
  elements.adminAuthModal = modal;
  elements.adminAuthForm = modal.querySelector("#adminAuthForm");
  elements.adminTokenInput = modal.querySelector("#adminTokenInput");
  elements.adminAuthStatus = modal.querySelector("#adminAuthStatus");
  elements.adminAuthCancelButton = modal.querySelector("#adminAuthCancelButton");
  elements.adminAuthForm.addEventListener("submit", submitAdminLogin);
  elements.adminAuthCancelButton.addEventListener("click", closeAdminAuthModal);
  modal.addEventListener("click", (event) => {
    if (event.target === modal) {
      closeAdminAuthModal();
    }
  });
}

function updateAdminControls() {
  if (elements.menuDevToolButton) {
    elements.menuDevToolButton.textContent = state.adminAuthenticated ? "Dev Tool" : "Admin Login";
    elements.menuDevToolButton.dataset.adminState = state.adminAuthenticated ? "authenticated" : "locked";
  }
  if (elements.adminLogoutButton) {
    setHidden(elements.adminLogoutButton, !state.adminAuthenticated);
  }
  renderBotPowerDebugPanel();
}

async function refreshAdminSession() {
  if (!state.supabaseUser) {
    state.adminAuthenticated = false;
    state.adminUser = null;
    syncSpecialBadgesToProfile();
    updateAdminControls();
    return;
  }
  try {
    const response = await fetch("/api/auth/session", { credentials: "same-origin" });
    const payload = await response.json().catch(() => ({}));
    state.adminAuthenticated = Boolean(response.ok && payload.authenticated);
    state.adminUser = state.adminAuthenticated ? payload.user || { role: "admin", name: "Admin" } : null;
  } catch {
    state.adminAuthenticated = false;
    state.adminUser = null;
  }
  syncSpecialBadgesToProfile();
  updateAdminControls();
}

function openAdminAuthModal(message = "") {
  buildAdminAuthModal();
  elements.adminAuthStatus.textContent = message || "Use the private ADMIN_TOKEN from Vercel. This unlocks local browser access only for this session.";
  elements.adminTokenInput.value = "";
  setHidden(elements.adminAuthModal, false);
  window.setTimeout(() => elements.adminTokenInput.focus(), 0);
}

function closeAdminAuthModal() {
  if (!elements.adminAuthModal) {
    return;
  }
  hideModalWithMotion(elements.adminAuthModal);
}

async function submitAdminLogin(event) {
  event.preventDefault();
  const token = elements.adminTokenInput.value.trim();
  if (!token) {
    elements.adminAuthStatus.textContent = "Paste your ADMIN_TOKEN first.";
    playSound("error");
    return;
  }

  try {
    elements.adminAuthStatus.textContent = "Checking admin access...";
    const response = await fetch("/api/auth/admin/login", {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ token })
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) {
      throw new Error(payload.error || `Admin login failed with status ${response.status}.`);
    }
    state.adminAuthenticated = true;
    state.adminUser = payload.user || { role: "admin", name: "Admin" };
    syncSpecialBadgesToProfile();
    updateAdminControls();
    closeAdminAuthModal();
    openDevToolScreen("questions");
  } catch (error) {
    console.warn(error);
    state.adminAuthenticated = false;
    state.adminUser = null;
    updateAdminControls();
    elements.adminAuthStatus.textContent = error.message || "Admin login failed.";
    playSound("error");
  }
}

async function logoutAdmin(options = {}) {
  try {
    await fetch("/api/auth/logout", {
      method: "POST",
      credentials: "same-origin"
    });
  } catch (error) {
    console.warn(error);
  }
  state.adminAuthenticated = false;
  state.adminUser = null;
  syncSpecialBadgesToProfile();
  updateAdminControls();
  if (!options.silent) {
    if (elements.devToolScreen) {
      setHidden(elements.devToolScreen, true);
    }
    setHidden(elements.modeScreen, false);
    playSound("click");
  }
}

async function handleDevToolButtonClick() {
  await refreshAdminSession();
  if (!state.adminAuthenticated) {
    openAdminAuthModal("Sign in as admin before using the Dev Tool.");
    return;
  }
  openDevToolScreen("questions");
}

async function closeDevToolScreen() {
  if (getCurrentDevToolTab() === "create" && !(await confirmDiscardDevCreateProgress())) {
    return;
  }
  if (getCurrentDevToolTab() === "create") {
    resetDevQuestionCreateForm({ keepStatus: false });
  }
  playSound("click");
  clearStatFlashes();
  setHidden(elements.devToolScreen, true);
  setHidden(elements.modeScreen, false);
}

async function loadQuestionDebugBank(force = false) {
  if (state.questionDebugBank.length && !force) {
    filterQuestionDebugBank();
    return;
  }

  try {
    ensureServerMode();
    elements.devQuestionStatus.textContent = "Loading question bank...";
    const response = await fetch("/api/debug/questions", { credentials: "same-origin" });
    if (response.status === 401) {
      state.adminAuthenticated = false;
      state.adminUser = null;
      updateAdminControls();
      openAdminAuthModal("Your admin session expired. Sign in again to load Dev Tool data.");
    }
    if (!response.ok) {
      const error = await response.json().catch(() => ({}));
      throw new Error(error.error || `Question debug failed with status ${response.status}.`);
    }
    const payload = await response.json();
    state.questionDebugBank = Array.isArray(payload.questions) ? payload.questions : [];
    state.questionDebugThemes = Array.isArray(payload.themes) ? payload.themes : triviaThemes;
    renderQuestionDebugCounts(payload.counts || {});
    filterQuestionDebugBank();
  } catch (error) {
    console.warn(error);
    elements.devQuestionStatus.textContent = error.message || "Could not load question bank.";
    playSound("error");
  }
}

function getQuestionDebugPassedIds() {
  try {
    const stored = JSON.parse(window.localStorage.getItem(QUESTION_DEBUG_PASSED_IDS_KEY) || "[]");
    return new Set(Array.isArray(stored) ? stored.map((id) => String(id || "").trim()).filter(Boolean) : []);
  } catch (error) {
    console.warn("Could not read passed question debug state:", error);
    return new Set();
  }
}

function saveQuestionDebugPassedIds(ids) {
  try {
    window.localStorage.setItem(QUESTION_DEBUG_PASSED_IDS_KEY, JSON.stringify([...ids].slice(-5000)));
    return true;
  } catch (error) {
    console.warn("Could not save passed question debug state:", error);
    return false;
  }
}

function isQuestionDebugNew(question, passedIds = getQuestionDebugPassedIds()) {
  return Boolean(question?.debugBatch) && !passedIds.has(String(question.id || ""));
}

function updateQuestionDebugPassButton() {
  if (!elements.devQuestionPassNewButton) {
    return;
  }
  const passedIds = getQuestionDebugPassedIds();
  const count = state.questionDebugBank.filter((question) => isQuestionDebugNew(question, passedIds)).length;
  elements.devQuestionPassNewButton.disabled = count === 0;
  elements.devQuestionPassNewButton.textContent = count ? `Pass New Batch (${count})` : "New Batch Passed";
}

function passNewQuestionBatch() {
  const passedIds = getQuestionDebugPassedIds();
  const newQuestions = state.questionDebugBank.filter((question) => isQuestionDebugNew(question, passedIds));
  if (!newQuestions.length) {
    elements.devQuestionToolsStatus.textContent = "There are no unpassed newly added questions.";
    updateQuestionDebugPassButton();
    return;
  }
  newQuestions.forEach((question) => passedIds.add(String(question.id)));
  if (!saveQuestionDebugPassedIds(passedIds)) {
    elements.devQuestionToolsStatus.textContent = "Could not save the passed-question list in this browser.";
    return;
  }
  elements.devQuestionToolsStatus.textContent = `Passed ${newQuestions.length} newly added question${newQuestions.length === 1 ? "" : "s"}. They are hidden from the Newly added view in this browser.`;
  updateQuestionDebugPassButton();
  filterQuestionDebugBank();
}

function renderQuestionDebugCounts(counts = {}) {
  elements.devQuestionCounts.replaceChildren();
  const selectedTheme = elements.devQuestionThemeFilter?.value || "all";
  const selectedLanguage = elements.devQuestionLanguageFilter?.value || "all";
  const liveCounts = {};
  state.questionDebugBank.forEach((question) => {
    const language = normalizeQuestionLanguage(question.language);
    if (selectedLanguage !== "all" && language !== selectedLanguage) {
      return;
    }
    const bucket = liveCounts[question.theme] || (liveCounts[question.theme] = {
      total: 0,
      image: 0,
      text: 0,
      multipleChoice: 0
    });
    bucket.total += 1;
    bucket[question.type] = (bucket[question.type] || 0) + 1;
    if (question.questionStyle === MULTIPLE_CHOICE_STYLE) {
      bucket.multipleChoice += 1;
    }
  });
  state.questionDebugThemes.forEach((theme) => {
    const count = liveCounts[theme] || counts[theme] || {};
    const item = document.createElement("button");
    item.type = "button";
    item.className = "dev-count-chip";
    item.classList.toggle("selected", selectedTheme === theme);
    item.dataset.theme = theme;
    item.innerHTML = `<strong>${theme}</strong><span>${Number(count.total || 0)} total</span><small>${Number(count.image || 0)} image / ${Number(count.text || 0)} text / ${Number(count.multipleChoice || 0)} MC</small>`;
    item.addEventListener("click", () => {
      elements.devQuestionThemeFilter.value = theme;
      filterQuestionDebugBank();
    });
    elements.devQuestionCounts.appendChild(item);
  });
}

function filterQuestionDebugBank() {
  const query = normalizeTriviaAnswer(elements.devQuestionSearchInput.value);
  const theme = elements.devQuestionThemeFilter.value;
  const type = elements.devQuestionTypeFilter.value;
  const language = elements.devQuestionLanguageFilter?.value || "all";
  const passedIds = getQuestionDebugPassedIds();
  renderQuestionDebugCounts();
  elements.devQuestionCounts.querySelectorAll(".dev-count-chip").forEach((button) => {
    button.classList.toggle("selected", button.dataset.theme === theme);
  });
  state.questionDebugFiltered = state.questionDebugBank.filter((question) => {
    const questionLanguage = normalizeQuestionLanguage(question.language);
    if (theme !== "all" && question.theme !== theme) {
      return false;
    }
    if (language !== "all" && questionLanguage !== language) {
      return false;
    }
    const isMultipleChoice = question.questionStyle === MULTIPLE_CHOICE_STYLE;
    if (type === "image-mcq" && !(question.type === "image" && isMultipleChoice)) {
      return false;
    }
    if (type === "text-mcq" && !(question.type === "text" && isMultipleChoice)) {
      return false;
    }
    if (type === "multiple-choice" && !isMultipleChoice) {
      return false;
    }
    if (type === "newly-added" && !isQuestionDebugNew(question, passedIds)) {
      return false;
    }
    if (type !== "all" && !["image-mcq", "text-mcq", "multiple-choice", "newly-added"].includes(type) && question.type !== type) {
      return false;
    }
    if (!query) {
      return true;
    }
    const haystack = [
      question.id,
      question.theme,
      question.difficulty,
      question.type,
      question.questionStyle,
      questionLanguage,
      question.gradingStrictness,
      question.question,
      question.canonicalAnswer,
      ...(question.acceptedAnswers || []),
      ...(question.botCards || []),
      ...(question.multipleChoiceOptions || []),
      ...(question.rejectedAnswers || []),
      question.image?.url
    ].filter(Boolean).join(" ");
    return normalizeTriviaAnswer(haystack).includes(query);
  });
  state.questionDebugIndex = Math.min(Math.max(0, state.questionDebugIndex), Math.max(0, state.questionDebugFiltered.length - 1));
  updateQuestionDebugPassButton();
  renderQuestionDebugResults();
  renderQuestionDebugPreview();
}

function renderQuestionDebugResults() {
  elements.devQuestionResults.replaceChildren();
  if (!state.questionDebugFiltered.length) {
    const empty = document.createElement("div");
    empty.className = "dev-question-result empty";
    empty.textContent = "No questions match these filters.";
    elements.devQuestionResults.appendChild(empty);
    return;
  }

  state.questionDebugFiltered.slice(0, 80).forEach((question, index) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "dev-question-result";
    button.classList.toggle("selected", index === state.questionDebugIndex);
    button.dataset.questionDebugIndex = String(index);
    const answer = document.createElement("span");
    answer.textContent = question.canonicalAnswer || "-";
    button.dataset.tooltip = `${question.id} - ${question.theme} - ${getQuestionLanguageLabel(question.language)} - ${question.difficulty} - ${question.type}${question.questionStyle === MULTIPLE_CHOICE_STYLE ? " - multiple choice" : ` - ${getGradingStrictnessLabel(question.gradingStrictness)}`}${question.debugBatch ? " - newly added" : ""}`;
    button.append(answer);
    elements.devQuestionResults.appendChild(button);
  });
}

function selectQuestionDebugIndex(index) {
  if (!state.questionDebugFiltered.length) {
    return;
  }
  const total = state.questionDebugFiltered.length;
  state.questionDebugIndex = ((Math.floor(index) % total) + total) % total;
  renderQuestionDebugResults();
  renderQuestionDebugPreview();
}

function renderQuestionDebugPreview() {
  const question = state.questionDebugFiltered[state.questionDebugIndex];
  const total = state.questionDebugFiltered.length;
  elements.devQuestionCounter.textContent = total ? `${state.questionDebugIndex + 1}/${total} shown` : "0 questions";
  elements.devQuestionPrevButton.disabled = total <= 1;
  elements.devQuestionNextButton.disabled = total <= 1;
  elements.devQuestionEditButton.disabled = !question;
  elements.devQuestionDeleteButton.disabled = !question;
  elements.devQuestionMeta.replaceChildren();

  if (!question) {
    elements.devQuestionPreview?.classList.remove("text-only");
    elements.devQuestionText.textContent = "Question preview";
    elements.devQuestionAnswer.textContent = "-";
    elements.devQuestionAccepted.textContent = "Accepted answers appear here.";
    elements.devQuestionRejected.textContent = "Rejected answers appear here.";
    elements.devQuestionStatus.textContent = "No question selected.";
    elements.devQuestionImage.removeAttribute("src");
    setHidden(elements.devQuestionImage, true);
    setHidden(elements.devQuestionPlaceholder, false);
    elements.devQuestionPlaceholder.textContent = "Select a question.";
    elements.devQuestionCredit.textContent = "";
    resetDevQuestionGradingTester("No question selected.");
    resetDevQuestionAiShield("No question selected.");
    renderDevQuestionGradingTester(null);
    return;
  }

  elements.devQuestionPreview?.classList.toggle("text-only", question.type !== "image");
  [
    question.theme,
    getQuestionLanguageLabel(question.language),
    question.type === "image" ? "Image" : "Text",
    question.questionStyle === MULTIPLE_CHOICE_STYLE ? "Multiple choice" : "",
    question.debugBatch ? "New batch" : "",
    question.questionStyle === MULTIPLE_CHOICE_STYLE ? "Exact option" : getGradingStrictnessLabel(question.gradingStrictness),
    normalizeDifficulty(question.difficulty)
  ].filter(Boolean).forEach((text) => {
    const badge = document.createElement("span");
    badge.textContent = text;
    elements.devQuestionMeta.appendChild(badge);
  });
  elements.devQuestionText.textContent = question.question || "Question preview";
  elements.devQuestionAnswer.textContent = question.canonicalAnswer || "-";
  if (question.questionStyle === MULTIPLE_CHOICE_STYLE) {
    elements.devQuestionAccepted.textContent = `Options: ${(question.multipleChoiceOptions || []).join(", ") || "No options listed."}`;
    elements.devQuestionRejected.textContent = "AI grading disabled. Exact option match only.";
  } else {
    elements.devQuestionAccepted.textContent = (question.acceptedAnswers || []).length
      ? `Accepted: ${question.acceptedAnswers.join(", ")}`
      : "No accepted answers listed.";
    elements.devQuestionRejected.textContent = (question.rejectedAnswers || []).length
      ? `Rejected: ${question.rejectedAnswers.join(", ")}`
      : "No explicit rejections listed.";
  }
  elements.devQuestionStatus.textContent = `Seed id: ${question.id}${question.debugBatch ? ` · Batch: ${question.debugBatch}` : ""}`;
  renderDevQuestionImage(question);
  resetDevQuestionGradingTester(question.questionStyle === MULTIPLE_CHOICE_STYLE
    ? "Multiple choice uses exact option marking. Type or click an option to test it."
    : "Enter a player answer, then run marking."
  );
  resetDevQuestionAiShield(question.questionStyle === MULTIPLE_CHOICE_STYLE
    ? "Multiple choice uses exact option marking, so the shield should block AI review."
    : "Enter a player answer, then check the AI shield."
  );
  renderDevQuestionGradingTester(question);
}

function renderDevQuestionImage(question) {
  elements.devQuestionImage.onload = () => {
    setHidden(elements.devQuestionImage, false);
    setHidden(elements.devQuestionPlaceholder, true);
  };
  elements.devQuestionImage.onerror = () => {
    elements.devQuestionPlaceholder.textContent = "Image failed to load.";
    setHidden(elements.devQuestionImage, true);
    setHidden(elements.devQuestionPlaceholder, false);
  };
  elements.devQuestionCredit.textContent = question.image?.credit || "";
  setHidden(elements.devQuestionCredit, !question.image?.credit);
  if (question.type === "image" && question.image?.url) {
    elements.devQuestionImage.alt = question.image.alt || "Trivia image preview";
    elements.devQuestionImage.removeAttribute("src");
    elements.devQuestionPlaceholder.textContent = "Waiting for image...";
    setHidden(elements.devQuestionImage, true);
    setHidden(elements.devQuestionPlaceholder, false);
    elements.devQuestionImage.src = question.image.url;
  } else {
    elements.devQuestionImage.removeAttribute("src");
    elements.devQuestionImage.alt = "";
    elements.devQuestionPlaceholder.textContent = "Text-only question.";
    setHidden(elements.devQuestionImage, true);
    setHidden(elements.devQuestionPlaceholder, false);
  }
}

function getDevQuestionGradeMode(question) {
  if (question?.questionStyle === MULTIPLE_CHOICE_STYLE) {
    return "local";
  }
  const mode = elements.devQuestionGradeMode?.value || "mixed";
  return ["mixed", "local", "force-ai"].includes(mode) ? mode : "mixed";
}

function getDevQuestionGradeModeLabel(mode) {
  switch (mode) {
    case "local":
      return "Non-AI only";
    case "force-ai":
      return "Force AI";
    case "mixed":
    default:
      return "Mixed";
  }
}

function getDevQuestionGradeSourceLabel(source) {
  switch (source) {
    case "model":
      return "AI grader";
    case "local-with-ai-second-opinion":
      return "AI accepted after second look";
    case "local-with-ai-review":
      return "AI reviewed";
    case "local-ai-unavailable":
      return "AI unavailable";
    case "local-ai-failed":
      return "AI failed";
    case "multiple-choice":
      return "Exact option";
    case "local-fallback":
    default:
      return "Local preset grader";
  }
}

function getDevQuestionGradeSummary(result, isCorrect) {
  switch (result?.source) {
    case "model":
      return isCorrect
        ? "AI accepted this answer using the question context."
        : "AI rejected this answer using the question context.";
    case "local-with-ai-second-opinion":
      return "The saved answers missed it at first, but AI took a second look and accepted it.";
    case "local-with-ai-review":
      return "AI took a second look and kept it incorrect.";
    case "local-ai-unavailable":
      return "AI grading was requested, but no AI key is available here, so this shows the local result.";
    case "local-ai-failed":
      return "AI grading was requested but failed, so this shows the local result.";
    case "multiple-choice":
      return isCorrect ? "This exactly matches the correct option." : "This does not match the correct option.";
    case "local-fallback":
    default:
      return isCorrect
        ? "This matched the saved answer or accepted aliases."
        : "This did not match the saved answer closely enough.";
  }
}

function resetDevQuestionGradingTester(message = "Pick a question, enter an answer, then run marking.") {
  state.questionDebugGradeRequestId += 1;
  if (!elements.devQuestionGradeStatus || !elements.devQuestionGradeResults) {
    return;
  }
  elements.devQuestionGradeStatus.textContent = message;
  elements.devQuestionGradeResults.replaceChildren();
  if (elements.devQuestionGradeSubmitButton) {
    elements.devQuestionGradeSubmitButton.disabled = !getSelectedDebugQuestion();
  }
}

function renderDevQuestionGradingTester(question) {
  if (!elements.devQuestionGradeMode || !elements.devQuestionGradeOptions || !elements.devQuestionGradeSubmitButton) {
    return;
  }
  const isMultipleChoice = question?.questionStyle === MULTIPLE_CHOICE_STYLE;
  elements.devQuestionGradeMode.disabled = !question || isMultipleChoice;
  if (isMultipleChoice) {
    elements.devQuestionGradeMode.value = "local";
  } else if (!["mixed", "local", "force-ai"].includes(elements.devQuestionGradeMode.value)) {
    elements.devQuestionGradeMode.value = "mixed";
  }
  elements.devQuestionGradeSubmitButton.disabled = !question;
  elements.devQuestionGradeOptions.replaceChildren();
  if (!question) {
    elements.devQuestionGradeAnswer.placeholder = "Select a question first";
    return;
  }
  elements.devQuestionGradeAnswer.placeholder = isMultipleChoice
    ? "Type or click one of the options"
    : "Type an answer exactly like a player would";
  if (!isMultipleChoice) {
    return;
  }
  (question.multipleChoiceOptions || []).forEach((option) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "dev-question-grade-option";
    button.dataset.devGradeOption = option;
    button.textContent = option;
    elements.devQuestionGradeOptions.appendChild(button);
  });
}

function resetDevQuestionAiShield(message = "Pick a question, enter an answer, then check the shield.") {
  state.questionDebugShieldRequestId += 1;
  if (!elements.devQuestionShieldStatus || !elements.devQuestionShieldResults || !elements.devQuestionShieldSubmitButton) {
    return;
  }
  elements.devQuestionShieldStatus.textContent = message;
  elements.devQuestionShieldResults.replaceChildren();
  elements.devQuestionShieldSubmitButton.disabled = !getSelectedDebugQuestion();
}

function buildDevQuestionAiShieldPayload(question, answer) {
  return {
    ...buildDevQuestionGradingPayload(question, answer, "mixed"),
    treatAsBot: Boolean(elements.devQuestionShieldBotToggle?.checked),
    roundSeed: `dev-ai-shield-${question.id || "question"}-${Date.now()}-${Math.random().toString(36).slice(2)}`
  };
}

function renderDevQuestionAiShieldResult(result, question) {
  if (!elements.devQuestionShieldResults || !elements.devQuestionShieldStatus) {
    return;
  }
  const allowed = Boolean(result.wouldAskAi);
  const card = document.createElement("article");
  card.className = "dev-question-shield-result";
  card.dataset.shield = allowed ? "allow" : "block";

  const heading = document.createElement("h4");
  heading.textContent = allowed ? "AI Review Allowed" : "AI Review Blocked";
  const summary = document.createElement("p");
  summary.textContent = result.reason || (allowed
    ? "Mixed grading would send this answer for AI review."
    : "Mixed grading would keep this answer away from AI.");

  const pills = document.createElement("div");
  pills.className = "dev-question-grade-pills";
  pills.append(
    createDevQuestionGradePill(allowed ? "AI can review" : "No AI token", allowed ? "ai" : "local"),
    createDevQuestionGradePill(`${Math.round(Number(result.localScore || 0) * 100)}% local`, "mode"),
    createDevQuestionGradePill(getGradingStrictnessLabel(result.strictness || question.gradingStrictness), "strictness")
  );
  if (result.localCorrect) {
    pills.append(createDevQuestionGradePill("Local already correct", "local"));
  }
  if (result.explicitlyRejected) {
    pills.append(createDevQuestionGradePill("Rejected preset", "local"));
  }
  if (result.treatAsBot) {
    pills.append(createDevQuestionGradePill("Bot skipped", "local"));
  }
  if (!result.aiConfigured && allowed) {
    pills.append(createDevQuestionGradePill(
      "AI key missing",
      "local",
      "The shield allows review, but the server does not currently have a usable AI key."
    ));
  }

  const tested = document.createElement("p");
  tested.className = "dev-question-grade-line";
  tested.textContent = `Tested answer: ${result.answer || "(blank)"}`;
  const normalized = document.createElement("p");
  normalized.className = "dev-question-grade-line";
  normalized.textContent = `Normalized answer: ${result.normalizedAnswer || "(blank)"}`;
  const expected = document.createElement("p");
  expected.className = "dev-question-grade-line";
  expected.textContent = `Saved answer: ${question.canonicalAnswer || "-"}`;
  card.append(heading, summary, pills, tested, normalized, expected);

  if (!result.aiConfigured && allowed) {
    const warning = document.createElement("p");
    warning.className = "dev-question-grade-warning";
    warning.textContent = "This would only call AI after the provider key is configured.";
    card.appendChild(warning);
  }

  const details = document.createElement("details");
  const detailsSummary = document.createElement("summary");
  detailsSummary.textContent = "Raw shield result";
  const raw = document.createElement("pre");
  raw.textContent = JSON.stringify({
    shield: result.shield,
    reasonCode: result.reasonCode,
    localScore: result.localScore,
    localThreshold: result.localThreshold,
    localCorrect: result.localCorrect,
    explicitlyRejected: result.explicitlyRejected,
    treatAsBot: result.treatAsBot,
    wouldAskAi: result.wouldAskAi,
    aiConfigured: result.aiConfigured,
    details: result.details || {}
  }, null, 2);
  details.append(detailsSummary, raw);
  card.appendChild(details);

  elements.devQuestionShieldResults.replaceChildren(card);
  elements.devQuestionShieldStatus.textContent = allowed
    ? "Mixed grading would ask AI for this player answer."
    : "Mixed grading would not spend AI on this answer.";
}

async function submitDevQuestionAiShieldTest() {
  const question = getSelectedDebugQuestion();
  if (!question) {
    resetDevQuestionAiShield("Select a question before checking the shield.");
    playSound("error");
    return;
  }
  const answer = String(elements.devQuestionGradeAnswer.value || "").trim();
  const requestId = state.questionDebugShieldRequestId + 1;
  state.questionDebugShieldRequestId = requestId;
  elements.devQuestionShieldSubmitButton.disabled = true;
  elements.devQuestionShieldStatus.textContent = "Checking AI shield...";
  elements.devQuestionShieldResults.replaceChildren();

  try {
    ensureServerMode();
    const response = await fetch("/api/debug/ai-shield", {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(buildDevQuestionAiShieldPayload(question, answer))
    });
    const payload = await response.json().catch(() => ({}));
    if (requestId !== state.questionDebugShieldRequestId) {
      return;
    }
    if (!response.ok) {
      if (response.status === 401) {
        state.adminAuthenticated = false;
        state.adminUser = null;
        updateAdminControls();
        openAdminAuthModal("Your admin session expired. Sign in again to test the AI shield.");
      }
      throw new Error(payload.error || `AI shield test failed with status ${response.status}.`);
    }
    renderDevQuestionAiShieldResult(payload, question);
    playSound("click");
  } catch (error) {
    console.warn(error);
    if (requestId === state.questionDebugShieldRequestId) {
      elements.devQuestionShieldStatus.textContent = error.message || "Could not check the AI shield.";
      elements.devQuestionShieldResults.replaceChildren();
      playSound("error");
    }
  } finally {
    if (requestId === state.questionDebugShieldRequestId) {
      elements.devQuestionShieldSubmitButton.disabled = !getSelectedDebugQuestion();
    }
  }
}

function pickDevQuestionControlAnswer(question, testedAnswer = "") {
  const blocked = new Set([
    testedAnswer,
    question?.canonicalAnswer,
    ...(question?.acceptedAnswers || [])
  ].map(normalizeTriviaAnswer).filter(Boolean));
  const candidates = [
    ...(question?.rejectedAnswers || []),
    ...(question?.botCards || []),
    ...(question?.multipleChoiceOptions || []),
    "Clearly wrong answer",
    "I don't know"
  ];
  return candidates.find((candidate) => {
    const normalized = normalizeTriviaAnswer(candidate);
    return normalized && !blocked.has(normalized);
  }) || "Clearly wrong answer";
}

function buildDevQuestionGradingPayload(question, answer, gradingMode) {
  const isMultipleChoice = question.questionStyle === MULTIPLE_CHOICE_STYLE;
  return {
    answer,
    blackCard: question.question,
    triviaTheme: question.theme,
    canonicalAnswer: question.canonicalAnswer,
    acceptedAnswers: isMultipleChoice
      ? [question.canonicalAnswer].filter(Boolean)
      : (question.acceptedAnswers || []),
    rejectedAnswers: question.rejectedAnswers || [],
    gradingStrictness: isMultipleChoice ? "exact" : normalizeGradingStrictness(question.gradingStrictness),
    image: question.image || null,
    botCards: [pickDevQuestionControlAnswer(question, answer)],
    botLabels: ["Control"],
    mode: "bots",
    gradingMode: isMultipleChoice ? "local" : gradingMode,
    roundSeed: `dev-grade-${question.id || "question"}-${gradingMode}-${Date.now()}-${Math.random().toString(36).slice(2)}`
  };
}

function createDevQuestionGradePill(text, variant = "", description = "") {
  const pill = document.createElement("span");
  pill.className = "dev-question-grade-pill";
  if (variant) {
    pill.dataset.variant = variant;
  }
  if (description) {
    pill.dataset.description = description;
    pill.tabIndex = 0;
    pill.setAttribute("aria-label", `${text}. ${description}`);
    attachFloatingDescriptionTooltip(pill);
  }
  pill.textContent = text;
  return pill;
}

function getDevQuestionAiPillDescription(source, mode) {
  switch (source) {
    case "model":
      return "AI reviewed this answer directly using the question context.";
    case "local-with-ai-second-opinion":
      return "Local marking rejected this answer first, then AI reviewed it and accepted it.";
    case "local-with-ai-review":
      return "Local marking rejected this answer first, then AI reviewed it and kept it incorrect.";
    case "local-ai-unavailable":
      return "AI grading was requested, but the server could not reach a usable AI model.";
    case "local-ai-failed":
      return "AI grading was requested, but the provider returned an error.";
    default:
      return mode === "force-ai" ? "AI was requested for this answer." : "";
  }
}

function renderDevQuestionGradingResult(result, question, answer, mode) {
  const correctIndexes = Array.isArray(result.correctIndexes) ? result.correctIndexes.map(Number) : [];
  const reviewedIndexes = Array.isArray(result.aiReviewedIndexes) ? result.aiReviewedIndexes.map(Number) : [];
  const isCorrect = correctIndexes.includes(0);
  const displaySource = question.questionStyle === MULTIPLE_CHOICE_STYLE ? "multiple-choice" : result.source;
  const aiFailed = Boolean(result.aiUnavailable)
    || result.source === "local-ai-unavailable"
    || result.source === "local-ai-failed";
  const card = document.createElement("article");
  card.className = "dev-question-grade-result";
  card.dataset.result = isCorrect ? "correct" : "incorrect";

  const heading = document.createElement("h4");
  heading.textContent = aiFailed
    ? `AI Failed - Local ${isCorrect ? "Accepted" : "Rejected"}`
    : isCorrect ? "Accepted" : "Rejected";
  const summary = document.createElement("p");
  summary.textContent = getDevQuestionGradeSummary({ ...result, source: displaySource }, isCorrect);

  const pills = document.createElement("div");
  pills.className = "dev-question-grade-pills";
  const sourceDescription = getDevQuestionAiPillDescription(displaySource, mode);
  pills.append(
    createDevQuestionGradePill(getDevQuestionGradeModeLabel(mode), "mode"),
    createDevQuestionGradePill(
      getDevQuestionGradeSourceLabel(displaySource),
      displaySource?.includes("ai") || displaySource === "model" ? "ai" : "local",
      sourceDescription
    ),
    createDevQuestionGradePill(question.questionStyle === MULTIPLE_CHOICE_STYLE ? "Exact option" : getGradingStrictnessLabel(question.gradingStrictness), "strictness")
  );
  if (reviewedIndexes.includes(0) || result.source === "model") {
    pills.append(createDevQuestionGradePill(
      "Player answer reviewed by AI",
      "ai",
      "AI reviewed this player answer using the trivia question context."
    ));
  }
  if (Array.isArray(result.aiSecondOpinionIndexes) && result.aiSecondOpinionIndexes.includes(0)) {
    pills.append(createDevQuestionGradePill(
      "AI rescued player answer",
      "ai",
      "AI overruled the local preset grader and counted this answer as correct."
    ));
  }

  const tested = document.createElement("p");
  tested.className = "dev-question-grade-line";
  tested.textContent = `Tested answer: ${answer}`;
  const expected = document.createElement("p");
  expected.className = "dev-question-grade-line";
  expected.textContent = `Saved answer: ${question.canonicalAnswer || "-"}`;
  card.append(heading, summary, pills, tested, expected);

  if (result.aiError) {
    const warning = document.createElement("p");
    warning.className = "dev-question-grade-warning";
    warning.textContent = result.aiError;
    card.appendChild(warning);
  }
  if (aiFailed && mode === "force-ai") {
    const warning = document.createElement("p");
    warning.className = "dev-question-grade-warning";
    warning.textContent = "Mixed grading will also rely on local marking until the AI token/provider configuration is fixed.";
    card.appendChild(warning);
  }

  const details = document.createElement("details");
  const detailsSummary = document.createElement("summary");
  detailsSummary.textContent = "Raw result";
  const raw = document.createElement("pre");
  raw.textContent = JSON.stringify({
    source: result.source,
    gradingMode: result.gradingMode || mode,
    correctIndexes: result.correctIndexes || [],
    aiReviewedIndexes: result.aiReviewedIndexes || [],
    aiSecondOpinionIndexes: result.aiSecondOpinionIndexes || [],
    cards: result.cards || []
  }, null, 2);
  details.append(detailsSummary, raw);
  card.appendChild(details);

  elements.devQuestionGradeResults.replaceChildren(card);
  elements.devQuestionGradeStatus.textContent = isCorrect
    ? aiFailed ? "AI failed. Local fallback marked the player answer correct." : "Marked correct for the player answer."
    : aiFailed ? "AI failed. Local fallback marked the player answer incorrect." : "Marked incorrect for the player answer.";
}

async function submitDevQuestionGradingTest() {
  const question = getSelectedDebugQuestion();
  if (!question) {
    resetDevQuestionGradingTester("Select a question before running a marking test.");
    playSound("error");
    return;
  }
  const answer = String(elements.devQuestionGradeAnswer.value || "").trim();
  if (!answer) {
    elements.devQuestionGradeStatus.textContent = "Type an answer first.";
    elements.devQuestionGradeResults.replaceChildren();
    playSound("error");
    return;
  }

  const mode = getDevQuestionGradeMode(question);
  const requestId = state.questionDebugGradeRequestId + 1;
  state.questionDebugGradeRequestId = requestId;
  elements.devQuestionGradeSubmitButton.disabled = true;
  elements.devQuestionGradeStatus.textContent = `Checking with ${getDevQuestionGradeModeLabel(mode).toLowerCase()}...`;
  elements.devQuestionGradeResults.replaceChildren();

  try {
    ensureServerMode();
    const response = await fetch("/api/round", {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(buildDevQuestionGradingPayload(question, answer, mode))
    });
    const payload = await response.json().catch(() => ({}));
    if (requestId !== state.questionDebugGradeRequestId) {
      return;
    }
    if (!response.ok) {
      throw new Error(payload.error || `Marking test failed with status ${response.status}.`);
    }
    renderDevQuestionGradingResult(payload, question, answer, mode);
    playSound("submit");
  } catch (error) {
    console.warn(error);
    if (requestId === state.questionDebugGradeRequestId) {
      elements.devQuestionGradeStatus.textContent = error.message || "Could not run marking test.";
      elements.devQuestionGradeResults.replaceChildren();
      playSound("error");
    }
  } finally {
    if (requestId === state.questionDebugGradeRequestId) {
      elements.devQuestionGradeSubmitButton.disabled = !getSelectedDebugQuestion();
    }
  }
}

function clearQuestionToolSelection(selectedButton) {
  [
    elements.devQuestionFindDuplicatesButton,
    elements.devQuestionCheckImagesButton,
    elements.devQuestionLeastSeenButton,
    elements.devQuestionMostRepeatedButton
  ].forEach((button) => button?.classList.toggle("selected", button === selectedButton));
}

function getQuestionToolLabel(question) {
  return question?.canonicalAnswer || question?.id || "Question";
}

function createQuestionToolItem(question, metaText, detailText = "") {
  const item = document.createElement("article");
  item.className = "dev-question-tool-item";
  const top = document.createElement("div");
  const title = document.createElement("strong");
  title.textContent = getQuestionToolLabel(question);
  const meta = document.createElement("span");
  meta.textContent = metaText;
  top.append(title, meta);
  const detail = document.createElement("p");
  detail.textContent = detailText || question?.question || question?.id || "";
  const action = document.createElement("button");
  action.type = "button";
  action.className = "icon-button";
  action.dataset.questionToolFocus = question?.id || "";
  action.disabled = !question?.id;
  action.textContent = "View";
  item.append(top, detail, action);
  return item;
}

function getDuplicateQuestionGroups() {
  const groups = new Map();
  state.questionDebugBank.forEach((question) => {
    const questionKey = normalizePromptText(question.question);
    const answerKey = normalizePromptText(question.canonicalAnswer);
    const imageKey = String(question.image?.url || "").trim().toLowerCase();
    [
      questionKey ? `Question: ${questionKey}` : "",
      answerKey ? `Answer: ${answerKey}` : "",
      imageKey ? `Image URL: ${imageKey}` : ""
    ].filter(Boolean).forEach((key) => {
      if (!groups.has(key)) {
        groups.set(key, []);
      }
      groups.get(key).push(question);
    });
  });
  return [...groups.entries()]
    .map(([key, questions]) => ({ key, questions }))
    .filter((group) => group.questions.length > 1)
    .sort((a, b) => b.questions.length - a.questions.length || a.key.localeCompare(b.key));
}

function renderDuplicateQuestionReport() {
  clearQuestionToolSelection(elements.devQuestionFindDuplicatesButton);
  const groups = getDuplicateQuestionGroups();
  elements.devQuestionToolsResults.replaceChildren();
  if (!groups.length) {
    elements.devQuestionToolsStatus.textContent = "No obvious duplicate questions, answers, or image URLs found.";
    return;
  }
  groups.slice(0, 24).forEach((group) => {
    const card = document.createElement("article");
    card.className = "dev-question-tool-group";
    const heading = document.createElement("h3");
    heading.textContent = `${group.questions.length} matches · ${group.key.split(":")[0]}`;
    const detail = document.createElement("p");
    detail.textContent = group.key.replace(/^[^:]+:\s*/, "");
    const list = document.createElement("div");
    list.className = "dev-question-tool-mini-list";
    group.questions.forEach((question) => {
      list.appendChild(createQuestionToolItem(question, `${question.theme} · ${question.difficulty}`, question.id));
    });
    card.append(heading, detail, list);
    elements.devQuestionToolsResults.appendChild(card);
  });
  elements.devQuestionToolsStatus.textContent = `${groups.length} possible duplicate group${groups.length === 1 ? "" : "s"} found. Showing top ${Math.min(groups.length, 24)}.`;
}

function getQuestionUsageCount(question, usage = loadQuestionUsageStats()) {
  const key = getQuestionUsageKey(question);
  return Math.max(0, Number(usage[key]?.count) || 0);
}

function renderQuestionUsageReport(mode) {
  const usage = loadQuestionUsageStats();
  const rows = [...state.questionDebugBank]
    .map((question) => ({ question, count: getQuestionUsageCount(question, usage) }))
    .sort((a, b) => mode === "most"
      ? b.count - a.count || String(a.question.id || "").localeCompare(String(b.question.id || ""))
      : a.count - b.count || String(a.question.id || "").localeCompare(String(b.question.id || "")));
  clearQuestionToolSelection(mode === "most" ? elements.devQuestionMostRepeatedButton : elements.devQuestionLeastSeenButton);
  elements.devQuestionToolsResults.replaceChildren();
  rows.slice(0, 30).forEach(({ question, count }) => {
    elements.devQuestionToolsResults.appendChild(createQuestionToolItem(
      question,
      `${count.toLocaleString()} appearance${count === 1 ? "" : "s"} · ${question.theme}`,
      question.question
    ));
  });
  elements.devQuestionToolsStatus.textContent = `${mode === "most" ? "Most repeated" : "Least seen"} questions shown from local play history. New or unplayed questions show 0.`;
}

async function checkImageUrl(question) {
  const url = String(question.image?.url || "").trim();
  if (question.type !== "image" || !url) {
    return { question, ok: false, skipped: true, reason: "No image URL" };
  }
  try {
    ensureServerMode();
    const response = await fetch(`/api/image?src=${encodeURIComponent(url)}`, { cache: "no-store" });
    return {
      question,
      ok: response.ok,
      reason: response.ok ? "OK" : `HTTP ${response.status}`
    };
  } catch (error) {
    return { question, ok: false, reason: error.message || "Image check failed" };
  }
}

async function checkQuestionImageUrls() {
  clearQuestionToolSelection(elements.devQuestionCheckImagesButton);
  const imageQuestions = state.questionDebugBank.filter((question) => question.type === "image");
  elements.devQuestionToolsResults.replaceChildren();
  if (!imageQuestions.length) {
    elements.devQuestionToolsStatus.textContent = "No image questions found.";
    return;
  }
  elements.devQuestionCheckImagesButton.disabled = true;
  const issues = [];
  let checked = 0;
  elements.devQuestionToolsStatus.textContent = `Checking 0/${imageQuestions.length} image URLs...`;
  for (const question of imageQuestions) {
    const result = await checkImageUrl(question);
    checked += 1;
    if (!result.ok) {
      issues.push(result);
    }
    elements.devQuestionToolsStatus.textContent = `Checking ${checked}/${imageQuestions.length} image URLs... ${issues.length} issue${issues.length === 1 ? "" : "s"} found.`;
  }
  elements.devQuestionCheckImagesButton.disabled = false;
  state.questionDebugImageIssues = issues;
  if (!issues.length) {
    elements.devQuestionToolsStatus.textContent = `All ${imageQuestions.length} image URLs loaded through the proxy.`;
    return;
  }
  issues.forEach((issue) => {
    elements.devQuestionToolsResults.appendChild(createQuestionToolItem(
      issue.question,
      `${issue.reason} · ${issue.question.theme}`,
      issue.question.image?.url || issue.question.id
    ));
  });
  elements.devQuestionToolsStatus.textContent = `${issues.length}/${imageQuestions.length} image question${issues.length === 1 ? "" : "s"} need attention.`;
}

function getSelectedDebugQuestion() {
  return state.questionDebugFiltered[state.questionDebugIndex] || null;
}

function getThemeIdPrefix(theme) {
  const prefixes = {
    "Pop Culture": "popculture",
    "Gaming and Geek Culture": "gaming",
    "Geo and History": "geohistory",
    "Animals": "animals",
    "Food and Drinks": "fooddrinks",
    "Sports": "sports",
    "Internet Culture": "internet",
    "Science": "science",
    "Mythology": "mythology",
    "Art and Music": "artmusic"
  };
  return prefixes[theme] || normalizeTriviaAnswer(theme).replace(/\s+/g, "");
}

function getKnownThemeIdPrefixes() {
  return new Set(triviaThemes.map(getThemeIdPrefix));
}

function getQuestionLanguageIdPrefix(language) {
  return questionLanguages[normalizeQuestionLanguage(language)]?.idPrefix || "";
}

function getDevQuestionIdPrefix(theme, language = elements.devCreateLanguage?.value || "en") {
  const languagePrefix = getQuestionLanguageIdPrefix(language);
  return [languagePrefix, getThemeIdPrefix(theme)].filter(Boolean).join("-");
}

function formatDevQuestionId(value, options = {}) {
  const keepTrailingDash = Boolean(options.keepTrailingDash);
  const formatted = String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+/g, "")
    .replace(/-{2,}/g, "-")
    .slice(0, 120);
  return keepTrailingDash ? formatted : formatted.replace(/-+$/g, "");
}

function getFormattedPrefixLength(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+/g, "")
    .replace(/-{2,}/g, "-")
    .slice(0, 120)
    .length;
}

function normalizeDevCreateIdInput() {
  const input = elements.devCreateId;
  const before = input.value;
  const cursor = input.selectionStart ?? before.length;
  const formatted = formatDevQuestionId(before, { keepTrailingDash: true });
  if (before === formatted) {
    return;
  }
  const nextCursor = getFormattedPrefixLength(before.slice(0, cursor));
  input.value = formatted;
  input.setSelectionRange(nextCursor, nextCursor);
}

function syncDevCreateIdPrefix() {
  const prefix = getDevQuestionIdPrefix(elements.devCreateTheme.value, elements.devCreateLanguage?.value);
  const current = formatDevQuestionId(elements.devCreateId.value);
  const parts = current.split("-");
  const knownPrefixes = getKnownThemeIdPrefixes();
  const knownLanguagePrefixes = new Set(Object.values(questionLanguages).map((entry) => entry.idPrefix).filter(Boolean));
  let suffix = "";
  if (current && parts.length > 1) {
    const withoutLanguage = knownLanguagePrefixes.has(parts[0]) ? parts.slice(1) : parts;
    suffix = knownPrefixes.has(withoutLanguage[0]) ? withoutLanguage.slice(1).join("-") : withoutLanguage.join("-");
  } else if (current && !knownPrefixes.has(current)) {
    suffix = current;
  }
  elements.devCreateId.value = suffix ? `${prefix}-${suffix}` : `${prefix}-`;
}

function getCurrentDevCreateIdPrefixValue() {
  return `${getDevQuestionIdPrefix(elements.devCreateTheme.value, elements.devCreateLanguage?.value)}-`;
}

function isDevCreateIdOnlyThemePrefix() {
  return formatDevQuestionId(elements.devCreateId.value, { keepTrailingDash: true }) === getCurrentDevCreateIdPrefixValue();
}

function hasDevCreateFormProgress() {
  return Boolean(
    state.questionEditOriginalId
    || (elements.devCreateId.value.trim() && !isDevCreateIdOnlyThemePrefix())
    || elements.devCreateQuestion.value.trim()
    || elements.devCreateCanonical.value.trim()
    || elements.devCreateAccepted.value.trim()
    || elements.devCreateBots.value.trim()
    || elements.devCreateRejected.value.trim()
    || elements.devCreateImageUrl.value.trim()
    || elements.devCreateImageAlt.value.trim()
    || elements.devCreateImageCredit.value.trim()
  );
}

async function confirmDiscardDevCreateProgress() {
  if (!hasDevCreateFormProgress()) {
    return true;
  }
  return showAppConfirm({
    eyebrow: state.questionEditOriginalId ? "Exit edit" : "Discard draft",
    title: "Discard unsaved changes?",
    copy: "Your current question edits are not saved yet. Leaving now will lose the changes on this form.",
    confirmLabel: "Discard",
    danger: true
  });
}

function resetDevQuestionCreateForm(options = {}) {
  const keepStatus = Boolean(options.keepStatus);
  state.questionEditOriginalId = "";
  state.questionEditReturnId = "";
  elements.devQuestionCreateForm.reset();
  syncDevCreateIdPrefix();
  updateDevCreateImageFields();
  setHidden(elements.devCreateExitButton, true);
  if (!keepStatus) {
    elements.devCreateStatus.textContent = "Ready. Created questions are saved to the persistent question bank.";
  }
  updateDevCreatePreview();
}

function updateDevCreatePreview() {
  if (!elements.devCreatePreview) {
    return;
  }
  const type = elements.devCreateType.value === "image" ? "image" : "text";
  const style = elements.devCreateQuestionStyle?.value === MULTIPLE_CHOICE_STYLE ? MULTIPLE_CHOICE_STYLE : "standard";
  const language = normalizeQuestionLanguage(elements.devCreateLanguage?.value);
  const theme = elements.devCreateTheme.value || "Theme";
  const difficulty = normalizeDifficulty(elements.devCreateDifficulty.value);
  const question = elements.devCreateQuestion.value.trim() || "Question preview";
  const imageUrl = elements.devCreateImageUrl.value.trim();
  const imageAlt = elements.devCreateImageAlt.value.trim() || "Question image preview";
  const imageCredit = elements.devCreateImageCredit.value.trim();

  elements.devCreatePreview.classList.toggle("text-only", type !== "image");
  elements.devCreatePreviewMeta.replaceChildren();
  [theme, getQuestionLanguageLabel(language), type === "image" ? "Image" : "Text", style === MULTIPLE_CHOICE_STYLE ? "Multiple choice" : getGradingStrictnessLabel(elements.devCreateStrictness?.value), difficulty].filter(Boolean).forEach((text) => {
    const badge = document.createElement("span");
    badge.textContent = text;
    elements.devCreatePreviewMeta.appendChild(badge);
  });

  elements.devCreatePreviewQuestion.textContent = question;
  elements.devCreatePreviewCredit.textContent = imageCredit;
  setHidden(elements.devCreatePreviewCredit, !imageCredit);
  elements.devCreatePreviewImage.onload = () => {
    setHidden(elements.devCreatePreviewImage, false);
    setHidden(elements.devCreatePreviewPlaceholder, true);
  };
  elements.devCreatePreviewImage.onerror = () => {
    elements.devCreatePreviewPlaceholder.textContent = "Image failed to load.";
    setHidden(elements.devCreatePreviewImage, true);
    setHidden(elements.devCreatePreviewPlaceholder, false);
  };

  if (type === "image" && imageUrl) {
    elements.devCreatePreviewImage.alt = imageAlt;
    if (elements.devCreatePreviewImage.dataset.previewUrl !== imageUrl) {
      elements.devCreatePreviewImage.dataset.previewUrl = imageUrl;
      elements.devCreatePreviewImage.removeAttribute("src");
      elements.devCreatePreviewPlaceholder.textContent = "Loading image...";
      setHidden(elements.devCreatePreviewImage, true);
      setHidden(elements.devCreatePreviewPlaceholder, false);
      elements.devCreatePreviewImage.src = imageUrl;
    }
  } else {
    elements.devCreatePreviewImage.removeAttribute("src");
    delete elements.devCreatePreviewImage.dataset.previewUrl;
    elements.devCreatePreviewImage.alt = "";
    elements.devCreatePreviewPlaceholder.textContent = type === "image" ? "Image URL preview" : "Text-only question";
    setHidden(elements.devCreatePreviewImage, true);
    setHidden(elements.devCreatePreviewPlaceholder, type === "image");
  }
}

function focusQuestionDebugById(id) {
  const question = state.questionDebugBank.find((entry) => entry.id === id);
  if (question) {
    elements.devQuestionThemeFilter.value = question.theme || "all";
    elements.devQuestionTypeFilter.value = "all";
    if (elements.devQuestionLanguageFilter) {
      elements.devQuestionLanguageFilter.value = normalizeQuestionLanguage(question.language);
    }
  }
  filterQuestionDebugBank();
  let index = state.questionDebugFiltered.findIndex((entry) => entry.id === id);
  if (index < 0 && elements.devQuestionSearchInput.value) {
    elements.devQuestionSearchInput.value = "";
    filterQuestionDebugBank();
    index = state.questionDebugFiltered.findIndex((entry) => entry.id === id);
  }
  if (index >= 0) {
    selectQuestionDebugIndex(index);
  }
}

async function exitDevQuestionEdit() {
  const returnId = state.questionEditReturnId || state.questionEditOriginalId;
  if (!(await confirmDiscardDevCreateProgress())) {
    return;
  }
  resetDevQuestionCreateForm({ keepStatus: false });
  setDevToolTab("questions");
  if (returnId) {
    focusQuestionDebugById(returnId);
  }
  playSound("click");
}

async function clearDevQuestionCreateFormWithConfirm() {
  if (!hasDevCreateFormProgress()) {
    return;
  }
  const confirmed = await showAppConfirm({
    eyebrow: "Clear form",
    title: "Clear every field?",
    copy: "This removes everything currently entered on the question form.",
    confirmLabel: "Clear",
    danger: true
  });
  if (!confirmed) {
    return;
  }
  elements.devQuestionCreateForm.reset();
  syncDevCreateIdPrefix();
  updateDevCreateImageFields();
  elements.devCreateStatus.textContent = state.questionEditOriginalId
    ? `Editing ${state.questionEditOriginalId}. Save will overwrite the original question.`
    : "Question form cleared.";
  updateDevCreatePreview();
  playSound("click");
}

function startEditingDebugQuestion() {
  const question = getSelectedDebugQuestion();
  if (!question) {
    return;
  }
  state.questionEditOriginalId = question.id;
  state.questionEditReturnId = question.id;
  elements.devCreateTheme.value = question.theme || triviaThemes[0];
  elements.devCreateDifficulty.value = normalizeDifficulty(question.difficulty);
  elements.devCreateType.value = question.type === "image" ? "image" : "text";
  elements.devCreateQuestionStyle.value = question.questionStyle === MULTIPLE_CHOICE_STYLE ? MULTIPLE_CHOICE_STYLE : "standard";
  elements.devCreateLanguage.value = normalizeQuestionLanguage(question.language);
  elements.devCreateStrictness.value = normalizeGradingStrictness(question.gradingStrictness);
  elements.devCreateId.value = question.id || "";
  elements.devCreateQuestion.value = question.question || "";
  elements.devCreateCanonical.value = question.canonicalAnswer || "";
  elements.devCreateAccepted.value = (question.acceptedAnswers || []).join(", ");
  elements.devCreateBots.value = question.questionStyle === MULTIPLE_CHOICE_STYLE
    ? (question.multipleChoiceOptions || []).filter((answer) => normalizeMultipleChoiceOption(answer) !== normalizeMultipleChoiceOption(question.canonicalAnswer)).join(", ")
    : (question.botCards || []).join(", ");
  elements.devCreateRejected.value = (question.rejectedAnswers || []).join(", ");
  elements.devCreateImageUrl.value = question.image?.url || "";
  elements.devCreateImageAlt.value = question.image?.alt || "";
  elements.devCreateImageCredit.value = question.image?.credit || "";
  updateDevCreateImageFields();
  setHidden(elements.devCreateExitButton, false);
  elements.devCreateStatus.textContent = `Editing ${question.id}. Save will overwrite the original question.`;
  setDevToolTab("create");
  playSound("click");
}

async function deleteSelectedDebugQuestion() {
  const question = getSelectedDebugQuestion();
  if (!question) {
    return;
  }
  const confirmed = await showAppConfirm({
    eyebrow: "Delete question",
    title: `Delete ${question.id}?`,
    copy: "This permanently removes the question from the persistent question bank.",
    confirmLabel: "Delete",
    danger: true
  });
  if (!confirmed) {
    return;
  }

  try {
    ensureServerMode();
    elements.devQuestionStatus.textContent = `Deleting ${question.id}...`;
    const response = await fetch(`/api/debug/questions/${encodeURIComponent(question.id)}`, {
      method: "DELETE",
      credentials: "same-origin"
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok) {
      throw new Error(result.error || `Delete failed with status ${response.status}.`);
    }
    elements.devQuestionStatus.textContent = `Deleted ${result.question?.id || question.id}. Bank total: ${result.total}.`;
    state.questionEditOriginalId = "";
    state.questionEditReturnId = "";
    state.questionDebugBank = [];
    await loadQuestionDebugBank(true);
    playSound("reveal");
  } catch (error) {
    console.warn(error);
    elements.devQuestionStatus.textContent = error.message || "Could not delete question.";
    playSound("error");
  }
}

function updateDevCreateImageFields() {
  const isImage = elements.devCreateType.value === "image";
  const isMultipleChoice = elements.devCreateQuestionStyle?.value === MULTIPLE_CHOICE_STYLE;
  setHidden(elements.devCreateImageFields, !isImage);
  elements.devCreateImageUrl.required = isImage;
  syncQuestionCreateAnswerFields({
    form: elements.devQuestionCreateForm,
    acceptedWrap: elements.devCreateAcceptedWrap,
    rejectedWrap: elements.devCreateRejectedWrap,
    acceptedInput: elements.devCreateAccepted,
    rejectedInput: elements.devCreateRejected,
    canonicalInput: elements.devCreateCanonical,
    botsWrap: elements.devCreateBotsWrap,
    strictnessInput: elements.devCreateStrictness,
    isMultipleChoice,
    standardCanonicalLabel: "Answer",
    standardBotsLabel: "Bot answers"
  });
  elements.devCreateBots.placeholder = isMultipleChoice ? "wrong one, wrong two, wrong three" : "wrong one, wrong two";
  if (elements.devCreateSubmitButton) {
    elements.devCreateSubmitButton.textContent = state.questionEditOriginalId ? "Save Question" : "Create Question";
  }
  if (elements.devCreateSaveAsNewButton) {
    setHidden(elements.devCreateSaveAsNewButton, !state.questionEditOriginalId);
  }
  if (elements.devCreateExitButton) {
    setHidden(elements.devCreateExitButton, !state.questionEditOriginalId);
  }
  updateDevCreatePreview();
}

function parseCommaSeparatedAnswers(value) {
  return String(value || "")
    .split(",")
    .map((answer) => answer.trim())
    .filter(Boolean);
}

function getMultipleChoiceDraftOptions(correctAnswer, wrongAnswers) {
  const correct = cleanInput(correctAnswer || "");
  const correctKey = normalizeMultipleChoiceOption(correct);
  const wrong = [];
  const seen = new Set();
  (wrongAnswers || []).forEach((answer) => {
    const cleaned = cleanInput(answer || "");
    const key = normalizeMultipleChoiceOption(cleaned);
    if (!cleaned || !key || key === correctKey || seen.has(key)) {
      return;
    }
    seen.add(key);
    wrong.push(cleaned);
  });
  return correct ? [correct, ...wrong] : [];
}

function validateMultipleChoiceDraft(correctAnswer, wrongAnswers, input, statusElement) {
  if (!input) {
    return true;
  }
  const correct = cleanInput(correctAnswer || "");
  const parsedWrongAnswers = (wrongAnswers || []).map((answer) => cleanInput(answer || "")).filter(Boolean);
  const options = getMultipleChoiceDraftOptions(correctAnswer, parsedWrongAnswers);
  const valid = Boolean(correct) && parsedWrongAnswers.length === 3 && options.length === 4;
  const message = !correct
    ? "Enter one correct answer for this multiple-choice question."
    : parsedWrongAnswers.length !== 3
      ? "Enter exactly three incorrect answers separated by commas."
      : "Incorrect answers must be unique and different from the correct answer.";
  input.setCustomValidity(valid ? "" : message);
  if (!valid) {
    input.reportValidity();
    if (statusElement) {
      statusElement.textContent = `${message} Multiple-choice saves require 1 correct answer and exactly 3 incorrect answers.`;
    }
    playSound("error");
  }
  return valid;
}

function validateDevCreateId(payload) {
  const prefix = `${getDevQuestionIdPrefix(payload.theme, payload.language)}-`;
  const id = formatDevQuestionId(payload.id, { keepTrailingDash: true });
  const valid = id.startsWith(prefix) && id.length > prefix.length;
  elements.devCreateId.setCustomValidity(valid ? "" : `Add a short unique ID after ${prefix}.`);
  if (!valid) {
    elements.devCreateId.reportValidity();
    elements.devCreateId.focus();
    elements.devCreateStatus.textContent = `Add a short unique ID after ${prefix} before saving.`;
    playSound("error");
  }
  return valid;
}

function validateQuestionEditorId(input, theme, statusElement, language = "en") {
  const prefix = `${getDevQuestionIdPrefix(theme, language)}-`;
  const id = formatDevQuestionId(input?.value || "", { keepTrailingDash: true });
  const valid = id.startsWith(prefix) && id.length > prefix.length;
  input?.setCustomValidity(valid ? "" : `Add a short unique ID after ${prefix}.`);
  if (!valid) {
    input?.reportValidity();
    input?.focus();
    if (statusElement) {
      statusElement.textContent = `Add a short unique ID after ${prefix} before saving.`;
    }
    playSound("error");
  }
  return valid;
}

function normalizeDevQuestionIdForComparison(id) {
  return normalizePromptText(id).replace(/\s+/g, "-");
}

function getDevQuestionCreatePayload() {
  const editingQuestion = state.questionDebugBank.find((question) => question.id === state.questionEditOriginalId);
  const payload = {
    id: formatDevQuestionId(elements.devCreateId.value),
    type: elements.devCreateType.value,
    questionStyle: elements.devCreateQuestionStyle?.value === MULTIPLE_CHOICE_STYLE ? MULTIPLE_CHOICE_STYLE : "standard",
    language: normalizeQuestionLanguage(elements.devCreateLanguage?.value),
    gradingStrictness: elements.devCreateQuestionStyle?.value === MULTIPLE_CHOICE_STYLE
      ? "exact"
      : normalizeGradingStrictness(elements.devCreateStrictness?.value),
    theme: elements.devCreateTheme.value,
    difficulty: elements.devCreateDifficulty.value,
    ...(editingQuestion?.debugBatch ? { debugBatch: editingQuestion.debugBatch } : {}),
    question: elements.devCreateQuestion.value.trim(),
    canonicalAnswer: elements.devCreateCanonical.value.trim(),
    acceptedAnswers: parseCommaSeparatedAnswers(elements.devCreateAccepted.value),
    botCards: parseCommaSeparatedAnswers(elements.devCreateBots.value),
    rejectedAnswers: parseCommaSeparatedAnswers(elements.devCreateRejected.value)
  };
  if (payload.questionStyle === MULTIPLE_CHOICE_STYLE) {
    const incorrect = parseCommaSeparatedAnswers(elements.devCreateBots.value);
    payload.acceptedAnswers = [];
    payload.botCards = [];
    payload.rejectedAnswers = [];
    payload.multipleChoiceOptions = getMultipleChoiceDraftOptions(payload.canonicalAnswer, incorrect);
  }
  if (payload.type === "image") {
    payload.image = {
      url: elements.devCreateImageUrl.value.trim(),
      alt: elements.devCreateImageAlt.value.trim(),
      credit: elements.devCreateImageCredit.value.trim()
    };
  }
  return payload;
}

function requireNewDevQuestionId(payload) {
  const originalId = state.questionEditOriginalId;
  if (!originalId) {
    return true;
  }
  const sameId = normalizeDevQuestionIdForComparison(payload.id) === normalizeDevQuestionIdForComparison(originalId);
  if (!sameId) {
    elements.devCreateId.setCustomValidity("");
    return true;
  }

  elements.devCreateId.setCustomValidity("Type a new unique ID before saving as a new question.");
  elements.devCreateId.reportValidity();
  elements.devCreateId.focus();
  elements.devCreateId.select();
  elements.devCreateStatus.textContent = "Save as New needs a new ID. Change the ID, then try again.";
  playSound("error");
  window.setTimeout(() => {
    elements.devCreateId.setCustomValidity("");
  }, 0);
  return false;
}

async function saveDevQuestionPayload(options = {}) {
  if (elements.devCreateQuestionStyle?.value === MULTIPLE_CHOICE_STYLE
    && !validateMultipleChoiceDraft(
      elements.devCreateCanonical.value,
      parseCommaSeparatedAnswers(elements.devCreateBots.value),
      elements.devCreateBots,
      elements.devCreateStatus
    )) {
    return;
  }
  const payload = getDevQuestionCreatePayload();
  elements.devCreateId.value = payload.id;
  if (!validateDevCreateId(payload)) {
    return;
  }
  if (options.saveAsNew && !requireNewDevQuestionId(payload)) {
    return;
  }
  try {
    ensureServerMode();
    const editId = options.saveAsNew ? "" : state.questionEditOriginalId;
    const actionLabel = editId ? "Saving" : options.saveAsNew ? "Saving new copy" : "Creating";
    elements.devCreateStatus.textContent = `${actionLabel} ${editId || payload.id}...`;
    const response = await fetch(editId ? `/api/debug/questions/${encodeURIComponent(editId)}` : "/api/debug/questions", {
      method: editId ? "PUT" : "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok) {
      throw new Error(result.error || `${editId ? "Update" : "Create"} failed with status ${response.status}.`);
    }
    const savedId = result.question?.id || payload.id;
    elements.devCreateStatus.textContent = `${editId ? "Updated" : "Created"} ${savedId}. Saved to ${result.storage === "backend" ? "backend storage" : "the question file"}. Bank total: ${result.total}.`;
    resetDevQuestionCreateForm({ keepStatus: true });
    state.questionDebugBank = [];
    await loadQuestionDebugBank(true);
    setDevToolTab("questions");
    focusQuestionDebugById(savedId);
    elements.devQuestionStatus.textContent = `${editId ? "Updated" : "Created"} ${savedId}. Bank total: ${result.total}.`;
    playSound("reveal");
  } catch (error) {
    console.warn(error);
    elements.devCreateStatus.textContent = error.message || "Could not create question.";
    playSound("error");
  }
}

async function submitDevQuestionCreateForm(event) {
  event.preventDefault();
  if (state.questionEditOriginalId) {
    const choice = await showEditSaveChoice();
    if (choice === "overwrite") {
      await saveDevQuestionPayload();
    } else if (choice === "saveAsNew") {
      await saveDevQuestionPayload({ saveAsNew: true });
    }
    return;
  }
  await saveDevQuestionPayload();
}

async function saveEditedQuestionAsNew() {
  if (!state.questionEditOriginalId) {
    return;
  }
  if (!elements.devQuestionCreateForm.reportValidity()) {
    return;
  }
  await saveDevQuestionPayload({ saveAsNew: true });
}

