function prefetchNextSetup() {
  if (isRoomMode() || state.matchEnded || state.round >= state.maxRounds || state.gradingActive || state.nextSetup || state.nextSetupPromise) {
    return;
  }

  const setupVersion = state.setupVersion;
  const matchToken = state.matchWorkToken;
  const questionLanguage = getCurrentQuestionLanguage();
  const promise = requestRoundSetup({ round: state.round + 1, totalRounds: state.maxRounds, questionLanguage });
  state.nextSetupPromise = promise;
  state.nextSetupStatus = "loading";
  promise
    .then((setup) => {
      if (
        state.setupVersion === setupVersion
        && isCurrentMatchWork(matchToken)
        && setupMatchesQuestionLanguage(setup, questionLanguage)
        && !isRepeatedBlackCard(setup)
      ) {
        state.nextSetup = setup;
        state.nextSetupStatus = "ready";
        preloadRoundExperience(setup);
      }
    })
    .catch((error) => {
      if (isAbortError(error)) {
        return;
      }
      if (state.setupVersion === setupVersion) {
        state.nextSetupStatus = "failed";
        console.warn("Next round prefetch failed:", error);
      }
    })
    .finally(() => {
      if (state.setupVersion === setupVersion && state.nextSetupPromise === promise) {
        state.nextSetupPromise = null;
        if (!state.nextSetup && state.nextSetupStatus === "loading") {
          state.nextSetupStatus = "idle";
        }
      }
    });
}

function scheduleNextSetupPrefetch() {
  if (isRoomMode()) {
    return;
  }
  if (state.matchEnded || state.round >= state.maxRounds || state.nextSetup || state.nextSetupPromise) {
    return;
  }
  scheduleWhenIdle(() => {
    if (!state.gradingActive && !state.matchEnded) {
      prefetchNextSetup();
    }
  });
}

function getPendingRoomRoundTransition(round = state.round) {
  const promise = state.roomRoundTransitionPromise;
  const matchId = getCurrentRoomMatchId();
  const key = String(state.roomRoundTransitionKey || "");
  if (
    !promise
    || !matchId
    || !key.endsWith(`|${matchId}|${Number(round) || state.round}`)
  ) {
    return null;
  }
  return promise;
}

async function newRound() {
  const matchToken = state.matchWorkToken;
  const previousBlackCard = state.blackCard;
  clearRoomAutoResolve();
  clearRoomSubmissionResolve();
  state.questionId = "";
  state.blackCard = "";
  state.questionType = "image";
  state.questionStyle = "standard";
  state.questionLanguage = getCurrentQuestionLanguage();
  state.gradingStrictness = "normal";
  state.questionDifficulty = "medium";
  state.triviaTheme = "";
  state.questionImage = null;
  state.canonicalAnswer = "";
  state.acceptedAnswers = [];
  state.judge = null;
  state.botCards = [];
  state.rejectedAnswers = [];
  state.multipleChoiceOptions = [];
  resetPlayedPowersForRound();
  const questionPreferences = {
    ...(state.nextQuestionPreferences || {})
  };
  const preferredTheme = questionPreferences.theme || state.nextPreferredTheme;
  state.nextPreferredTheme = "";
  state.nextQuestionPreferences = { theme: "", difficulty: "", questionStyle: "" };
  const roomSetupContext = createRoundSetupWorkContext({ matchToken });
  const pendingRoomRoundTransition = isRoomMode() && isCurrentHost() && !state.joiningRoom
    ? getPendingRoomRoundTransition(state.round)
    : null;
  if (isRoomMode() && !isCurrentHost()) {
    resetRoundUiForLoading({ resetBlackCardTheme: true });
    showWaitingForHostRoundSetup(state.round);
    try {
      const setup = await waitForSyncedRoomSetupForRound(state.round);
      if (!setup) {
        return;
      }
      if (isCurrentMatchWork(matchToken)) {
        applyRoundSetup(setup);
        applyRoomGamePowerState();
      }
    } catch (error) {
      if (isAbortError(error) || !isCurrentMatchWork(matchToken)) {
        return;
      }
      if (await recoverFromStaleRoomRoundSetup(error, roomSetupContext)) {
        return;
      }
      if (isRoomMode() && !isCurrentHost()) {
        showWaitingForHostRoundSetup(state.round);
        return;
      }
      console.warn(error);
      stopLoadingMessages();
      playSound("error");
      elements.errorText.textContent = `${error.message} Waiting for the host to sync the question bank card.`;
      setHidden(elements.loadingPanel, true);
      setHidden(elements.errorPanel, false);
    }
    return;
  }
  if (isRoomMode() && isCurrentHost() && !state.joiningRoom) {
    resetRoundUiForLoading({ resetBlackCardTheme: true });
    try {
      const setupOptions = {
        ...(preferredTheme ? getThemeSetupOptions(preferredTheme) : {}),
        questionDifficultyPreference: questionPreferences.difficulty || "",
        questionStylePreference: questionPreferences.questionStyle || "",
        round: state.round,
        totalRounds: state.maxRounds
      };
      let setup = getSyncedRoomSetupForRound(state.round);
      if (!setup && pendingRoomRoundTransition) {
        const transitionResult = await pendingRoomRoundTransition;
        if (!transitionResult?.ok) {
          return;
        }
        setup = getSyncedRoomSetupForRound(state.round);
        if (!setup && transitionResult.game?.setup) {
          setup = normalizeSetupPayload(transitionResult.game.setup);
        }
      }
      if (!setup) {
        setup = await requestAuthoritativeRoomRoundSetup(setupOptions);
      }
      if (isCurrentRoundSetupWork(roomSetupContext)) {
        applyRoundSetup(setup, { skipPublish: true });
      }
    } catch (error) {
      if (isAbortError(error) || !isCurrentMatchWork(matchToken)) {
        return;
      }
      if (await recoverFromStaleRoomRoundSetup(error, roomSetupContext)) {
        return;
      }
      console.warn(error);
      if (clearStaleRoundSetupWaitIfPlayable()) {
        return;
      }
      showRoomRoundSetupSyncWait("Waiting for the room to finish syncing this round...");
    }
    return;
  }
  if (preferredTheme || questionPreferences.difficulty || questionPreferences.questionStyle) {
    reserveQuestionSetups([state.nextSetup, ...state.setupStack].filter(Boolean));
    state.setupStack = [];
    state.nextSetup = null;
    state.nextSetupPromise = null;
    state.nextSetupStatus = "idle";
    resetRoundUiForLoading({ resetBlackCardTheme: true });
    try {
      const setup = await requestRoundSetup({
        ...(preferredTheme ? getThemeSetupOptions(preferredTheme) : {}),
        questionDifficultyPreference: questionPreferences.difficulty || "",
        questionStylePreference: questionPreferences.questionStyle || "",
        round: state.round,
        totalRounds: state.maxRounds
      });
      if (isCurrentMatchWork(matchToken)) {
        applyRoundSetup(setup);
      }
    } catch (error) {
      if (isAbortError(error) || !isCurrentMatchWork(matchToken)) {
        return;
      }
      console.warn(error);
      stopLoadingMessages();
      playSound("error");
      elements.errorText.textContent = `${error.message} The question bank could not prepare the next card.`;
      setHidden(elements.loadingPanel, true);
      setHidden(elements.errorPanel, false);
    }
    return;
  }

  const cachedSetup = state.setupStack.length
    ? state.setupStack.shift()
    : takeReservedSetup(getEnabledTriviaThemes(), previousBlackCard, { round: state.round, totalRounds: state.maxRounds }) || state.nextSetup;
  state.nextSetup = null;
  state.nextSetupStatus = "idle";

  if (
    cachedSetup
    && !isRepeatedBlackCard(cachedSetup, previousBlackCard)
    && setupMatchesQuestionLanguage(cachedSetup, getCurrentQuestionLanguage())
    && setupMatchesRoundMultipleChoiceChance(cachedSetup, { round: state.round, totalRounds: state.maxRounds })
  ) {
    resetRoundUiForLoading({ resetBlackCardTheme: true });
    applyRoundSetup(cachedSetup);
    return;
  }

  resetRoundUiForLoading({ resetBlackCardTheme: true });

  try {
    const pendingSetup = state.nextSetupPromise;
    if (pendingSetup) {
      startLoadingMessages("next", "Finishing the next round...");
    }
    let setup = state.setupStack.length
      ? state.setupStack.shift()
      : pendingSetup
        ? await pendingSetup
        : await requestRoundSetup();
    if (
      isRepeatedBlackCard(setup, previousBlackCard)
      || !setupMatchesQuestionLanguage(setup, getCurrentQuestionLanguage())
      || !setupMatchesRoundMultipleChoiceChance(setup, { round: state.round, totalRounds: state.maxRounds })
    ) {
      setup = state.setupStack.length ? state.setupStack.shift() : await requestRoundSetup();
    }
    if (!isCurrentMatchWork(matchToken)) {
      return;
    }
    if (state.nextSetup === setup) {
      state.nextSetup = null;
    }
    applyRoundSetup(setup);
  } catch (error) {
    if (isAbortError(error) || !isCurrentMatchWork(matchToken)) {
      return;
    }
    console.warn(error);
    stopLoadingMessages();
    playSound("error");
    elements.errorText.textContent = `${error.message} The question bank could not prepare the next card.`;
    setHidden(elements.loadingPanel, true);
    setHidden(elements.errorPanel, false);
  }
}

