function returnToRoomLobbyAfterMatch(options = {}) {
  if (options.playSound !== false) {
    playSound("click");
  }
  const sync = options.sync !== false;
  if (sync && isCurrentHost() && !state.joiningRoom) {
    void publishRoomReturnToLobby().then((result) => {
      if (!result?.room) {
        addSystemChat("Could not return the room to lobby. Please try again.", { private: true, sync: false });
      }
    });
  }
  clearRoomMatchScopedStateForLobby();
  state.roomMatchStartGuardUntil = 0;
  state.matchEnded = true;
  state.currentRoomStatus = "lobby";
  state.roomGame = null;
  state.roomRoundResult = null;
  state.roomParticipants = normalizeRoomParticipantsList(
    Array.isArray(options.participants) ? options.participants : getRoomParticipantsFromPlayers("lobby")
  );
  clearRoomParticipantSubmissionState();
  setHidden(elements.gameStage, true);
  setHidden(elements.roomChat, true);
  setHidden(elements.roomScreen, true);
  setHidden(elements.joinScreen, true);
  setHidden(elements.modeScreen, true);
  elements.gameStage.classList.remove("room-active");
  if (sync) {
    const room = state.hostedRooms.find((entry) => entry.code === state.roomSettings.code) || state.joiningRoom;
    renderRoomPlayers();
    if (room) {
      void updateRoomPresence(room, {
        spectator: state.isSpectator,
        status: state.isSpectator ? "spectating" : "joined",
        answer: "",
        submittedRound: 0,
        remainingTime: 0,
        optimisticRealtime: true,
        optimisticEventType: "participant-updated",
        includeRoomSnapshot: true
      });
    }
  }
  renderRoomLobby();
  setRoomInviteUrlPath(state.roomSettings.code);
  startRoomRealtime(state.roomSettings.code);
  startRoomPresenceMaintenance();
  setHidden(elements.roomLobbyScreen, false);
}

elements.changeModeButton.addEventListener("click", () => {
  if (isRoomMode() && !elements.endPanel.classList.contains("hidden")) {
    if (!isCurrentHost() || state.joiningRoom) {
      addSystemChat("Only the host can return everyone to the room.", { private: true, sync: false });
      return;
    }
    returnToRoomLobbyAfterMatch();
    return;
  }
  playSound("click");
  clearRoomAutoResolve();
  stopNextRoundCountdown();
  resetTimerDisplay();
  stopLoadingMessages();
  const leavingActiveMatchEarly = !state.matchEnded && elements.endPanel.classList.contains("hidden");
  state.matchEnded = true;
  if (leavingActiveMatchEarly) {
    discardUnusedQuestionSetups();
  } else {
    stashUnusedQuestionSetups();
  }
  state.nextSetup = null;
  state.nextSetupPromise = null;
  state.nextSetupStatus = "idle";
  state.setupStack = [];
  setHidden(elements.gameStage, true);
  setHidden(elements.roomChat, true);
  elements.gameStage.classList.remove("room-active");
  setHidden(elements.modeScreen, false);
  ensureQuestionReserve({ enabledThemes: state.enabledThemes });
});
